const TICKER_ALIASES = {
  APPL: "AAPL",
  APPLE: "AAPL",
  TESLA: "TSLA",
  GOOGLE: "GOOGL",
  ALPHABET: "GOOGL",
  AMAZON: "AMZN",
  NVIDIA: "NVDA",
  MICROSOFT: "MSFT",
};

function resolveTickerAlias(raw) {
  const upper = String(raw || "").trim().toUpperCase();
  return TICKER_ALIASES[upper] || upper;
}

function normalizePositionType(value, fallback = DEFAULT_POSITION_TYPE) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "crypto_hold") return "investment";
  return POSITION_TYPE_DEFINITIONS.some((item) => item.value === normalized)
    ? normalized
    : fallback;
}

function getPositionTypeMeta(value) {
  return POSITION_TYPE_DEFINITIONS.find((item) => item.value === normalizePositionType(value))
    || POSITION_TYPE_DEFINITIONS[0];
}

function getPositionIntentOverride(symbol, overrides = {}) {
  const canonicalKey = getPositionIntentKey(symbol);
  const legacyKey = String(symbol || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
  return overrides[canonicalKey] || overrides[legacyKey] || {};
}

function getPositionIntentMigrationStorageKey(userId) {
  return userId ? `${POSITION_INTENT_STORAGE_KEY}:synced:${userId}` : `${POSITION_INTENT_STORAGE_KEY}:synced`;
}

function mapPositionTradeTypeRows(rows = []) {
  return (rows || []).reduce((acc, row) => {
    const key = getPositionIntentKey(row?.symbol);
    if (!key) return acc;
    const tradeType = normalizePositionType(row?.trade_type || row?.tradeType);
    const meta = getPositionTypeMeta(tradeType);
    acc[key] = {
      symbol: String(row?.symbol || key).trim().toUpperCase(),
      tradeType,
      trade_type: tradeType,
      positionType: tradeType,
      position_type: tradeType,
      timeHorizon: meta.defaultTimeHorizon,
      time_horizon: meta.defaultTimeHorizon,
    };
    return acc;
  }, {});
}

function readLegacyPositionIntentOverrides() {
  try {
    const parsed = JSON.parse(localStorage.getItem(POSITION_INTENT_STORAGE_KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

// Canonical key helper: strips /USD suffix for crypto, strips non-alphanumeric.
// Used in every write, read, and lookup path so keys always match.
function getPositionIntentKey(symbol) {
  const normalizedAsset = normalizePickAssetSymbol(symbol);
  return String(normalizedAsset || symbol || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function inferPositionTypeFromBrokerLog(symbol, brokerTradeLog) {
  if (!symbol || !Array.isArray(brokerTradeLog) || !brokerTradeLog.length) return "investment";
  const key = getPositionIntentKey(symbol);
  const today = new Date();
  const hasTodayBuy = brokerTradeLog.some((order) => {
    if (!order?.filled_at) return false;
    const side = String(order?.side || "").toLowerCase();
    const status = String(order?.status || "").toLowerCase();
    if (side !== "buy" || (status !== "filled" && status !== "partially_filled")) return false;
    if (getPositionIntentKey(order?.symbol) !== key) return false;
    const filled = new Date(order.filled_at);
    return filled.getFullYear() === today.getFullYear() && filled.getMonth() === today.getMonth() && filled.getDate() === today.getDate();
  });
  return hasTodayBuy ? "day_trade" : "investment";
}

function inferPositionTypeFromSymbol(symbol, brokerTradeLog) {
  return inferPositionTypeFromBrokerLog(symbol, brokerTradeLog);
}

function buildPositionIntentMetadata(record = {}, fallbackType = DEFAULT_POSITION_TYPE) {
  const positionType = normalizePositionType(record.tradeType || record.trade_type || record.positionType || record.position_type || record.positionIntent?.type, fallbackType);
  const meta = getPositionTypeMeta(positionType);
  const entryReason = String(record.entryReason || record.entry_reason || record.positionIntent?.entryReason || "").trim();
  const timeHorizon = String(record.timeHorizon || record.time_horizon || record.positionIntent?.timeHorizon || meta.defaultTimeHorizon || "").trim();
  // Trader-provided free-text rationale. Read from legacy `thesis` field for backward
  // compatibility with existing stored data, but renamed to `traderReason` on the
  // returned object so it never reaches the LLM as a field labelled "thesis".
  const traderReason = String(record.thesis || record.reason || record.positionIntent?.thesis || record.positionIntent?.reason || "").trim();
  return {
    positionType,
    position_type: positionType,
    tradeType: positionType,
    trade_type: positionType,
    positionTypeLabel: meta.label,
    positionCategory: meta.category,
    isLongTermHolding: meta.category === "holding",
    traderReason,
    entryReason,
    entry_reason: entryReason,
    timeHorizon,
    time_horizon: timeHorizon,
    positionIntent: {
      type: positionType,
      label: meta.label,
      category: meta.category,
      timeHorizon,
      reason: traderReason,
      entryReason,
    },
  };
}

function matchesPerformancePositionFilter(record, filterValue = "all") {
  const { positionType } = buildPositionIntentMetadata(record, DEFAULT_POSITION_TYPE);
  if (filterValue === "all" || filterValue === "active") {
    return positionType === "day_trade" || positionType === "swing_trade";
  }
  if (filterValue === "holdings") {
    return positionType === "investment";
  }
  return true;
}

function clampNumber(value, min, max) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return min;
  return Math.max(min, Math.min(max, numeric));
}

function coerceFiniteNumber(value, fallback = 0) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : fallback;
}

function resolveCustomChartViewport(startMs, endMs, viewport) {
  const start = Number(startMs);
  const end = Number(endMs);
  const zoom = CUSTOM_CHART_ZOOM_LEVELS.includes(Number(viewport?.zoom)) ? Number(viewport.zoom) : 1;
  const offset = clampNumber(viewport?.offset ?? 1, 0, 1);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start || zoom <= 1) {
    const fallbackEnd = Number.isFinite(end) ? end : Date.now();
    const fallbackStart = Number.isFinite(start) && start < fallbackEnd
      ? start
      : fallbackEnd - (24 * 60 * 60 * 1000);
    return { startMs: fallbackStart, endMs: fallbackEnd, zoom: 1, offset: 1 };
  }
  const fullSpan = end - start;
  const visibleSpan = fullSpan / zoom;
  const maxOffsetMs = Math.max(0, fullSpan - visibleSpan);
  const visibleStart = start + (maxOffsetMs * offset);
  return {
    startMs: visibleStart,
    endMs: visibleStart + visibleSpan,
    zoom,
    offset,
  };
}

function getNextCustomChartZoom(currentZoom, direction) {
  const zoom = Number(currentZoom) || 1;
  const currentIndex = CUSTOM_CHART_ZOOM_LEVELS.indexOf(zoom);
  const safeIndex = currentIndex >= 0 ? currentIndex : 0;
  return CUSTOM_CHART_ZOOM_LEVELS[clampNumber(safeIndex + direction, 0, CUSTOM_CHART_ZOOM_LEVELS.length - 1)];
}
