const CANONICAL_BROKER_CRYPTO_ASSETS = SUPPORTED_CRYPTO_SEARCH_ASSETS.map((asset) => ({
  symbol: asset.symbol,
  name: asset.description,
  exchange: "Crypto",
  assetClass: "crypto",
  marginable: false,
  shortable: false,
  easyToBorrow: false,
}));

function normalizeBrokerAssetSearchKey(symbol) {
  return String(symbol || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function getCanonicalBrokerCryptoAssetsForQuery(query) {
  const compactQuery = normalizeBrokerAssetSearchKey(query);
  if (!compactQuery) return [];

  return CANONICAL_BROKER_CRYPTO_ASSETS.filter((asset) => {
    const compactSymbol = normalizeBrokerAssetSearchKey(asset.symbol);
    const baseSymbol = compactSymbol.endsWith("USD") ? compactSymbol.slice(0, -3) : compactSymbol;
    return compactQuery === baseSymbol || compactQuery === compactSymbol;
  });
}

function mergeBrokerAssetSearchResults(query, backendAssets) {
  const seen = new Set();
  const results = [];

  for (const asset of (Array.isArray(backendAssets) ? backendAssets : [])) {
    const assetClass = String(asset?.assetClass || asset?.asset_class || "").toLowerCase();
    const isCrypto = assetClass === "crypto";

    if (!isCrypto && asset?.tradable !== true) continue;

    const rawKey = normalizeBrokerAssetSearchKey(asset?.symbol);
    const baseKey = isCrypto
      ? rawKey.endsWith("USDT") || rawKey.endsWith("USDC")
        ? rawKey.slice(0, -4)
        : rawKey.endsWith("USD")
          ? rawKey.slice(0, -3)
          : rawKey
      : rawKey;
    const dedupKey = isCrypto ? `crypto:${baseKey}` : baseKey;
    if (!dedupKey || seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    results.push(isCrypto ? { ...asset, symbol: baseKey } : asset);
  }

  // Five-tier ranking so exact ticker always wins over prefix/fuzzy on either
  // ticker or company name. Ties inside a tier broken alphabetically by symbol
  // so ordering is deterministic across renders.
  //   0 → exact ticker    (GOOG for query "GOOG")
  //   1 → exact company   ("Alphabet" for query "ALPHABET")
  //   2 → prefix ticker   (GOOGL for query "GOOG")
  //   3 → prefix company  ("Alphabet Inc." for query "ALPH")
  //   4 → fuzzy / substring match anywhere in ticker or name
  const q = normalizeBrokerAssetSearchKey(query);
  const qCompact = String(query || "").trim().toUpperCase();
  function normalizeName(name) {
    return String(name || "").trim().toUpperCase();
  }
  function rankAsset(asset) {
    const sym = normalizeBrokerAssetSearchKey(asset?.symbol);
    const nameUpper = normalizeName(asset?.name ?? asset?.description);
    if (sym === q) return 0;
    if (nameUpper && nameUpper === qCompact) return 1;
    if (q && sym.startsWith(q)) return 2;
    if (nameUpper && qCompact && nameUpper.startsWith(qCompact)) return 3;
    if ((q && sym.includes(q)) || (qCompact && nameUpper && nameUpper.includes(qCompact))) return 4;
    return 5;
  }
  results.sort((a, b) => {
    const r = rankAsset(a) - rankAsset(b);
    if (r !== 0) return r;
    // Deterministic tie-break: shorter symbol first (GOOG before GOOGL),
    // then alphabetical.
    const symA = normalizeBrokerAssetSearchKey(a?.symbol);
    const symB = normalizeBrokerAssetSearchKey(b?.symbol);
    if (symA.length !== symB.length) return symA.length - symB.length;
    return symA.localeCompare(symB);
  });

  return results;
}

