// Signals that mean "the user is asking about current market state, news,
// catalysts, macro events, or a specific holding's move." Any one of these
// triggers the world-context fetch — no compound gate, no requirement that
// the user opened Ask Rayla from a specific launcher. If a reasonable human
// would read the question as asking for real-world market context, one of
// these should match. Users should never have to learn trigger phrases.
//
// Categories, each fires independently:
//   1. Cause inquiry — why / what happened / what's driving / news on / etc.
//   2. News keyword — news / headline / catalyst
//   3. Macro inquiry — fed / cpi / earnings / geopolitics / etc.
//   4. Movement word + subject word — "portfolio up", "sector rallying"
//   5. Movement word + time-current word — "tech up today", "green this week"
//   6. Held-ticker mention — any $PLTR/PLTR when the user actually holds it
const CAUSE_INQUIRY_RE = /\b(why|what(?:'|’)?s\s+(?:driving|happening|moving|going\s+on|the\s+news|the\s+catalyst)|what\s+is\s+(?:driving|happening|moving|going\s+on|the\s+news|the\s+catalyst)|what\s+happened|what\s+caused|what(?:'|’)?s\s+up\s+with|any\s+news|news\s+on|update\s+on|updates?\s+on)\b/i;
const NEWS_KEYWORD_RE = /\b(news|headline|headlines|catalyst|catalysts)\b/i;
const MACRO_INQUIRY_RE = /\b(fed|fomc|federal\s+reserve|powell|rate\s+cut|rate\s+hike|interest\s+rate|cpi|ppi|inflation|pce|jobs\s+report|payroll|nonfarm|unemployment|jobless|earnings|guidance|beat\s+estimates|missed\s+estimates|opec|tariff|sanction|geopolit|ukraine|russia|china|taiwan|middle\s+east|israel|iran)\b/i;
const MARKET_MOVEMENT_RE = /\b(up|down|rally|rallying|rallied|sell[-\s]?off|selloff|selling\s+off|sold\s+off|jumped|jumping|surge|surged|surging|dropped|dropping|crash|crashed|crashing|gain(?:s|ing|ed)?|loss(?:es|ing)?|lost|green|red|moving|moved|rebound(?:ed|ing)?|bounce[dr]?|slid|sliding|slipped|higher|lower)\b/i;
const MARKET_SUBJECT_RE = /\b(market|markets|portfolio|portfolios|holdings|position|positions|stock|stocks|share|shares|sector|sectors|tech|equity|equities|bond|bonds|commodity|commodities|crypto)\b/i;
const TIME_CURRENT_RE = /\b(today|this\s+week|this\s+morning|this\s+afternoon|right\s+now|currently|premarket|after\s+hours|overnight|yesterday|last\s+night|recent(?:ly)?|lately|this\s+month)\b/i;

function looksLikeWorldContextQuestion(text, heldTickers = []) {
  const s = String(text || "");
  if (!s.trim()) return false;
  if (CAUSE_INQUIRY_RE.test(s)) return true;
  if (NEWS_KEYWORD_RE.test(s)) return true;
  if (MACRO_INQUIRY_RE.test(s)) return true;
  if (MARKET_MOVEMENT_RE.test(s) && MARKET_SUBJECT_RE.test(s)) return true;
  if (MARKET_MOVEMENT_RE.test(s) && TIME_CURRENT_RE.test(s)) return true;
  if (heldTickers.length > 0) {
    const upper = s.toUpperCase();
    for (const ticker of heldTickers) {
      if (!ticker) continue;
      if (new RegExp(`\\b\\$?${ticker}\\b`).test(upper)) return true;
    }
  }
  return false;
}

// Assembles the world-context payload the ask-rayla system prompt consumes.
// Fetches in parallel: general market news, per-symbol news for the top
// holdings, and sector ETF snapshot. Returns a compact object safe to attach
// to extraContext.worldContext. Failure is non-fatal — a partial or empty
// world-context block just means Rayla answers without world data.
async function buildWorldContextForPortfolio({ supabaseClient, symbols = [], generalNewsLimit = 24 }) {
  const shortlist = Array.from(new Set(
    (Array.isArray(symbols) ? symbols : [])
      .map((s) => String(s || "").toUpperCase().trim())
      .filter(Boolean),
  )).slice(0, 6); // cap per-symbol fetches to keep latency in check

  const generalPromise = supabaseClient.functions.invoke("market-data", {
    body: { includeGeneralNews: true, generalNewsLimit },
  }).then((res) => Array.isArray(res?.data?.generalNews) ? res.data.generalNews : [])
    .catch(() => []);

  const sectorPromise = supabaseClient.functions.invoke("market-data", {
    body: { symbols: SECTOR_SNAPSHOT_SYMBOLS.map((s) => ({ symbol: s, type: "stock" })) },
  }).then((res) => {
    const quotes = res?.data?.quotes || {};
    return SECTOR_SNAPSHOT_SYMBOLS
      .map((sym) => ({ symbol: sym, change: Number(quotes?.[sym]?.change) }))
      .filter((row) => Number.isFinite(row.change))
      .sort((a, b) => b.change - a.change);
  }).catch(() => []);

  const perSymbolPromise = Promise.all(
    shortlist.map(async (sym) => {
      try {
        const res = await supabaseClient.functions.invoke("market-data", {
          body: { newsSymbol: sym, newsType: "stock" },
        });
        const news = Array.isArray(res?.data?.news) ? res.data.news.slice(0, 3) : [];
        return [sym, news];
      } catch {
        return [sym, []];
      }
    }),
  );

  const [general, sectorSnapshot, symbolPairs] = await Promise.all([
    generalPromise, sectorPromise, perSymbolPromise,
  ]);

  const bySymbol = {};
  for (const [sym, news] of symbolPairs) {
    if (news.length) bySymbol[sym] = news;
  }

  const macroMatches = general.filter((item) => {
    const text = `${item?.headline || ""} ${item?.summary || ""}`.toLowerCase();
    return MACRO_KEYWORDS.some((kw) => text.includes(kw));
  });

  return {
    generalHeadlines: general.slice(0, 12),
    macroHeadlines: macroMatches.slice(0, 8),
    bySymbol,
    sectorSnapshot,
    fetchedAt: new Date().toISOString(),
  };
}

function normalizeAssetId(rawSymbol, type = "", tvSymbol = "") {
  const raw = String(rawSymbol || "").trim().toUpperCase();
  if (!raw) return "";

  const normalizedType = String(type || "").trim().toUpperCase();
  const upperTvSymbol = String(tvSymbol || "").trim().toUpperCase();
  const cryptoCandidate = normalizeCryptoAssetId(raw);
  const isCrypto = normalizedType === "CRYPTO"
    || upperTvSymbol.includes("BINANCE")
    || upperTvSymbol.includes("USDT")
    || raw.includes("USDT")
    || raw.includes("USD")
    || CRYPTO_SYMBOL_SET.has(raw)
    || CRYPTO_SYMBOL_SET.has(cryptoCandidate);

  if (isCrypto) return cryptoCandidate;
  if (raw === "TRON") return "TRX";
  return raw.includes(":") ? raw.split(":").pop() : raw;
}

function buildChartDrawingsStorageKey(symbol, chartType) {
  const normalizedSymbol = normalizeAssetId(symbol) || "UNKNOWN";
  return `rayla_drawings_${normalizedSymbol}_${chartType}`;
}

function normalizeStoredChartDrawing(drawing) {
  if (!drawing || typeof drawing !== "object") return null;
  const type = drawing.type === "note" ? "text" : String(drawing.type || "").toLowerCase();
  if (!["horizontal", "trendline", "text"].includes(type)) return null;
  const points = Array.isArray(drawing.points)
    ? drawing.points
        .map((point) => {
          if (!point || typeof point !== "object") return null;
          const normalizedPoint = {};
          if (Number.isFinite(Number(point.time))) normalizedPoint.time = Number(point.time);
          if (Number.isFinite(Number(point.price))) normalizedPoint.price = Number(point.price);
          if (Number.isFinite(Number(point.xPct))) normalizedPoint.xPct = Math.max(0, Math.min(100, Number(point.xPct)));
          if (Number.isFinite(Number(point.yPct))) normalizedPoint.yPct = Math.max(0, Math.min(100, Number(point.yPct)));
          return Object.keys(normalizedPoint).length ? normalizedPoint : null;
        })
        .filter(Boolean)
    : [];
  if (!points.length) return null;
  return {
    id: String(drawing.id || createClientId()),
    type,
    points,
    text: type === "text" ? String(drawing.text || "").trim().slice(0, 80) : "",
  };
}

function readChartDrawingsFromStorage(storageKey) {
  if (!storageKey || typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(storageKey);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.map(normalizeStoredChartDrawing).filter(Boolean);
  } catch {
    return [];
  }
}

function writeChartDrawingsToStorage(storageKey, drawings) {
  if (!storageKey || typeof window === "undefined") return;
  try {
    if (!Array.isArray(drawings) || !drawings.length) {
      window.localStorage.removeItem(storageKey);
      return;
    }
    window.localStorage.setItem(storageKey, JSON.stringify(drawings.map(normalizeStoredChartDrawing).filter(Boolean)));
  } catch {
    // Ignore localStorage write failures.
  }
}

function fetchWithTimeout(url, options = {}, timeoutMs = 12000) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort("Request timed out"), timeoutMs);

  return fetch(url, { ...options, signal: controller.signal })
    .finally(() => clearTimeout(timeout));
}

// Repairs JSON strings that ask-rayla's cleanupAnswerText may have corrupted:
// 1. Reverses "• " bullet injection (was "- " or "* " or "1. " at line start)
// 2. Escapes literal unescaped newlines/carriage-returns inside JSON string values
function repairLLMJsonString(raw) {
  let s = raw.replace(/• /g, "- ");
  let result = "";
  let inString = false;
  let escaped = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (escaped) { result += ch; escaped = false; continue; }
    if (ch === "\\") { escaped = true; result += ch; continue; }
    if (ch === '"') { inString = !inString; result += ch; continue; }
    if (inString && ch === "\n") { result += "\\n"; continue; }
    if (inString && ch === "\r") { continue; }
    result += ch;
  }
  return result;
}

function getTvSymbol(asset) {
  if (asset?.tvSymbol) return asset.tvSymbol;
  if (asset?.type === "crypto") return `BINANCE:${asset.id}USDT`;
  return asset?.id || "";
}

function getEquityTvSymbol(symbol, exchange = "", assetType = "") {
  const normalizedExchange = String(exchange || "").trim().toUpperCase();
  const normalizedType = String(assetType || "").trim().toUpperCase();
  if (normalizedExchange.includes("NYSE")) return `NYSE:${symbol}`;
  if (normalizedExchange.includes("NASDAQ")) return `NASDAQ:${symbol}`;
  if (
    normalizedExchange.includes("AMEX")
    || normalizedExchange.includes("ARCA")
    || normalizedExchange.includes("BATS")
    || normalizedExchange.includes("CBOE")
  ) {
    return `AMEX:${symbol}`;
  }
  if (normalizedType === "ETP" && !String(symbol).includes(".")) {
    return `AMEX:${symbol}`;
  }

  return symbol;
}

function normalizeSearchResult(result) {
  const symbol = normalizeAssetId(result?.symbol, result?.type, result?.tvSymbol);
  const description = String(result?.description || symbol).trim();
  const exchange = String(result?.exchange || result?.mic || "").trim().toUpperCase();
  const assetType = String(result?.type || "").trim().toUpperCase();
  const explicitOverrides = {
    SPY: "AMEX:SPY",
    QQQ: "NASDAQ:QQQ",
    DIA: "AMEX:DIA",
    IWM: "AMEX:IWM",
    BTC: "BINANCE:BTCUSDT",
    ETH: "BINANCE:ETHUSDT",
    SOL: "BINANCE:SOLUSDT",
    XRP: "BINANCE:XRPUSDT",
    DOGE: "BINANCE:DOGEUSDT",
    ADA: "BINANCE:ADAUSDT",
    AVAX: "BINANCE:AVAXUSDT",
    LINK: "BINANCE:LINKUSDT",
    NRG: "NYSE:NRG",
    KO: "NYSE:KO",
    DIS: "NYSE:DIS",
    BA: "NYSE:BA",
    JPM: "NYSE:JPM",
    XOM: "NYSE:XOM",
    WMT: "NYSE:WMT",
    NKE: "NYSE:NKE",
    MCD: "NYSE:MCD",
    GS: "NYSE:GS",
  };

  let tvSymbol = explicitOverrides[symbol];
  if (!tvSymbol) {
    const isCrypto = CRYPTO_SYMBOL_SET.has(symbol) || exchange.includes("CRYPTO");
    if (isCrypto) tvSymbol = `BINANCE:${symbol}USDT`;
    else tvSymbol = getEquityTvSymbol(symbol, exchange, assetType);
  }

  return {
    ...result,
    symbol,
    description,
    exchange,
    tvSymbol,
    alpacaSupported: typeof result?.tradable === "boolean"
      ? Boolean(result.tradable)
      : (CRYPTO_SYMBOL_SET.has(symbol) ? true : result?.alpacaSupported),
  };
}

function rankSupportedSearchResult(result, query) {
  const normalizedQuery = String(query || "").trim().toUpperCase();
  const symbol = String(result?.symbol || "").trim().toUpperCase();
  const description = String(result?.description || "").trim().toUpperCase();
  const isCanonicalCryptoQuery = SUPPORTED_CRYPTO_SEARCH_ASSETS.some((asset) => asset.symbol === normalizedQuery);
  const isCanonicalCryptoMatch = isCanonicalCryptoQuery && result?.type === "crypto" && symbol === normalizedQuery;
  if (isCanonicalCryptoMatch) return -1;
  if (isCanonicalCryptoQuery && result?.type === "crypto") return -0.5;
  if (symbol === normalizedQuery) return 0;
  if (description === normalizedQuery) return 1;
  if (symbol.startsWith(normalizedQuery)) return 2;
  if (description.startsWith(normalizedQuery)) return 3;
  if (symbol.includes(normalizedQuery)) return 4;
  if (description.includes(normalizedQuery)) return 5;
  return 6;
}

const supportedSearchCache = new Map();

async function searchRaylaSupportedAssets(query, alpacaConnected, preferPaper = false) {
  const normalizedQuery = resolveTickerAlias(String(query || "").trim().toUpperCase());
  if (!normalizedQuery) return [];

  const cacheKey = `${alpacaConnected ? (preferPaper ? "alpaca-paper" : "alpaca-live") : "local"}:${normalizedQuery}`;
  if (supportedSearchCache.has(cacheKey)) {
    return supportedSearchCache.get(cacheKey);
  }

  const cryptoResults = SUPPORTED_CRYPTO_SEARCH_ASSETS
    .filter((asset) => (
      asset.symbol.includes(normalizedQuery)
      || asset.description.toUpperCase().includes(normalizedQuery)
    ))
    .map(normalizeSearchResult);

  let stockResults = [];
  if (alpacaConnected) {
    try {
      const { data, error } = await supabase.functions.invoke("alpaca-assets", {
        body: { query: normalizedQuery, preferPaper },
      });

      if (!error && data?.ok && Array.isArray(data.assets)) {
        stockResults = data.assets.map((asset) => normalizeSearchResult({
          symbol: asset.symbol,
          description: asset.name,
          exchange: asset.exchange,
          type: "stock",
        }));
      }
    } catch {
      stockResults = [];
    }
  } else {
    stockResults = SUPPORTED_POPULAR_STOCKS
      .filter((asset) => (
        asset.symbol.includes(normalizedQuery)
        || asset.description.toUpperCase().includes(normalizedQuery)
      ))
      .map(normalizeSearchResult);
  }

  const merged = [...cryptoResults, ...stockResults];
  const seen = new Set();
  const results = merged
    .filter((result) => {
      const key = `${result.symbol}:${result.type || ""}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => {
      const rankDelta = rankSupportedSearchResult(a, normalizedQuery) - rankSupportedSearchResult(b, normalizedQuery);
      if (rankDelta !== 0) return rankDelta;
      const symbolLengthDelta = Math.abs(String(a.symbol || "").length - normalizedQuery.length) - Math.abs(String(b.symbol || "").length - normalizedQuery.length);
      if (symbolLengthDelta !== 0) return symbolLengthDelta;
      return String(a.symbol || "").localeCompare(String(b.symbol || ""));
    })
    .slice(0, 8);

  supportedSearchCache.set(cacheKey, results);
  return results;
}

