function createDefaultRaylaAdaptiveState() {
  return {
    onboardingCompleted: false,
    onboardingAnswers: {},
    interactions: {
      questionCount: 0,
      confusionCount: 0,
      advancedCount: 0,
      recentQuestions: [],
    },
  };
}

function isRaylaConfusionQuestion(question) {
  const normalized = String(question || "").toLowerCase();
  return [
    "i don't understand",
    "i dont understand",
    "confused",
    "simpler",
    "simplify",
    "explain again",
    "what does that mean",
    "break that down",
    "too complex",
    "lost me",
  ].some((phrase) => normalized.includes(phrase));
}

function isRaylaAdvancedQuestion(question) {
  const normalized = String(question || "").toLowerCase();
  return [
    "risk reward",
    "risk/reward",
    "drawdown",
    "liquidity",
    "execution",
    "position sizing",
    "probability",
    "correlation",
    "timeframe alignment",
    "market structure",
    "invalid",
    "r-multiple",
    "expectancy",
  ].some((phrase) => normalized.includes(phrase));
}

function buildNextRaylaAdaptiveState(state, question) {
  const nextState = state || createDefaultRaylaAdaptiveState();
  const trimmedQuestion = String(question || "").trim();
  if (!trimmedQuestion) return nextState;

  return {
    ...nextState,
    interactions: {
      questionCount: (nextState.interactions?.questionCount || 0) + 1,
      confusionCount: (nextState.interactions?.confusionCount || 0) + (isRaylaConfusionQuestion(trimmedQuestion) ? 1 : 0),
      advancedCount: (nextState.interactions?.advancedCount || 0) + (isRaylaAdvancedQuestion(trimmedQuestion) ? 1 : 0),
      recentQuestions: [
        trimmedQuestion,
        ...((nextState.interactions?.recentQuestions || []).slice(0, 5)),
      ],
    },
  };
}

function buildRaylaAdaptiveProfile({
  adaptiveState,
  currentQuestion,
  trades,
  simulationTradeHistory,
  selectedMarketId,
}) {
  const nextState = adaptiveState || createDefaultRaylaAdaptiveState();
  const answers = nextState.onboardingAnswers || {};
  const interactions = nextState.interactions || {};
  const simulationProfile = {
    totalTrades: Array.isArray(simulationTradeHistory) ? simulationTradeHistory.length : 0,
  };
  const coachReport = buildCoachReport(trades || []);
  const currentQuestionIsConfused = isRaylaConfusionQuestion(currentQuestion);
  const currentQuestionIsAdvanced = isRaylaAdvancedQuestion(currentQuestion);

  let complexityScore = 0;

  if (answers.experience === "brand new") complexityScore -= 2;
  if (answers.experience === "some experience") complexityScore += 0;
  if (answers.experience === "active trader") complexityScore += 2;

  if (answers.familiarity === "not very") complexityScore -= 2;
  if (answers.familiarity === "somewhat comfortable") complexityScore += 0;
  if (answers.familiarity === "very comfortable") complexityScore += 2;

  if ((interactions.questionCount || 0) >= 6) complexityScore += 1;
  if ((interactions.advancedCount || 0) >= 3) complexityScore += 2;
  if ((simulationProfile?.totalTrades || 0) >= 5) complexityScore += 1;
  if ((coachReport?.trades || 0) >= 5) complexityScore += 1;
  if ((interactions.confusionCount || 0) >= 2) complexityScore -= 2;
  if (currentQuestionIsConfused) complexityScore -= 3;
  if (currentQuestionIsAdvanced) complexityScore += 2;

  const explanationDepth = currentQuestionIsConfused || complexityScore <= -1
    ? "simple"
    : complexityScore >= 4
      ? "advanced"
      : "balanced";

  const guidanceNotes = [];
  if (explanationDepth === "simple") {
    guidanceNotes.push("Use plain language, short steps, and define terms only when needed.");
    guidanceNotes.push("Assume the user may want simpler framing right now.");
  } else if (explanationDepth === "advanced") {
    guidanceNotes.push("The user likely understands the basics, so avoid repeating beginner definitions unless asked.");
    guidanceNotes.push("It is okay to be a bit more technical and connect ideas across execution, risk, and market structure.");
  } else {
    guidanceNotes.push("Use a balanced explanation depth with clear reasoning and light jargon.");
  }

  if (answers.goal === "learn the basics") {
    guidanceNotes.push("Bias toward teaching-first explanations and concrete examples.");
  } else if (answers.goal === "improve execution") {
    guidanceNotes.push("Bias toward actionable execution feedback and trade management details.");
  } else if (answers.goal === "analyze performance") {
    guidanceNotes.push("Bias toward pattern recognition, review, and performance framing.");
  }

  return {
    onboardingCompleted: !!nextState.onboardingCompleted,
    onboardingAnswers: answers,
    selectedMarketId,
    questionCount: interactions.questionCount || 0,
    confusionCount: interactions.confusionCount || 0,
    advancedCount: interactions.advancedCount || 0,
    explanationDepth,
    currentQuestionIsConfused,
    currentQuestionIsAdvanced,
    guidanceNotes,
  };
}

function renderRaylaMessageContent(content) {
  const text = String(content || "").trim();
  if (!text) return null;

  return text.split(/\n\s*\n/).map((block, blockIndex) => {
    const lines = block.split("\n").map((line) => line.trim()).filter(Boolean);
    const segments = [];
    let paragraphLines = [];
    let bulletItems = [];

    function flushParagraph() {
      if (!paragraphLines.length) return;
      segments.push(
        <p key={`p-${blockIndex}-${segments.length}`} style={{ margin: 0, lineHeight: 1.7 }}>
          {paragraphLines.join(" ")}
        </p>
      );
      paragraphLines = [];
    }

    function flushBullets() {
      if (!bulletItems.length) return;
      segments.push(
        <ul
          key={`ul-${blockIndex}-${segments.length}`}
          style={{ margin: 0, paddingLeft: 18, display: "flex", flexDirection: "column", gap: 6 }}
        >
          {bulletItems.map((item, index) => (
            <li key={index}>{item}</li>
          ))}
        </ul>
      );
      bulletItems = [];
    }

    lines.forEach((line) => {
      if (/^[-•*]\s+/.test(line)) {
        flushParagraph();
        bulletItems.push(line.replace(/^[-•*]\s+/, ""));
      } else {
        flushBullets();
        paragraphLines.push(line);
      }
    });

    flushParagraph();
    flushBullets();

    return (
      <div key={blockIndex} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {segments}
      </div>
    );
  });
}

function parseTradeResult(value) {
  const parsed = Number.parseFloat(value ?? 0);
  return Number.isFinite(parsed) ? parsed : 0;
}

function parseOptionalTradeResult(value) {
  if (value === null || value === undefined || String(value).trim() === "") return null;
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function parsePickResultR(trade) {
  const resultR = parseOptionalTradeResult(trade?.result_r);
  if (resultR != null) return resultR;
  const resultRAlt = parseOptionalTradeResult(trade?.resultR);
  if (resultRAlt != null) return resultRAlt;
  const rMultiple = parseOptionalTradeResult(trade?.rMultiple);
  return rMultiple != null ? rMultiple : null;
}

function normalizePickDirection(value) {
  const normalized = String(value || "").trim().toLowerCase().replace(/[_-]+/g, " ");
  if (!normalized) return "";
  if (normalized === "long" || normalized === "buy" || normalized.includes("buy / long")) return "long";
  if (normalized === "short" || normalized === "sell short" || normalized === "short sell" || normalized.includes("sell / short")) return "short";
  return normalized;
}

function normalizePickAssetSymbol(value) {
  const raw = String(value || "").trim().toUpperCase();
  if (!raw) return "";
  const compact = normalizePerformanceAssetKey(raw);
  const cryptoUsdPair = compact.match(/^([A-Z0-9]{2,8})USD$/);
  if (cryptoUsdPair && CRYPTO_SYMBOL_SET.has(cryptoUsdPair[1])) return cryptoUsdPair[1];
  const cryptoUsdtPair = compact.match(/^([A-Z0-9]{2,8})USDT$/);
  if (cryptoUsdtPair && CRYPTO_SYMBOL_SET.has(cryptoUsdtPair[1])) return cryptoUsdtPair[1];
  return compact || raw;
}

function brokerSymbolsMatch(a, b) {
  const left = normalizePickAssetSymbol(a);
  const right = normalizePickAssetSymbol(b);
  return Boolean(left && right && left === right);
}

function findBrokerPositionBySymbol(positions, symbol) {
  return (positions || []).find((position) => brokerSymbolsMatch(position?.symbol, symbol)) || null;
}

function brokerSelectionIncludesSymbol(symbols, symbol) {
  return (symbols || []).some((item) => brokerSymbolsMatch(item, symbol));
}

function formatBrokerQuantity(value) {
  const qty = Math.abs(Number(value));
  if (!Number.isFinite(qty)) return "--";
  if (qty === 0) return "0";
  if (qty < 1) return Number.parseFloat(qty.toFixed(8)).toString();
  if (!Number.isInteger(qty)) return Number.parseFloat(qty.toFixed(6)).toString();
  return String(qty);
}

function getTradeOutcomeValue(trade) {
  const resultR = parsePickResultR(trade);
  if (!trade?.isBrokerTrade && !isBrokerImportSetup(trade?.setup) && resultR != null) return resultR;
  const pnlValue = Number(trade?.pnl_value);
  if (Number.isFinite(pnlValue)) return pnlValue;
  return resultR != null ? resultR : 0;
}

function getTradeProfitValue(trade) {
  const explicitProfit = Number(trade?.profitLoss);
  if (Number.isFinite(explicitProfit)) return explicitProfit;
  const explicitPnlDollars = Number(trade?.pnl_dollars);
  if (Number.isFinite(explicitPnlDollars)) return explicitPnlDollars;
  const explicitPnl = Number(trade?.pnl);
  if (Number.isFinite(explicitPnl)) return explicitPnl;
  const explicitUsd = Number(trade?.profitLossUsd);
  if (Number.isFinite(explicitUsd)) return explicitUsd;
  const explicitRealized = Number(trade?.realizedPnl);
  if (Number.isFinite(explicitRealized)) return explicitRealized;
  const explicitAmount = Number(trade?.resultAmount);
  if (Number.isFinite(explicitAmount)) return explicitAmount;
  const pnlValue = Number(trade?.pnl_value);
  if (Number.isFinite(pnlValue)) return pnlValue;
  return calculateTradeDollarPnl(trade);
}

function sortTradesForPerformance(trades, timeAccessor = null) {
  return [...(Array.isArray(trades) ? trades : [])]
    .map((trade, index) => ({
      trade,
      index,
      timeMs: typeof timeAccessor === "function" ? timeAccessor(trade) : null,
    }))
    .sort((a, b) => {
      const timeA = Number.isFinite(a.timeMs) ? a.timeMs : null;
      const timeB = Number.isFinite(b.timeMs) ? b.timeMs : null;
      if (timeA != null && timeB != null && timeA !== timeB) return timeA - timeB;
      if (timeA != null && timeB == null) return -1;
      if (timeA == null && timeB != null) return 1;
      return a.index - b.index;
    })
    .map((entry) => entry.trade);
}

function calculateProfitDrawdown(trades, profitAccessor = getTradeProfitValue, timeAccessor = null) {
  const orderedTrades = sortTradesForPerformance(trades, timeAccessor);
  let runningProfit = 0;
  let peakProfit = 0;
  let maxDrawdown = 0;

  orderedTrades.forEach((trade) => {
    const profitValue = typeof profitAccessor === "function" ? profitAccessor(trade) : null;
    if (!Number.isFinite(profitValue)) return;
    runningProfit += profitValue;
    if (runningProfit > peakProfit) peakProfit = runningProfit;
    const drawdown = runningProfit - peakProfit;
    if (drawdown < maxDrawdown) maxDrawdown = drawdown;
  });

  return maxDrawdown;
}

function buildPerformanceSegmentMetrics(trades, { profitAccessor = getTradeProfitValue, rAccessor = null, timeAccessor = null } = {}) {
  const normalizedTrades = Array.isArray(trades) ? trades : [];
  const resolvedRAccessor = typeof rAccessor === "function"
    ? rAccessor
    : (trade) => {
        const resultR = Number(trade?.result_r);
        if (Number.isFinite(resultR)) return resultR;
        const rMultiple = Number(trade?.rMultiple);
        return Number.isFinite(rMultiple) ? rMultiple : null;
      };

  const tradeCount = normalizedTrades.length;
  const pnlValues = normalizedTrades
    .map((trade) => (typeof profitAccessor === "function" ? profitAccessor(trade) : null))
    .filter((value) => Number.isFinite(value));
  const rValues = normalizedTrades
    .map((trade) => resolvedRAccessor(trade))
    .filter((value) => Number.isFinite(value));

  const winSourceValues = pnlValues.length === tradeCount
    ? pnlValues
    : normalizedTrades
        .map((trade) => {
          const profitValue = typeof profitAccessor === "function" ? profitAccessor(trade) : null;
          if (Number.isFinite(profitValue)) return profitValue;
          return resolvedRAccessor(trade);
        })
        .filter((value) => Number.isFinite(value));

  const wins = winSourceValues.filter((value) => value > 0).length;
  const winRate = tradeCount ? (wins / tradeCount) * 100 : 0;

  return {
    tradeCount,
    totalPnl: pnlValues.length ? pnlValues.reduce((sum, value) => sum + value, 0) : null,
    winRate: tradeCount ? winRate : null,
    avgR: rValues.length ? averageNumber(rValues) : null,
    maxDrawdown: tradeCount ? calculateProfitDrawdown(normalizedTrades, profitAccessor, timeAccessor) : null,
    isLowSample: tradeCount > 0 && tradeCount < 5,
  };
}

function normalizeSimulationTradeForPerformance(trade) {
  const asset = String(trade?.asset || trade?.symbol || trade?.ticker || "").trim().toUpperCase();
  const symbol = asset || null;
  const positionIntent = buildPositionIntentMetadata(trade, DEFAULT_POSITION_TYPE);
  const resultR = Number(trade?.rMultiple);
  const profitValue = getTradeProfitValue(trade);
  const setup = normalizeSetupType(trade?.setupType) || String(trade?.setup || "").trim() || "";
  const session = String(
    trade?.session
    || trade?.sessionSlot
    || deriveSessionSlot(trade?.closedAt || trade?.openedAt || trade?.entry_time || trade?.exit_time)
    || ""
  ).trim();
  const normalizeTimestamp = (value) => {
    if (Number.isFinite(Number(value))) {
      return new Date(Number(value)).toISOString();
    }
    const parsed = Date.parse(String(value || ""));
    return Number.isFinite(parsed) ? new Date(parsed).toISOString() : null;
  };
  const entryTime = normalizeTimestamp(trade?.entry_time || trade?.openedAt);
  const exitTime = normalizeTimestamp(trade?.exit_time || trade?.closedAt);
  const createdAt = normalizeTimestamp(trade?.created_at || trade?.openedAt || trade?.closedAt);
  const closedAt = normalizeTimestamp(trade?.closed_at || trade?.closedAt || trade?.exit_time);
  const entryPrice = Number.isFinite(Number(trade?.entry_price)) ? Number(trade.entry_price) : Number.isFinite(Number(trade?.entryPrice)) ? Number(trade.entryPrice) : null;
  const exitPrice = Number.isFinite(Number(trade?.exit_price)) ? Number(trade.exit_price) : Number.isFinite(Number(trade?.exitPrice)) ? Number(trade.exitPrice) : null;
  const amount = Number.isFinite(Number(trade?.amount)) ? Number(trade.amount) : null;
  const amountMode = String(trade?.amountMode || "").trim().toLowerCase();
  const entrySize = Number.isFinite(Number(trade?.entry_size))
    ? Number(trade.entry_size)
    : Number.isFinite(amount) && amountMode === "dollars"
      ? amount
      : Number.isFinite(amount) && Number.isFinite(entryPrice)
        ? amount * entryPrice
        : null;

  return {
    ...trade,
    id: trade?.id || `sim-${asset || "trade"}-${trade?.closedAt || trade?.openedAt || Date.now()}`,
    asset,
    symbol,
    ticker: symbol,
    setup,
    session,
    direction: String(trade?.direction || "").trim().toLowerCase() || null,
    result_r: Number.isFinite(resultR) ? resultR : null,
    pnl_value: Number.isFinite(profitValue) ? profitValue : null,
    profit_loss: Number.isFinite(profitValue) ? profitValue : null,
    profitLoss: Number.isFinite(profitValue) ? profitValue : null,
    profitLossUsd: Number.isFinite(profitValue) ? profitValue : null,
    pnl: Number.isFinite(profitValue) ? profitValue : null,
    entry_size: entrySize,
    size: entrySize,
    qty: Number.isFinite(amount) && amountMode !== "dollars" ? amount : null,
    entry_time: entryTime,
    exit_time: exitTime,
    created_at: createdAt,
    closed_at: closedAt,
    entry_price: entryPrice,
    exit_price: exitPrice,
    source: trade?.source || "live_simulation",
    source_label: trade?.source_label || "Live Simulation",
    positionType: positionIntent.positionType,
    position_type: positionIntent.positionType,
    tradeType: positionIntent.positionType,
    trade_type: positionIntent.positionType,
    positionTypeLabel: positionIntent.positionTypeLabel,
    positionCategory: positionIntent.positionCategory,
    positionIntent: positionIntent.positionIntent,
    entryReason: positionIntent.entryReason,
    entry_reason: positionIntent.entryReason,
    timeHorizon: positionIntent.timeHorizon,
    time_horizon: positionIntent.timeHorizon,
  };
}

function normalizeSimulationTradeForJournal(trade) {
  const normalized = normalizeSimulationTradeForPerformance(trade);
  return {
    ...normalized,
    pnl_value: undefined,
    isBrokerTrade: false,
    source: "live_simulation",
    source_label: "Live Simulation",
  };
}

function getSimulationTradeMarketMode(trade) {
  const explicitMode = String(trade?.marketMode || trade?.mode || trade?.simulationMode || "").trim().toLowerCase();
  if (explicitMode === "scenario") return "scenario";
  if (explicitMode === "live") return "live";
  return trade?.scenarioType ? "scenario" : "live";
}

function isClosedSimulationTrade(trade) {
  return Boolean(
    trade?.closedAt
    || trade?.closed_at
    || trade?.exit_time
    || trade?.exitPrice != null
    || trade?.exit_price != null
    || trade?.profitLoss != null
    || trade?.profit_loss != null
    || trade?.rMultiple != null
    || trade?.result_r != null
  );
}

function isClosedLiveSimulationTradeForPerformance(trade) {
  return isClosedSimulationTrade(trade) && getSimulationTradeMarketMode(trade) === "live";
}

function normalizePerformanceAssetKey(value) {
  return String(value || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function parseStrictDecimal(value, { allowNegative = false } = {}) {
  const raw = String(value ?? "").trim().replace(/[$,]/g, "").replace(/[rR]/g, "");
  if (!raw) return null;
  const pattern = allowNegative ? /^[+-]?(?:\d+|\d*\.\d+)$/ : /^\+?(?:\d+|\d*\.\d+)$/;
  if (!pattern.test(raw)) return null;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatBrokerPerformanceAssetSymbol(value) {
  const compact = normalizePerformanceAssetKey(value);
  const cryptoUsdPair = compact.match(/^([A-Z0-9]{2,8})USD$/);
  if (cryptoUsdPair && CRYPTO_SYMBOL_SET.has(cryptoUsdPair[1])) {
    return `${cryptoUsdPair[1]}/USD`;
  }
  return compact || String(value || "").trim().toUpperCase();
}

function numbersNearlyEqual(a, b, tolerance = 0.0001) {
  const left = Number(a);
  const right = Number(b);
  return Number.isFinite(left) && Number.isFinite(right) && Math.abs(left - right) <= tolerance;
}

function timesNearlyEqual(a, b, toleranceMs = 2 * 60 * 1000) {
  const left = Date.parse(String(a || ""));
  const right = Date.parse(String(b || ""));
  return Number.isFinite(left) && Number.isFinite(right) && Math.abs(left - right) <= toleranceMs;
}

function doesManualTradeMirrorBrokerTrade(manualTrade, brokerTrade) {
  if (!manualTrade || !brokerTrade) return false;
  const manualBrokerKey = manualTrade?.broker_provider && manualTrade?.broker_order_id
    ? `${manualTrade.broker_provider}:${manualTrade.broker_order_id}`
    : "";
  const brokerKey = brokerTrade?.broker_provider && brokerTrade?.broker_order_id
    ? `${brokerTrade.broker_provider}:${brokerTrade.broker_order_id}`
    : "";
  if (manualBrokerKey && brokerKey && manualBrokerKey === brokerKey) return true;

  const manualAsset = normalizePerformanceAssetKey(manualTrade?.asset || manualTrade?.symbol || manualTrade?.ticker);
  const brokerAsset = normalizePerformanceAssetKey(brokerTrade?.asset || brokerTrade?.symbol || brokerTrade?.ticker);
  if (!manualAsset || manualAsset !== brokerAsset) return false;

  const sameExitTime = timesNearlyEqual(manualTrade?.exit_time || manualTrade?.closed_at, brokerTrade?.exit_time || brokerTrade?.closed_at || brokerTrade?.filled_at);
  const sameEntryPrice = numbersNearlyEqual(manualTrade?.entry_price, brokerTrade?.entry_price, 0.01);
  const sameExitPrice = numbersNearlyEqual(manualTrade?.exit_price, brokerTrade?.exit_price, 0.01);
  const sameEntrySize = numbersNearlyEqual(manualTrade?.entry_size, brokerTrade?.entry_size, 0.5);
  return sameExitTime && sameEntryPrice && sameExitPrice && sameEntrySize;
}

function filterBrokerTradesAlreadyLoggedManually(manualTrades, brokerTrades) {
  const normalizedManualTrades = Array.isArray(manualTrades) ? manualTrades : [];
  return (Array.isArray(brokerTrades) ? brokerTrades : []).filter((brokerTrade) =>
    !normalizedManualTrades.some((manualTrade) => doesManualTradeMirrorBrokerTrade(manualTrade, brokerTrade))
  );
}

function parseBrokerFillPrice(trade) {
  const rawPayload = trade?.raw_payload || {};
  const candidates = [
    rawPayload?.filled_avg_price,
    rawPayload?.avg_fill_price,
    rawPayload?.filledAvgPrice,
  ];
  const parsed = Number.parseFloat(candidates.find((value) => value != null) ?? NaN);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function buildNormalizedBrokerTrades(brokerTradeLog) {
  const brokerTradesByKey = new Map();
  (brokerTradeLog || []).forEach((trade) => {
    if (!trade?.broker_provider || !trade?.broker_order_id) return;
    brokerTradesByKey.set(`${trade.broker_provider}:${trade.broker_order_id}`, trade);
  });

  const orderedBrokerTrades = [...brokerTradesByKey.values()]
    .filter((trade) => {
      const status = String(trade?.status || "").toLowerCase();
      return trade?.filled_at && (status === "filled" || status === "partially_filled");
    })
    .map((trade) => ({
      ...trade,
      fillPrice: parseBrokerFillPrice(trade),
      qtyValue: Number.parseFloat(trade?.qty ?? 0),
      filledAtValue: new Date(trade.filled_at).getTime(),
    }))
    .filter((trade) => trade.fillPrice != null && Number.isFinite(trade.qtyValue) && trade.qtyValue > 0)
    .sort((a, b) => {
      const timeA = Number.isFinite(a.filledAtValue) ? a.filledAtValue : 0;
      const timeB = Number.isFinite(b.filledAtValue) ? b.filledAtValue : 0;
      return timeA - timeB;
    });

  const lotsBySymbol = new Map();
  const normalizedClosedTrades = [];

  orderedBrokerTrades.forEach((trade) => {
    const symbol = normalizePerformanceAssetKey(trade.symbol);
    const side = String(trade.side || "").toLowerCase();
    if (!symbol || !side) return;

    if (side === "buy") {
      const existingLots = lotsBySymbol.get(symbol) || [];
      existingLots.push({
        qty: trade.qtyValue,
        price: trade.fillPrice,
        filledAt: trade.filled_at,
        tradeType: normalizePositionType(trade.trade_type || trade.tradeType),
      });
      lotsBySymbol.set(symbol, existingLots);
      return;
    }

    if (side !== "sell") return;

    const existingLots = lotsBySymbol.get(symbol) || [];
    if (!existingLots.length) return;

    let remainingQty = trade.qtyValue;
    let realizedPnl = 0;
    let matchedQty = 0;
    let matchedCost = 0;
    let matchedTradeType = null;
    let earliestEntryTime = null;

    while (remainingQty > 0 && existingLots.length) {
      const currentLot = existingLots[0];
      const matchedLotQty = Math.min(remainingQty, currentLot.qty);
      realizedPnl += (trade.fillPrice - currentLot.price) * matchedLotQty;
      matchedQty += matchedLotQty;
      matchedCost += currentLot.price * matchedLotQty;
      matchedTradeType ||= currentLot.tradeType;
      if (!earliestEntryTime && currentLot.filledAt) earliestEntryTime = currentLot.filledAt;
      currentLot.qty -= matchedLotQty;
      remainingQty -= matchedLotQty;

      if (currentLot.qty <= 0) {
        existingLots.shift();
      }
    }

    if (existingLots.length) lotsBySymbol.set(symbol, existingLots);
    else lotsBySymbol.delete(symbol);

    if (matchedQty > 0 && remainingQty === 0) {
      const avgEntryPrice = matchedCost / matchedQty;
      const closedTradeType = normalizePositionType(matchedTradeType || trade.trade_type || trade.tradeType || DEFAULT_POSITION_TYPE);
      normalizedClosedTrades.push({
        id: `broker:${trade.broker_provider}:${trade.broker_order_id}`,
        asset: formatBrokerPerformanceAssetSymbol(trade.symbol),
        setup: "Broker Import",
        session: "Broker",
        direction: "long",
        entry_price: avgEntryPrice,
        exit_price: trade.fillPrice,
        entry_size: matchedCost,
        entry_time: earliestEntryTime || trade.filled_at,
        exit_time: trade.filled_at,
        result_r: null,
        pnl_value: realizedPnl,
        tradeType: closedTradeType,
        trade_type: closedTradeType,
        positionType: closedTradeType,
        position_type: closedTradeType,
        source: trade.source === "rayla" ? "rayla" : "broker",
        source_label: trade.source === "rayla" ? "Placed in Rayla" : "Imported from Alpaca",
        broker_provider: trade.broker_provider,
        broker_order_id: trade.broker_order_id,
        status: trade.status,
        coachTag: trade.source === "rayla" ? "Executed in Rayla" : "Imported from broker",
        isBrokerTrade: true,
      });
    }
  });

  return normalizedClosedTrades.sort((a, b) => {
    const aTime = parseTradeTimeMs(a) || 0;
    const bTime = parseTradeTimeMs(b) || 0;
    return bTime - aTime;
  });
}

function getBrokerOrderStatusValue(orderOrStatus) {
  if (orderOrStatus && typeof orderOrStatus === "object") {
    return String(orderOrStatus.status || orderOrStatus.raw_payload?.status || orderOrStatus.raw?.status || "").trim().toLowerCase();
  }
  return String(orderOrStatus || "").trim().toLowerCase();
}

function getBrokerOrderSubmittedAt(orderOrStatus, fallbackSubmittedAt = null) {
  if (orderOrStatus && typeof orderOrStatus === "object") {
    return orderOrStatus.submitted_at || orderOrStatus.submittedAt || orderOrStatus.raw_payload?.submitted_at || orderOrStatus.raw?.submitted_at || fallbackSubmittedAt;
  }
  return fallbackSubmittedAt;
}

function getBrokerOrderFilledAt(order) {
  if (!order || typeof order !== "object") return null;
  return order.filled_at || order.filledAt || order.raw_payload?.filled_at || order.raw?.filled_at || null;
}

function getBrokerOrderQty(order) {
  if (!order || typeof order !== "object") return null;
  const qty = Number(order.qty ?? order.quantity ?? order.raw_payload?.qty ?? order.raw?.qty);
  return Number.isFinite(qty) ? Math.abs(qty) : null;
}

function getBrokerOrderFilledQty(order) {
  if (!order || typeof order !== "object") return null;
  const qty = Number(order.filled_qty ?? order.filledQty ?? order.raw_payload?.filled_qty ?? order.raw?.filled_qty);
  return Number.isFinite(qty) ? Math.abs(qty) : null;
}

function isBrokerOrderFullyFilled(orderOrStatus) {
  const status = getBrokerOrderStatusValue(orderOrStatus);
  if (status === "filled") return true;
  if (!orderOrStatus || typeof orderOrStatus !== "object") return false;
  const filledAt = getBrokerOrderFilledAt(orderOrStatus);
  const filledQty = getBrokerOrderFilledQty(orderOrStatus);
  const qty = getBrokerOrderQty(orderOrStatus);
  if (filledAt && (!Number.isFinite(qty) || !Number.isFinite(filledQty) || filledQty >= qty - 0.0001)) return true;
  return Number.isFinite(qty) && qty > 0 && Number.isFinite(filledQty) && filledQty >= qty - 0.0001;
}

function getBrokerOrderStatusPresentation(orderOrStatus, submittedAt = null) {
  const status = getBrokerOrderStatusValue(orderOrStatus);
  const resolvedSubmittedAt = getBrokerOrderSubmittedAt(orderOrStatus, submittedAt);
  const submittedMs = resolvedSubmittedAt ? new Date(resolvedSubmittedAt).getTime() : null;
  const ageMs = Number.isFinite(submittedMs) ? Date.now() - submittedMs : null;
  const isStaleOpenOrder = Number.isFinite(ageMs) && ageMs > 24 * 60 * 60 * 1000;

  if (isBrokerOrderFullyFilled(orderOrStatus)) {
    return { label: "Order filled", color: "#4ade80", background: "rgba(74,222,128,0.12)", border: "rgba(74,222,128,0.24)" };
  }
  if (status === "partially_filled") {
    return { label: "Partially filled", color: "#fbbf24", background: "rgba(251,191,36,0.12)", border: "rgba(251,191,36,0.24)" };
  }
  if (status === "accepted" || status === "new" || status === "pending_new") {
    if (isStaleOpenOrder) {
      return { label: "Order still open in broker sync — refresh/check Alpaca", color: "#fca5a5", background: "rgba(248,113,113,0.12)", border: "rgba(248,113,113,0.24)" };
    }
    return { label: "Order accepted — may fill when market opens", color: "#fb923c", background: "rgba(251,146,60,0.12)", border: "rgba(251,146,60,0.24)" };
  }
  if (status === "done_for_day") {
    return { label: "Order done for day", color: "#fbbf24", background: "rgba(251,191,36,0.12)", border: "rgba(251,191,36,0.24)" };
  }
  if (status === "canceled") {
    return { label: "Order canceled", color: "#f87171", background: "rgba(248,113,113,0.12)", border: "rgba(248,113,113,0.24)" };
  }
  if (status === "rejected") {
    return { label: "Order rejected", color: "#f87171", background: "rgba(248,113,113,0.12)", border: "rgba(248,113,113,0.24)" };
  }
  if (status === "expired") {
    return { label: "Order expired", color: "#94a3b8", background: "rgba(148,163,184,0.12)", border: "rgba(148,163,184,0.24)" };
  }

  return { label: status || "Status unavailable", color: "#cbd5e1", background: "rgba(203,213,225,0.08)", border: "rgba(203,213,225,0.16)" };
}

function getBrokerOrderStatusKind(orderOrStatus) {
  const status = getBrokerOrderStatusValue(orderOrStatus);
  if (isBrokerOrderFullyFilled(orderOrStatus)) return "filled";
  if (status === "canceled" || status === "rejected" || status === "expired") return "failed";
  if (status === "partially_filled") return "partial";
  if (status === "accepted" || status === "new" || status === "pending_new" || status === "done_for_day") return "pending";
  return status ? "unknown" : "none";
}

function findMatchingBrokerOrder(orders, submittedOrder) {
  if (!submittedOrder) return null;
  const submittedId = submittedOrder.id || submittedOrder.broker_order_id;
  const submittedSymbol = submittedOrder.symbol;
  const submittedSide = String(submittedOrder.side || "").trim().toLowerCase();
  const matches = (orders || []).filter((order) => {
    if (submittedId && (order.broker_order_id === submittedId || order.id === submittedId || order.raw_payload?.id === submittedId)) return true;
    return (
      brokerSymbolsMatch(submittedSymbol, order?.symbol)
      && (!submittedSide || submittedSide === String(order.side || "").trim().toLowerCase())
    );
  });
  if (!matches.length) return null;
  const exactIdMatch = submittedId
    ? matches.find((order) => order.broker_order_id === submittedId || order.id === submittedId || order.raw_payload?.id === submittedId)
    : null;
  if (exactIdMatch) return exactIdMatch;
  return [...matches].sort((a, b) => {
    const filledDelta = Number(isBrokerOrderFullyFilled(b)) - Number(isBrokerOrderFullyFilled(a));
    if (filledDelta !== 0) return filledDelta;
    const aTime = new Date(getBrokerOrderSubmittedAt(a) || getBrokerOrderFilledAt(a) || 0).getTime() || 0;
    const bTime = new Date(getBrokerOrderSubmittedAt(b) || getBrokerOrderFilledAt(b) || 0).getTime() || 0;
    return bTime - aTime;
  })[0] || null;
}

function getPendingCloseOrderForPosition(orders, position) {
  if (!position?.symbol) return null;
  const closeSide = position?.side === "short" ? "buy" : "sell";
  return (orders || []).find((order) => {
    const statusKind = getBrokerOrderStatusKind(order);
    if (statusKind !== "pending" && statusKind !== "partial") return false;
    return (
      brokerSymbolsMatch(order?.symbol, position.symbol)
      && String(order?.side || "").trim().toLowerCase() === closeSide
    );
  }) || null;
}

function getLastFailedCloseOrderForPosition(orders, position) {
  if (!position?.symbol) return null;
  const closeSide = position?.side === "short" ? "buy" : "sell";
  return (orders || []).find((order) => (
    getBrokerOrderStatusKind(order) === "failed"
    && brokerSymbolsMatch(order?.symbol, position.symbol)
    && String(order?.side || "").trim().toLowerCase() === closeSide
  )) || null;
}

function buildOrderRealityCheck({ symbol, side, qty, estimatedValue, buyingPower, position }) {
  const insights = [];
  const currentQty = Math.abs(Number(position?.qty ?? 0));

  if (!position || currentQty <= 0) {
    if (side === "buy") {
      insights.push(`This is your first position in ${symbol}.`);
    }
  } else if (side === "buy") {
    insights.push(`You are adding to your ${symbol} position.`);
  } else if (qty >= currentQty) {
    insights.push(`This will close your ${symbol} position.`);
  } else {
    insights.push(`This reduces your ${symbol} exposure.`);
  }

  if (Number.isFinite(estimatedValue) && Number.isFinite(buyingPower) && buyingPower > 0) {
    const buyingPowerUsage = estimatedValue / buyingPower;
    if (buyingPowerUsage >= 0.3) {
      insights.push(`This trade uses ~${Math.round(buyingPowerUsage * 100)}% of your available buying power.`);
    }
  }

  return insights.slice(0, 2);
}

function getAlpacaOrderPayloadSide(action) {
  if (action === "sell" || action === "short_sell") return "sell";
  return "buy";
}

function getAlpacaOrderActionLabel(action) {
  if (action === "short_sell") return "Short Sell";
  if (action === "buy_to_cover") return "Buy to Cover";
  if (action === "sell") return "Sell";
  return "Buy";
}

function getAlpacaCloseActionLabel(action) {
  if (action === "buy_to_cover") return "Buy to Cover";
  return "Sell to Close";
}

async function getSupabaseFunctionErrorMessage(error, fallback = "Request failed.") {
  const context = error?.context;
  if (context && typeof context.json === "function") {
    try {
      const body = await context.json();
      if (body?.error) return body.error;
      if (body?.message) return body.message;
      return JSON.stringify(body);
    } catch {
      try {
        const text = typeof context.text === "function" ? await context.text() : "";
        if (text) return text;
      } catch {
        // Fall through to the generic error message.
      }
    }
  }
  return error?.message || fallback;
}

// Web Locks contention thrown by supabase-js's default navigatorLock during concurrent
// auth-token access. processLock in src/supabase.js prevents this at the source, but we
// still defensively filter it in billing-flow catches so a stray lock error never renders
// as a user-facing "Unable to start checkout" banner.
function isSupabaseAuthLockError(error) {
  if (!error) return false;
  const name = String(error.name || "").toLowerCase();
  const message = String(error.message || error).toLowerCase();
  return name === "aborterror"
    || message.includes("lock was stolen")
    || message.includes("lock broken");
}

function getAlpacaOrderTypeLabel(type) {
  if (type === "stop_limit") return "Stop Limit";
  if (type === "stop") return "Stop";
  if (type === "limit") return "Limit";
  return "Market";
}

function getAlpacaTimeInForceLabel(value) {
  if (value === "day") return "DAY";
  if (value === "gtc") return "GTC";
  if (value === "ioc") return "IOC";
  if (value === "fok") return "FOK";
  return String(value || "").toUpperCase();
}

function getLeverageMultiplierValue(value) {
  const parsed = Number(String(value || "1x").replace(/x/gi, ""));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
}

// Returns a 0-100 y-percentage for an entry price overlay on a live chart,
// or null if the price falls outside the visible range.
// bars must be an array of { high, low } OHLC objects (same structure as extractVisibleChartBars output).
function computeEntryOverlayYPct(bars, entryPrice) {
  if (!Array.isArray(bars) || bars.length < 2) return null;
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) return null;
  const prices = bars.flatMap((b) => [Number(b.high), Number(b.low)]).filter(Number.isFinite);
  if (!prices.length) return null;
  const rawMin = Math.min(...prices);
  const rawMax = Math.max(...prices);
  const range = rawMax - rawMin || 1;
  const pad = range * 0.15; // approximate TradingView auto-fit padding
  const displayMin = rawMin - pad;
  const displayMax = rawMax + pad;
  const yPct = 100 * (1 - (entryPrice - displayMin) / (displayMax - displayMin));
  if (yPct < 4 || yPct > 94) return null; // outside visible range — skip
  return yPct;
}

// Renders the entry price overlay line + label over a TradingViewLiveChart container.
// Parent container must have position: relative and overflow: hidden.
function ChartEntryOverlay({ yPct, entryPrice }) {
  if (yPct == null) return null;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: `${yPct}%`, pointerEvents: "none", zIndex: 10 }}>
      <div style={{
        position: "absolute", left: 0, right: 0, height: 1,
        background: "repeating-linear-gradient(90deg, rgba(124,196,255,0.55) 0, rgba(124,196,255,0.55) 5px, transparent 5px, transparent 11px)",
      }} />
      <div style={{
        position: "absolute", right: 6, top: -11,
        padding: "2px 6px", borderRadius: 4,
        background: "rgba(10,14,20,0.88)", border: "1px solid rgba(124,196,255,0.38)",
        fontSize: 10, fontWeight: 700, color: "#7CC4FF",
        whiteSpace: "nowrap", letterSpacing: "0.3px",
      }}>
        Avg Entry · {formatCurrency(entryPrice)}
      </div>
    </div>
  );
}

function getAvailableLeverageOptions(multiplier) {
  const normalizedMax = Math.max(1, Math.floor(Number(multiplier) || 1));
  const values = [1];

  [2, 4].forEach((candidate) => {
    if (candidate <= normalizedMax && !values.includes(candidate)) {
      values.push(candidate);
    }
  });

  if (!values.includes(normalizedMax)) {
    values.push(normalizedMax);
  }

  return values
    .filter((value) => value >= 1)
    .sort((a, b) => a - b)
    .map((value) => ({ value: `${value}x`, label: `${value}x` }));
}

function getSimulationCoachMessage(position, currentPrice, metrics) {
  if (!position) return "Ready for your next setup.";
  if (!Number.isFinite(currentPrice)) return "Trade is open. Watch how price behaves.";

  if (position.exitMode === "pnl") {
    if (position.stopLoss != null && Number.isFinite(metrics?.profitLoss) && metrics.profitLoss < 0) {
      const stopProgress = Math.abs(metrics.profitLoss) / Math.max(position.stopLoss, 0.0001);
      if (stopProgress >= 0.85) {
        return "Near your stop. Don't move it.";
      }
    }
    if (position.takeProfit != null && Number.isFinite(metrics?.profitLoss) && metrics.profitLoss > 0) {
      const targetProgress = metrics.profitLoss / Math.max(position.takeProfit, 0.0001);
      if (targetProgress >= 0.85) {
        return "Near your target. Let it work.";
      }
    }
  } else {
    if (position.stopLoss != null) {
      const stopDistance = Math.abs(position.entryPrice - position.stopLoss);
      const remainingToStop = Math.abs(currentPrice - position.stopLoss);
      if (stopDistance > 0 && remainingToStop / stopDistance <= 0.15) {
        return "Near your stop. Don't move it.";
      }
    }
    if (position.takeProfit != null) {
      const targetDistance = Math.abs(position.takeProfit - position.entryPrice);
      const remainingToTarget = Math.abs(position.takeProfit - currentPrice);
      if (targetDistance > 0 && remainingToTarget / targetDistance <= 0.15) {
        return "Near your target. Let it work.";
      }
    }
  }

  if (Number.isFinite(metrics?.profitLoss) && metrics.profitLoss > 0) {
    return "In profit. Stay patient.";
  }

  return "Trade is open. Watch how price behaves.";
}

function didLiveSimulationStopWiden(position, nextStopLoss) {
  if (!position || (position.marketMode || "live") !== "live") return false;
  if (position.stopWidenedObserved) return false;
  if (position.exitMode !== "price") return false;

  const entryPrice = Number(position.entryPrice);
  const originalStopLoss = Number(position.originalStopLoss);
  const candidateStopLoss = Number(nextStopLoss);

  if (!Number.isFinite(entryPrice) || !Number.isFinite(originalStopLoss) || !Number.isFinite(candidateStopLoss)) {
    return false;
  }

  const originalDistance = Math.abs(entryPrice - originalStopLoss);
  const nextDistance = Math.abs(entryPrice - candidateStopLoss);
  if (!(nextDistance > originalDistance + 1e-9)) return false;

  if (position.direction === "long") {
    return candidateStopLoss < originalStopLoss && candidateStopLoss < entryPrice;
  }
  if (position.direction === "short") {
    return candidateStopLoss > originalStopLoss && candidateStopLoss > entryPrice;
  }

  return false;
}

function getSimulationLeverageMultiplier(leverageValue) {
  const parsed = Number.parseFloat(String(leverageValue || "1x").replace(/x/i, ""));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
}

