// Priority order: more specific templates checked before more general ones
const TEMPLATE_PRIORITY = [
  "DocumentIntelligence",
  "StrategyScanner",
  "PortfolioAddition",
  "OpportunityRanking",
  "CashDeployment",
  "MarketSnapshot",
  "RiskAssessment",
  "TradeReview",
  "PortfolioReview",
  "MarketIntel",
  "PersonalPicks",
  "Educational",
];

function classifyQuestion(question, screenSource) {
  if (!question || question.length < 4) return null;
  let bestKey = null;
  let bestScore = 0;
  for (const key of TEMPLATE_PRIORITY) {
    const tmpl = RESPONSE_TEMPLATES[key];
    let score = 0;
    for (const pattern of tmpl.patterns) {
      if (pattern.test(question)) { score += 2; break; }
    }
    if (tmpl.screenBoost.includes(screenSource)) score += 1;
    if (score > bestScore) { bestScore = score; bestKey = key; }
  }
  return bestScore >= 2 ? bestKey : null;
}

function getResponseTemplate(templateType) {
  if (!templateType || !RESPONSE_TEMPLATES[templateType]) return null;
  const tmpl = RESPONSE_TEMPLATES[templateType];
  return `[Rayla response format — ${tmpl.label}]\n${tmpl.instruction}`;
}

// ─── Universal Screen Context ─────────────────────────────────────────────────

const PICKS_CACHE_STORAGE_KEY = "rayla-picks-cache-v1";

function loadPicksCacheForContext() {
  try {
    const raw = typeof window !== "undefined" ? window.localStorage.getItem(PICKS_CACHE_STORAGE_KEY) : null;
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed?.picks?.length) return null;
    const savedAt = parsed.generatedAt || parsed.timestamp || 0;
    const ageMs = Date.now() - savedAt;
    if (ageMs > 7 * 24 * 60 * 60 * 1000) return null; // 7-day TTL matches component
    return parsed.picks;
  } catch { return null; }
}

function detectScreenSource({ activeTab, performancePositionFilter, raylaActiveReviewedTrade, intelSubTab }) {
  if (activeTab === "home") return "Home";
  if (activeTab === "ai") {
    if (performancePositionFilter === "holdings") return "Holdings";
    return "Portfolio";
  }
  if (activeTab === "picks") return "PersonalPicks";
  if (activeTab === "intel") return intelSubTab === "picks" ? "PersonalPicks" : "MarketIntel";
  if (activeTab === "journal") {
    if (raylaActiveReviewedTrade) return "TradeReview";
    return "Journal";
  }
  if (activeTab === "simulation") return "Simulation";
  if (activeTab === "trades") return "LiveTrades";
  return "General";
}

// ─── Portfolio Risk Engine ────────────────────────────────────────────────────

function buildPortfolioRiskContext({ positions, account }) {
  if (!Array.isArray(positions) || !positions.length) return null;
  const equity = Number(account?.equity ?? account?.portfolioValue ?? 0);
  if (!equity || equity <= 0) return null;

  const fmtM = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? `$${n.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 })}` : "—";
  };

  const withConc = positions
    .map((p) => ({
      symbol: String(p.symbol || ""),
      mv: Number(p.market_value ?? p.marketValue ?? 0),
      assetClass: p.assetClass || p.asset_class || "",
    }))
    .filter((p) => p.symbol && Number.isFinite(p.mv) && p.mv > 0)
    .map((p) => ({ ...p, conc: (p.mv / equity) * 100 }))
    .sort((a, b) => b.conc - a.conc);

  if (!withConc.length) return null;

  const n = withConc.length;
  const totalInvested = withConc.reduce((s, p) => s + p.mv, 0);
  const cashPct = Math.max(0, ((equity - totalInvested) / equity) * 100);
  const maxPct = n <= 3 ? 25 : n <= 5 ? 20 : n <= 10 ? 15 : 10;
  const maxDollar = (equity * maxPct) / 100;

  const lines = ["[Portfolio Risk Engine]"];
  lines.push(`Positions: ${n} | Cash: ${cashPct.toFixed(1)}% | Total equity: ${fmtM(equity)}`);

  lines.push("Concentration:");
  withConc.forEach((p) => {
    const flag = p.conc >= 30 ? " ⚠ HIGH" : p.conc >= 20 ? " △ WATCH" : "";
    lines.push(`  ${p.symbol}: ${p.conc.toFixed(1)}%${flag}`);
  });

  const flags = [];
  withConc.forEach((p) => {
    if (p.conc >= 30) flags.push(`⚠ ${p.symbol} at ${p.conc.toFixed(1)}% — overconcentrated (suggested max: 25%)`);
    else if (p.conc >= 20) flags.push(`△ ${p.symbol} at ${p.conc.toFixed(1)}% — approaching concentration limit`);
  });
  if (n === 1) flags.push("⚠ Single-position portfolio — no diversification");
  else if (n <= 3) flags.push(`△ ${n}-position portfolio — highly concentrated`);
  if (n > 15) flags.push(`△ ${n} positions — verify each is a high-conviction holding`);
  if (cashPct > 40) flags.push(`△ ${cashPct.toFixed(0)}% cash — large uninvested balance`);

  if (flags.length) {
    lines.push("Risk flags:");
    flags.forEach((f) => lines.push(`  ${f}`));
  } else {
    lines.push("Risk flags: None — concentration within reasonable bounds");
  }

  lines.push(`Sizing guidance: Max recommended per new position — ${maxPct}% (${fmtM(maxDollar)}) given ${n} existing positions`);

  const classes = [...new Set(withConc.map((p) => p.assetClass).filter(Boolean))];
  if (classes.length > 1) lines.push(`Asset classes held: ${classes.join(", ")}`);

  return lines.join("\n");
}

// ─── Market Snapshot Layer ────────────────────────────────────────────────────

const MARKET_SNAPSHOT_STORAGE_KEY = "rayla-market-snapshot-v1";
const MARKET_SNAPSHOT_TTL_MS = 15 * 60 * 1000; // 15 minutes
const MARKET_SNAPSHOT_SYMBOLS = ["SPY", "QQQ", "VIX", "XLK", "XLF", "XLE", "XLV", "XLI"];

function classifyMarketRegime(quotes) {
  if (!quotes) return null;
  const spyChg = quotes.SPY?.change ?? null;
  const qqqChg = quotes.QQQ?.change ?? null;
  const vixPx  = quotes.VIX?.price  ?? null;
  const xlkChg = quotes.XLK?.change ?? null;
  const xleChg = quotes.XLE?.change ?? null;

  let riskOn = 0;
  let riskOff = 0;

  if (spyChg !== null) { if (spyChg >  0.5) riskOn++; else if (spyChg < -0.5) riskOff++; }
  if (qqqChg !== null) { if (qqqChg >  0.5) riskOn++; else if (qqqChg < -0.5) riskOff++; }
  if (vixPx  !== null) { if (vixPx  < 17)   riskOn++; else if (vixPx > 25) riskOff++; else if (vixPx > 20) riskOff += 0.5; }
  // Tech leading energy = risk-on; energy leading tech = rotation/risk-off signal
  if (xlkChg !== null && xleChg !== null) {
    if (xlkChg > xleChg + 0.5) riskOn++;
    else if (xleChg > xlkChg + 0.5) riskOff += 0.5;
  }

  if (riskOn >= 2 && riskOff === 0) return "Risk-On";
  if (riskOff >= 2) return "Risk-Off";
  if (riskOn === 0 && riskOff === 0) return null; // not enough data
  return "Neutral";
}

function buildMarketSnapshotContext(snapshot) {
  if (!snapshot?.quotes || !snapshot.fetchedAt) return null;

  const q = snapshot.quotes;
  const regime = classifyMarketRegime(q);
  const ageMs = Date.now() - new Date(snapshot.fetchedAt).getTime();
  const ageMin = Math.round(ageMs / 60000);
  const timeLabel = new Date(snapshot.fetchedAt).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" });

  const fmtChg = (chg) => chg != null ? ` (${chg >= 0 ? "+" : ""}${Number(chg).toFixed(2)}%)` : "";
  const fmtPx  = (px)  => px  != null ? `$${Number(px).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : null;

  const lines = [`[Market Snapshot — as of ${timeLabel}, ${ageMin}m ago]`];
  if (regime) lines.push(`Market regime: ${regime}`);

  // Major indices
  const indices = [];
  if (q.SPY?.price) indices.push(`SPY: ${fmtPx(q.SPY.price)}${fmtChg(q.SPY.change)}`);
  if (q.QQQ?.price) indices.push(`QQQ: ${fmtPx(q.QQQ.price)}${fmtChg(q.QQQ.change)}`);
  if (q.VIX?.price) indices.push(`VIX: ${Number(q.VIX.price).toFixed(2)}${fmtChg(q.VIX.change)}`);
  else              indices.push("VIX: unavailable");
  if (indices.length) lines.push(`Indices: ${indices.join(" | ")}`);

  // Sector ETFs
  const sectorSymbols = ["XLK", "XLF", "XLE", "XLV", "XLI"];
  const sectorLines = sectorSymbols
    .filter(s => q[s]?.price)
    .map(s => `${s}${fmtChg(q[s].change)}`);
  if (sectorLines.length) lines.push(`Sectors: ${sectorLines.join(" | ")}`);

  // Leading / lagging sectors
  const sectorChanges = sectorSymbols
    .filter(s => q[s]?.change != null)
    .map(s => ({ symbol: s, change: q[s].change }))
    .sort((a, b) => b.change - a.change);
  if (sectorChanges.length >= 2) {
    const best  = sectorChanges[0];
    const worst = sectorChanges[sectorChanges.length - 1];
    lines.push(`Leading sector today: ${best.symbol} (${best.change >= 0 ? "+" : ""}${best.change.toFixed(2)}%)`);
    lines.push(`Lagging sector today: ${worst.symbol} (${worst.change >= 0 ? "+" : ""}${worst.change.toFixed(2)}%)`);
  }

  return lines.join("\n");
}

// ─── End Market Snapshot Layer ────────────────────────────────────────────────

// ─── Document Intelligence Layer ─────────────────────────────────────────────

const DOCUMENT_INTELLIGENCE_STORAGE_KEY = "rayla-document-intelligence-v1";
const DOCUMENT_INTELLIGENCE_TTL_MS = 4 * 60 * 60 * 1000; // 4 hours

const DOCUMENT_TYPES = {
  EarningsReport: "Earnings Report",
  BalanceSheet: "Balance Sheet",
  IncomeStatement: "Income Statement",
  CashFlow: "Cash Flow Statement",
  NewsArticle: "News Article",
  Unknown: "Unknown",
};

const DOCUMENT_TYPE_PATTERNS = {
  EarningsReport: [
    /earnings per share|\bEPS\b/i,
    /revenue.{0,20}(quarter|year|period)/i,
    /beat.{0,15}estimate|miss.{0,15}estimate/i,
    /guidance for.{0,20}(quarter|year|Q[1-4])/i,
    /adjusted.{0,10}EPS|GAAP.{0,10}EPS|diluted EPS/i,
    /net income.{0,20}attributable|earnings release/i,
  ],
  BalanceSheet: [
    /total assets|total liabilities/i,
    /shareholders.{0,5}equity|stockholders.{0,5}equity/i,
    /current assets|current liabilities/i,
    /long.term debt|short.term debt/i,
    /\bgoodwill\b|\bintangible assets\b/i,
    /balance sheet|financial position/i,
  ],
  IncomeStatement: [
    /gross profit|gross margin/i,
    /operating income|operating expenses/i,
    /income from operations|operating profit/i,
    /selling.{0,10}general.{0,10}administrative|\bSG&A\b/i,
    /research.{0,10}development.{0,10}expense|\bR&D\b.{0,10}expense/i,
    /income statement|statement of (operations|earnings)/i,
  ],
  CashFlow: [
    /cash flow from operations|operating activities/i,
    /capital expenditures|\bcapex\b/i,
    /free cash flow|\bFCF\b/i,
    /investing activities|financing activities/i,
    /depreciation.{0,10}amortization/i,
    /statement of cash flows/i,
  ],
  NewsArticle: [
    /according to|reported that|announced that/i,
    /shares (rose|fell|gained|dropped|surged|plunged)/i,
    /\b(Reuters|Bloomberg|CNBC|WSJ|Financial Times|Barron|MarketWatch)\b/i,
    /the company (said|announced|reported)/i,
    /stock (rose|fell|gained|dropped|surged|plunged)/i,
  ],
};

function detectDocumentType(rawText) {
  if (!rawText || rawText.length < 30) return "Unknown";
  const text = String(rawText);
  const scores = {};
  for (const [type, patterns] of Object.entries(DOCUMENT_TYPE_PATTERNS)) {
    scores[type] = patterns.filter((p) => p.test(text)).length;
  }
  const best = Object.entries(scores).sort((a, b) => b[1] - a[1])[0];
  return (best && best[1] >= 2) ? best[0] : "Unknown";
}

// Extraction prompt templates — sent to Claude when a document is uploaded (future upload UI)
const DOCUMENT_EXTRACTION_PROMPTS = {
  EarningsReport: `Analyze this earnings report and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"period":null,"revenue":null,"revenueGrowth":null,"eps":null,"epsBeat":null,"guidance":null,"guidanceDirection":null,"grossMargin":null,"operatingMargin":null,"netMargin":null,"managementTone":null,"keyPositives":[],"keyNegatives":[],"bullCase":null,"bearCase":null,"surprises":null}
Rules: epsBeat="beat"/"miss"/"in-line"/null. guidanceDirection="raised"/"lowered"/"maintained"/null. managementTone="confident"/"cautious"/"neutral"/"mixed". Use null for any field not found. Source:`,

  BalanceSheet: `Analyze this balance sheet and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"period":null,"totalCash":null,"totalDebt":null,"netCash":null,"currentRatio":null,"debtToEquity":null,"goodwill":null,"financialStrength":null,"leverageTrend":null,"liquidityRisk":null,"redFlags":[],"keyStrengths":[],"summary":null}
Rules: financialStrength="strong"/"adequate"/"weak"/"stressed". leverageTrend="improving"/"deteriorating"/"stable"/null. liquidityRisk="low"/"moderate"/"high". Use null for any field not found. Source:`,

  IncomeStatement: `Analyze this income statement and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"period":null,"revenue":null,"revenueGrowth":null,"grossMargin":null,"grossMarginTrend":null,"operatingMargin":null,"operatingMarginTrend":null,"netMargin":null,"operatingLeverage":null,"ebitda":null,"profitabilityAssessment":null,"keyDrivers":[],"concerns":[],"summary":null}
Rules: *Trend="expanding"/"contracting"/"stable"/null. operatingLeverage="positive"/"negative"/"neutral". profitabilityAssessment="strong"/"adequate"/"weak"/"improving"/"deteriorating". Use null for any field not found. Source:`,

  CashFlow: `Analyze this cash flow statement and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"period":null,"operatingCashFlow":null,"capex":null,"freeCashFlow":null,"fcfMargin":null,"fcfToNetIncome":null,"earningsQuality":null,"cashConversion":null,"dividendsPaid":null,"buybacksAmount":null,"debtRepayment":null,"concerns":[],"summary":null}
Rules: earningsQuality="high"/"adequate"/"low"/"concern". cashConversion="strong"/"adequate"/"weak". Use null for any field not found. Source:`,

  NewsArticle: `Analyze this financial news article and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"headline":null,"publicationDate":null,"source":null,"catalyst":null,"sentiment":null,"priceImpact":null,"riskIdentified":null,"opportunityIdentified":null,"isTimeSensitive":false,"affectedSectors":[],"keyFacts":[],"summary":null}
Rules: sentiment="positive"/"negative"/"neutral"/"mixed". Use null for any field not found. Source:`,

  Unknown: `Analyze this financial document and return ONLY valid JSON with these exact fields:
{"symbol":null,"company":null,"documentDescription":null,"keyFindings":[],"risks":[],"opportunities":[],"summary":null}
Use null for any field not found. Source:`,
};

function buildDocumentExtractionPrompt(documentType, rawText) {
  const template = DOCUMENT_EXTRACTION_PROMPTS[documentType] || DOCUMENT_EXTRACTION_PROMPTS.Unknown;
  return `${template}\n\n"""\n${String(rawText || "").slice(0, 12000)}\n"""`;
}

function loadDocumentIntelligence() {
  try {
    const raw = sessionStorage.getItem(DOCUMENT_INTELLIGENCE_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed?.analyzedAt && Date.now() - new Date(parsed.analyzedAt).getTime() > DOCUMENT_INTELLIGENCE_TTL_MS) {
      sessionStorage.removeItem(DOCUMENT_INTELLIGENCE_STORAGE_KEY);
      return null;
    }
    return parsed;
  } catch { return null; }
}

function saveDocumentIntelligence(intel) {
  if (!intel) return null;
  const payload = { ...intel, analyzedAt: new Date().toISOString() };
  try { sessionStorage.setItem(DOCUMENT_INTELLIGENCE_STORAGE_KEY, JSON.stringify(payload)); } catch { /* ignore */ }
  return payload;
}

function clearDocumentIntelligence() {
  try { sessionStorage.removeItem(DOCUMENT_INTELLIGENCE_STORAGE_KEY); } catch { /* ignore */ }
}

function buildDocumentIntelligenceContext(docIntel) {
  if (!docIntel?.documentType) return null;
  const typeName = DOCUMENT_TYPES[docIntel.documentType] || "Document";
  const lines = [`[Document Intelligence — ${typeName}]`];

  const id = [docIntel.company, docIntel.symbol ? `(${docIntel.symbol})` : null, docIntel.period].filter(Boolean).join(" ");
  if (id) lines.push(`Source: ${id}`);
  if (docIntel.summary) lines.push(`Summary: ${docIntel.summary}`);

  if (docIntel.documentType === "EarningsReport") {
    const rev = [docIntel.revenue, docIntel.revenueGrowth].filter(Boolean).join(" ");
    if (rev) lines.push(`Revenue: ${rev}`);
    const eps = [docIntel.eps, docIntel.epsBeat].filter(Boolean).join(" — ");
    if (eps) lines.push(`EPS: ${eps}`);
    if (docIntel.grossMargin) lines.push(`Gross margin: ${docIntel.grossMargin}`);
    if (docIntel.operatingMargin) lines.push(`Operating margin: ${docIntel.operatingMargin}`);
    if (docIntel.guidance) lines.push(`Guidance: ${String(docIntel.guidance).slice(0, 200)}${docIntel.guidanceDirection ? ` [${docIntel.guidanceDirection}]` : ""}`);
    if (docIntel.managementTone) lines.push(`Management tone: ${docIntel.managementTone}`);
    if (docIntel.bullCase) lines.push(`Bull case: ${docIntel.bullCase}`);
    if (docIntel.bearCase) lines.push(`Bear case: ${docIntel.bearCase}`);
    if (docIntel.surprises) lines.push(`Surprises: ${docIntel.surprises}`);
  }

  if (docIntel.documentType === "BalanceSheet") {
    if (docIntel.totalCash) lines.push(`Cash: ${docIntel.totalCash}`);
    if (docIntel.totalDebt) lines.push(`Total debt: ${docIntel.totalDebt}`);
    if (docIntel.netCash) lines.push(`Net cash position: ${docIntel.netCash}`);
    if (docIntel.currentRatio) lines.push(`Current ratio: ${docIntel.currentRatio}`);
    if (docIntel.debtToEquity) lines.push(`Debt/equity: ${docIntel.debtToEquity}`);
    if (docIntel.financialStrength) lines.push(`Financial strength: ${docIntel.financialStrength}`);
    if (docIntel.liquidityRisk) lines.push(`Liquidity risk: ${docIntel.liquidityRisk}`);
    if (docIntel.leverageTrend) lines.push(`Leverage trend: ${docIntel.leverageTrend}`);
  }

  if (docIntel.documentType === "IncomeStatement") {
    const rev = [docIntel.revenue, docIntel.revenueGrowth].filter(Boolean).join(" ");
    if (rev) lines.push(`Revenue: ${rev}`);
    if (docIntel.grossMargin) lines.push(`Gross margin: ${docIntel.grossMargin}${docIntel.grossMarginTrend ? ` [${docIntel.grossMarginTrend}]` : ""}`);
    if (docIntel.operatingMargin) lines.push(`Operating margin: ${docIntel.operatingMargin}${docIntel.operatingMarginTrend ? ` [${docIntel.operatingMarginTrend}]` : ""}`);
    if (docIntel.operatingLeverage) lines.push(`Operating leverage: ${docIntel.operatingLeverage}`);
    if (docIntel.profitabilityAssessment) lines.push(`Profitability: ${docIntel.profitabilityAssessment}`);
  }

  if (docIntel.documentType === "CashFlow") {
    if (docIntel.operatingCashFlow) lines.push(`Operating cash flow: ${docIntel.operatingCashFlow}`);
    if (docIntel.capex) lines.push(`Capex: ${docIntel.capex}`);
    if (docIntel.freeCashFlow) lines.push(`Free cash flow: ${docIntel.freeCashFlow}`);
    if (docIntel.fcfMargin) lines.push(`FCF margin: ${docIntel.fcfMargin}`);
    if (docIntel.fcfToNetIncome) lines.push(`FCF/Net income: ${docIntel.fcfToNetIncome}`);
    if (docIntel.earningsQuality) lines.push(`Earnings quality: ${docIntel.earningsQuality}`);
    if (docIntel.cashConversion) lines.push(`Cash conversion: ${docIntel.cashConversion}`);
    if (docIntel.buybacksAmount) lines.push(`Buybacks: ${docIntel.buybacksAmount}`);
  }

  if (docIntel.documentType === "NewsArticle") {
    if (docIntel.headline) lines.push(`Headline: ${String(docIntel.headline).slice(0, 150)}`);
    if (docIntel.catalyst) lines.push(`Catalyst: ${docIntel.catalyst}`);
    if (docIntel.sentiment) lines.push(`Sentiment: ${docIntel.sentiment}`);
    if (docIntel.priceImpact) lines.push(`Price impact: ${docIntel.priceImpact}`);
    if (docIntel.riskIdentified) lines.push(`Risk: ${docIntel.riskIdentified}`);
    if (docIntel.opportunityIdentified) lines.push(`Opportunity: ${docIntel.opportunityIdentified}`);
  }

  const findings = Array.isArray(docIntel.keyFindings || docIntel.keyPositives || docIntel.keyFacts)
    ? (docIntel.keyFindings || docIntel.keyPositives || docIntel.keyFacts || []) : [];
  if (findings.length) lines.push(`Key findings: ${findings.slice(0, 3).join(" | ")}`);

  const risks = Array.isArray(docIntel.risks || docIntel.redFlags || docIntel.concerns || docIntel.keyNegatives)
    ? (docIntel.risks || docIntel.redFlags || docIntel.concerns || docIntel.keyNegatives || []) : [];
  if (risks.length) lines.push(`Risks: ${risks.slice(0, 3).join(" | ")}`);

  const opps = Array.isArray(docIntel.opportunities || docIntel.keyStrengths)
    ? (docIntel.opportunities || docIntel.keyStrengths || []) : [];
  if (opps.length) lines.push(`Opportunities: ${opps.slice(0, 3).join(" | ")}`);

  if (docIntel.analyzedAt) {
    const ageMin = Math.round((Date.now() - new Date(docIntel.analyzedAt).getTime()) / 60000);
    if (ageMin < 240) lines.push(`Analyzed: ${ageMin}m ago this session`);
  }

  return lines.join("\n");
}

// ─── End Document Intelligence Layer ─────────────────────────────────────────

// ─── Fundamentals Feed Layer ──────────────────────────────────────────────────

const FUNDAMENTALS_STORAGE_KEY = "rayla-fundamentals-cache-v1";
const FUNDAMENTALS_TTL_MS = 60 * 60 * 1000; // 1 hour

function loadFundamentalsCache() {
  try {
    const raw = sessionStorage.getItem(FUNDAMENTALS_STORAGE_KEY);
    return raw ? (JSON.parse(raw) || {}) : {};
  } catch { return {}; }
}

function saveFundamentalsCache(cache) {
  try { sessionStorage.setItem(FUNDAMENTALS_STORAGE_KEY, JSON.stringify(cache)); } catch { /* ignore */ }
}

function formatFundamentalsMillions(millionsUSD) {
  const v = Number(millionsUSD);
  if (!Number.isFinite(v) || v <= 0) return null;
  if (v >= 1000000) return `$${(v / 1000000).toFixed(2)}T`;
  if (v >= 1000) return `$${(v / 1000).toFixed(1)}B`;
  return `$${v.toFixed(0)}M`;
}

function buildFundamentalsContext(symbols, cache) {
  if (!cache || !Array.isArray(symbols) || symbols.length === 0) return null;
  const blocks = [];
  for (const sym of symbols) {
    const d = cache[String(sym).toUpperCase()];
    if (!d?.fetchedAt) continue;
    const lines = [`[Fundamentals — ${sym}]`];
    let hasData = false;
    const rev = formatFundamentalsMillions(d.revenueTTM);
    if (rev) { lines.push(`Revenue (TTM): ${rev}`); hasData = true; }
    if (d.revenueGrowth3Y != null) { lines.push(`Revenue Growth (3Y): ${Number(d.revenueGrowth3Y).toFixed(1)}%`); hasData = true; }
    if (d.epsTTM != null) { lines.push(`EPS (TTM): $${Number(d.epsTTM).toFixed(2)}`); hasData = true; }
    if (d.epsGrowth3Y != null) { lines.push(`EPS Growth (3Y): ${Number(d.epsGrowth3Y).toFixed(1)}%`); hasData = true; }
    if (d.grossMarginTTM != null) { lines.push(`Gross Margin: ${Number(d.grossMarginTTM).toFixed(1)}%`); hasData = true; }
    if (d.operatingMarginTTM != null) { lines.push(`Operating Margin: ${Number(d.operatingMarginTTM).toFixed(1)}%`); hasData = true; }
    if (d.netMarginTTM != null) { lines.push(`Net Margin: ${Number(d.netMarginTTM).toFixed(1)}%`); hasData = true; }
    if (d.peTTM != null) { lines.push(`P/E (TTM): ${Number(d.peTTM).toFixed(1)}x`); hasData = true; }
    const mktCap = formatFundamentalsMillions(d.marketCapitalization);
    if (mktCap) { lines.push(`Market Cap: ${mktCap}`); hasData = true; }
    if (hasData) blocks.push(lines.join("\n"));
  }
  return blocks.length > 0 ? blocks.join("\n\n") : null;
}

// ─── End Fundamentals Feed Layer ─────────────────────────────────────────────

// ─── Strategy Scanner Layer ───────────────────────────────────────────────────

const SCANNER_STORAGE_KEY = "rayla-scanner-results-v1";
const SCANNER_TTL_MS = 15 * 60 * 1000; // 15 minutes

function loadScannerResults() {
  try {
    const raw = sessionStorage.getItem(SCANNER_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed?.fetchedAt && Date.now() - new Date(parsed.fetchedAt).getTime() > SCANNER_TTL_MS) {
      sessionStorage.removeItem(SCANNER_STORAGE_KEY);
      return null;
    }
    return parsed?.results || null;
  } catch { return null; }
}

function saveScannerResults(results) {
  try { sessionStorage.setItem(SCANNER_STORAGE_KEY, JSON.stringify({ results, fetchedAt: new Date().toISOString() })); } catch { /* ignore */ }
}

function buildScannerContext(results) {
  if (!results || typeof results !== "object") return null;
  const entries = Object.values(results).filter((r) => r && !r.insufficient && r.symbol);
  if (entries.length === 0) return null;
  entries.sort((a, b) => (b.rs ?? -999) - (a.rs ?? -999));
  const lines = ["[Scanner Results]"];
  for (const r of entries.slice(0, 10)) {
    lines.push(`\n${r.symbol}:`);
    lines.push(`  Relative Strength: ${r.rs != null ? `${r.rs}× vs SPY` : "unavailable"}`);
    lines.push(`  Momentum (20d): ${r.roc20 != null ? `${r.roc20 >= 0 ? "+" : ""}${r.roc20}%` : "unavailable"}`);
    lines.push(`  Above 50 EMA: ${r.aboveEma50 != null ? (r.aboveEma50 ? "Yes" : "No") : "unavailable"}`);
    lines.push(`  Trend: ${r.trend || "unavailable"}`);
  }
  return lines.join("\n");
}

// ─── End Strategy Scanner Layer ───────────────────────────────────────────────

// ─── Opportunity Ranking Engine ───────────────────────────────────────────────

function buildOpportunityRanking({ scannerResults, fundamentalsCache, positions, account }) {
  const results = scannerResults && typeof scannerResults === "object" ? scannerResults : {};
  const funds = fundamentalsCache && typeof fundamentalsCache === "object" ? fundamentalsCache : {};
  const heldPositions = Array.isArray(positions) ? positions : [];
  const totalEquity = Number(account?.equity ?? account?.portfolioValue ?? 0);

  const picks = loadPicksCacheForContext();
  const pickSymbols = new Set(
    (Array.isArray(picks) ? picks : []).map((p) => String(p.symbol || p.ticker || "").toUpperCase()).filter(Boolean)
  );

  // Build concentration map for held positions
  const heldMap = {};
  heldPositions.forEach((p) => {
    const sym = String(p.symbol || "").toUpperCase();
    const mv = Number(p.market_value ?? p.marketValue);
    if (sym) heldMap[sym] = totalEquity > 0 && Number.isFinite(mv) && mv > 0 ? (mv / totalEquity) * 100 : null;
  });

  // Market regime from SPY ROC20
  const spyROC20 = results["SPY"]?.roc20 ?? null;
  let regimeLabel = "Neutral";
  let momentumMult = 1.0;
  let qualityMult = 1.0;
  if (spyROC20 != null) {
    if (spyROC20 > 5)  { regimeLabel = "Bull"; momentumMult = 1.2; qualityMult = 0.9; }
    else if (spyROC20 < -5) { regimeLabel = "Bear"; momentumMult = 0.8; qualityMult = 1.2; }
  }

  // Candidate pool: scanner symbols (excl SPY) + picks not yet in scanner
  const candidateSymbols = new Set(
    Object.keys(results).filter((s) => s !== "SPY" && !results[s]?.insufficient)
  );
  for (const sym of pickSymbols) { if (sym !== "SPY") candidateSymbols.add(sym); }

  const ranked = [];
  for (const sym of candidateSymbols) {
    const scan = results[sym] || {};
    const fund = funds[sym] || {};
    const rs = scan.rs ?? null;
    const roc20 = scan.roc20 ?? null;
    const aboveEma50 = scan.aboveEma50 ?? null;
    const trend = scan.trend ?? "Neutral";

    // Technical (0–40)
    let technical = 0;
    if (rs != null) {
      if (rs > 1.2) technical += 20;
      else if (rs > 1.05) technical += 12;
      else if (rs >= 1.0) technical += 5;
    }
    if (trend === "Bullish") technical += 12;
    else if (trend === "Rising") technical += 7;
    else if (trend === "Neutral") technical += 3;
    if (aboveEma50 === true) technical += 8;

    // Momentum (0–25, regime-adjusted)
    let momentum = 0;
    if (roc20 != null) {
      if (roc20 > 15) momentum = 25;
      else if (roc20 > 8) momentum = 18;
      else if (roc20 > 3) momentum = 10;
      else if (roc20 >= 0) momentum = 4;
    }
    momentum = Math.min(25, Math.round(momentum * momentumMult));

    // Quality (0–20, regime-adjusted) — graceful zero when fundamentals absent
    let quality = 0;
    const hasFund = fund.epsTTM != null || fund.revenueTTM != null || fund.grossMarginTTM != null;
    if (hasFund) {
      if ((fund.epsGrowth3Y ?? 0) > 0) quality += 8;
      if ((fund.revenueGrowth3Y ?? 0) > 0) quality += 7;
      if ((fund.grossMarginTTM ?? 0) > 40) quality += 5;
      if ((fund.peTTM ?? 0) > 50) quality -= 5;
      quality = Math.max(0, Math.min(20, Math.round(quality * qualityMult)));
    }

    // Alignment (0–15, can go negative for heavy concentration)
    let alignment = 0;
    if (pickSymbols.has(sym)) alignment += 10;
    const conc = heldMap[sym];
    if (!(sym in heldMap)) alignment += 5; // fresh add
    else if (conc != null && conc > 25) alignment -= 5; // already heavy

    const score = Math.min(100, Math.max(0, technical + momentum + quality + alignment));

    // Confidence: 3 of 3 signals = High, 2 = Medium, else Low
    const sigCount = [rs != null && rs > 1.1, aboveEma50 === true, trend === "Bullish" || trend === "Rising"].filter(Boolean).length;
    const confidence = sigCount >= 3 ? "High" : sigCount === 2 ? "Medium" : "Low";

    // Reason sentence from top signals
    const reasonParts = [];
    if (rs != null) reasonParts.push(`RS ${rs}× vs SPY`);
    if (roc20 != null) reasonParts.push(`momentum ${roc20 >= 0 ? "+" : ""}${roc20}%`);
    if (trend !== "Neutral") reasonParts.push(`${trend.toLowerCase()} trend`);
    if (aboveEma50 === true) reasonParts.push("above 50 EMA");
    else if (aboveEma50 === false) reasonParts.push("below 50 EMA");

    // Risk note — sizing context only, not a gate
    const riskParts = [];
    if (conc != null && conc > 20) riskParts.push(`already ${conc.toFixed(0)}% of portfolio`);
    if (confidence === "Low") riskParts.push("signals mixed — size smaller");
    if (aboveEma50 === false) riskParts.push("below 50 EMA");

    // Only skip symbols with zero data and not in picks
    if (rs == null && roc20 == null && aboveEma50 == null && !pickSymbols.has(sym)) continue;

    ranked.push({ symbol: sym, score, confidence, reason: reasonParts.join(", ") || "in picks universe", riskNote: riskParts.join("; ") || null, trend, rs, roc20, aboveEma50 });
  }

  ranked.sort((a, b) => b.score - a.score);
  return { ranked: ranked.slice(0, 5), regimeLabel, spyROC20 };
}

function buildOpportunityRankingContext({ scannerResults, fundamentalsCache, positions, account }) {
  const { ranked, regimeLabel, spyROC20 } = buildOpportunityRanking({ scannerResults, fundamentalsCache, positions, account });
  if (ranked.length === 0) return null;

  const lines = ["[Opportunity Ranking]"];
  ranked.forEach((r, i) => {
    lines.push(`\n${i + 1}. ${r.symbol} — Score: ${r.score}/100 | ${r.confidence} Confidence`);
    if (r.reason) lines.push(`   Signals: ${r.reason}`);
    if (r.riskNote) lines.push(`   Sizing note: ${r.riskNote}`);
  });
  lines.push(`\nMarket regime: ${regimeLabel}${spyROC20 != null ? ` (SPY 20d: ${spyROC20 >= 0 ? "+" : ""}${spyROC20}%)` : ""}`);
  return lines.join("\n");
}

// ─── End Opportunity Ranking Engine ──────────────────────────────────────────

function buildUniversalScreenContext({
  activeTab,
  performancePositionFilter,
  raylaActiveReviewedTrade,
  brokerPositionsWithIntent,
  longTermBrokerPositions,
  alpacaAccount,
  simulationMode,
  selectedSimulationOpenPosition,
  hotColdReport,
  marketSnapshot,
  documentIntelligence,
  fundamentalsCache,
  scannerResults,
  trades,
  intelSubTab,
}) {
  const source = detectScreenSource({ activeTab, performancePositionFilter, raylaActiveReviewedTrade, intelSubTab });
  const objectsIncluded = [];
  let contextText = "";

  const fmt = (v) => (v != null ? String(v) : "—");
  const fmtMoney = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? `$${n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "—";
  };
  const goalsCtx = buildFinancialGoalsContext(loadFinancialGoals());

  switch (source) {
    case "Home": {
      const lines = ["[Screen: Home Overview]"];
      if (alpacaAccount) {
        objectsIncluded.push("account");
        lines.push(`Account equity: ${fmtMoney(alpacaAccount.equity || alpacaAccount.portfolioValue)}`);
      }
      const posCount = Array.isArray(brokerPositionsWithIntent) ? brokerPositionsWithIntent.length : 0;
      if (posCount > 0) {
        objectsIncluded.push("positions_summary");
        lines.push(`Open positions: ${posCount}`);
      }
      const tradeCount = Array.isArray(trades) ? trades.length : 0;
      if (tradeCount > 0) {
        objectsIncluded.push("trade_count");
        lines.push(`Journal trades logged: ${tradeCount}`);
      }
      const homeRiskCtx = buildPortfolioRiskContext({ positions: brokerPositionsWithIntent, account: alpacaAccount });
      if (homeRiskCtx) { objectsIncluded.push("risk_engine"); lines.push(""); lines.push(homeRiskCtx); }
      if (goalsCtx) { objectsIncluded.push("financial_goals"); lines.push(""); lines.push(goalsCtx); }
      contextText = lines.join("\n");
      break;
    }

    case "Portfolio": {
      const positions = Array.isArray(brokerPositionsWithIntent) ? brokerPositionsWithIntent : [];
      const lines = ["[Screen: Portfolio — All Positions]"];
      if (alpacaAccount) {
        objectsIncluded.push("account");
        lines.push(`Account equity: ${fmtMoney(alpacaAccount.equity || alpacaAccount.portfolioValue)}`);
      }
      if (positions.length) {
        objectsIncluded.push("all_positions");
        lines.push(`Positions (${positions.length}):`);
        positions.forEach((p) => {
          const pl = Number(p.unrealized_pl ?? p.unrealizedPl);
          const plStr = Number.isFinite(pl) ? ` | P&L: ${pl >= 0 ? "+" : ""}${fmtMoney(pl)}` : "";
          lines.push(`  ${fmt(p.symbol)}: ${fmtMoney(p.market_value ?? p.marketValue)} | ${fmt(p.positionTypeLabel || p.positionType)}${plStr}`);
        });
      }
      const portfolioRiskCtx = buildPortfolioRiskContext({ positions, account: alpacaAccount });
      if (portfolioRiskCtx) { objectsIncluded.push("risk_engine"); lines.push(""); lines.push(portfolioRiskCtx); }
      if (goalsCtx) { objectsIncluded.push("financial_goals"); lines.push(""); lines.push(goalsCtx); }
      contextText = lines.join("\n");
      break;
    }

    case "Holdings": {
      const positions = Array.isArray(longTermBrokerPositions) ? longTermBrokerPositions : [];
      const lines = ["[Screen: Holdings — Long-Term Investments]"];
      const totalEquity = Number(alpacaAccount?.equity ?? alpacaAccount?.portfolioValue ?? 0);
      if (alpacaAccount) {
        objectsIncluded.push("account");
        lines.push(`Account equity: ${fmtMoney(totalEquity)}`);
      }
      if (positions.length) {
        objectsIncluded.push("holdings_positions");
        lines.push(`Holdings (${positions.length}):`);
        positions.forEach((p) => {
          const mv = Number(p.market_value ?? p.marketValue);
          const pl = Number(p.unrealized_pl ?? p.unrealizedPl);
          const plPct = Number(p.unrealizedPlpc);
          const avgEntry = Number(p.avg_entry_price ?? p.avgEntryPrice);
          const concentration = totalEquity > 0 && Number.isFinite(mv) && mv > 0 ? (mv / totalEquity * 100).toFixed(1) : null;
          let posLine = `  ${fmt(p.symbol)}: ${fmtMoney(mv)}`;
          if (Number.isFinite(pl)) posLine += ` | P&L: ${pl >= 0 ? "+" : ""}${fmtMoney(pl)}`;
          if (Number.isFinite(plPct) && plPct !== 0) posLine += ` (${(plPct * 100) >= 0 ? "+" : ""}${(plPct * 100).toFixed(1)}%)`;
          if (concentration) posLine += ` | ${concentration}% of portfolio`;
          if (Number.isFinite(avgEntry) && avgEntry > 0) posLine += ` | Avg entry: ${fmtMoney(avgEntry)}`;
          lines.push(posLine);
        });
      } else {
        lines.push("No long-term holdings classified yet.");
      }
      const holdingsRiskCtx = buildPortfolioRiskContext({ positions, account: alpacaAccount });
      if (holdingsRiskCtx) { objectsIncluded.push("risk_engine"); lines.push(""); lines.push(holdingsRiskCtx); }
      if (goalsCtx) { objectsIncluded.push("financial_goals"); lines.push(""); lines.push(goalsCtx); }
      contextText = lines.join("\n");
      break;
    }

    case "PersonalPicks": {
      const lines = ["[Screen: Personal Picks — Weekly Baseline Picks]"];
      const cachedPicks = loadPicksCacheForContext();
      const profile = loadPicksProfile();
      if (profile) {
        objectsIncluded.push("picks_profile");
        const profileCtx = buildPicksProfileContext(profile);
        if (profileCtx) lines.push(profileCtx);
      }
      if (cachedPicks?.length) {
        objectsIncluded.push("picks_cache");
        lines.push(`\nCurrent weekly picks (${cachedPicks.length}) — treat these as the baseline recommendation set and build from there:`);
        cachedPicks.forEach((pk, i) => {
          lines.push(`  ${i + 1}. ${fmt(pk.symbol || pk.ticker)} — ${fmt(pk.fitScore ?? pk.fit_score)}% fit — ${fmt(pk.confidence ?? "—")} confidence`);
          if (pk.why) lines.push(`     Why: ${String(pk.why).slice(0, 150)}`);
          if (pk.watchOut) lines.push(`     Watch out: ${String(pk.watchOut).slice(0, 120)}`);
          else if (pk.reasoning) lines.push(`     Reason: ${String(pk.reasoning).slice(0, 120)}`);
        });
        lines.push("\nWhen the user asks questions, reference these picks directly, explain the reasoning behind each, and suggest how to act on or refine them.");
      } else {
        lines.push("\nNo weekly picks generated yet. Help the user understand what to expect or prompt them to generate picks.");
      }
      if (goalsCtx) { objectsIncluded.push("financial_goals"); lines.push(""); lines.push(goalsCtx); }
      contextText = lines.join("\n");
      break;
    }

    case "MarketIntel": {
      const lines = ["[Screen: Market Intelligence]"];
      if (hotColdReport) {
        objectsIncluded.push("hot_cold_report");
        const hot = Array.isArray(hotColdReport.stockHot) ? hotColdReport.stockHot : [];
        const cold = Array.isArray(hotColdReport.stockCold) ? hotColdReport.stockCold : [];
        if (hot.length) lines.push(`Hot stocks: ${hot.slice(0, 5).map((s) => s?.symbol || s).join(", ")}`);
        if (cold.length) lines.push(`Cold stocks: ${cold.slice(0, 5).map((s) => s?.symbol || s).join(", ")}`);
        if (hotColdReport.cryptoHot?.symbol) lines.push(`Hot crypto: ${hotColdReport.cryptoHot.symbol}`);
        if (hotColdReport.cryptoCold?.symbol) lines.push(`Cold crypto: ${hotColdReport.cryptoCold.symbol}`);
      }
      contextText = lines.join("\n");
      break;
    }

    case "TradeReview": {
      const trade = raylaActiveReviewedTrade;
      const lines = ["[Screen: Trade Review]"];
      if (trade) {
        objectsIncluded.push("reviewed_trade");
        lines.push(`Reviewing trade: ${fmt(trade.asset || trade.symbol)}`);
        if (trade.direction) lines.push(`Direction: ${fmt(trade.direction)}`);
        if (trade.setup) lines.push(`Setup: ${fmt(trade.setup)}`);
        if (trade.result_r != null) lines.push(`Result: ${fmt(trade.result_r)}R`);
        if (trade.entry_time) lines.push(`Entry: ${fmt(trade.entry_time)}`);
        const tradeEntryReason = trade.entryReason || trade.entry_reason || "";
        if (tradeEntryReason) lines.push(`Trade entry reason: ${String(tradeEntryReason).slice(0, 200)}`);
        if (trade.notes) lines.push(`Notes: ${String(trade.notes).slice(0, 120)}`);
      }
      contextText = lines.join("\n");
      break;
    }

    case "Journal": {
      const recentTrades = (Array.isArray(trades) ? trades : []).slice(0, 5);
      const lines = ["[Screen: Trade Journal]"];
      if (recentTrades.length) {
        objectsIncluded.push("recent_trades");
        lines.push(`Recent trades (last ${recentTrades.length}):`);
        recentTrades.forEach((t) => {
          lines.push(`  ${fmt(t.asset)} — ${fmt(t.direction)} — ${fmt(t.setup)} — ${fmt(t.result_r)}R`);
        });
      } else {
        lines.push("No trades logged yet.");
      }
      contextText = lines.join("\n");
      break;
    }

    case "Simulation": {
      const lines = ["[Screen: Trade Simulation]"];
      objectsIncluded.push("simulation_mode");
      lines.push(`Simulation mode: ${fmt(simulationMode)}`);
      if (selectedSimulationOpenPosition) {
        objectsIncluded.push("sim_open_position");
        const pos = selectedSimulationOpenPosition;
        lines.push(`Selected position: ${fmt(pos.asset || pos.symbol)}`);
        if (pos.direction) lines.push(`Direction: ${fmt(pos.direction)}`);
        if (pos.entryPrice != null) lines.push(`Entry: ${fmtMoney(pos.entryPrice)}`);
        if (pos.profitLoss != null) lines.push(`Unrealized P&L: ${fmtMoney(pos.profitLoss)}`);
      }
      contextText = lines.join("\n");
      break;
    }

    case "LiveTrades": {
      const positions = Array.isArray(brokerPositionsWithIntent) ? brokerPositionsWithIntent : [];
      const lines = ["[Screen: Live Trade Execution]"];
      if (alpacaAccount) {
        objectsIncluded.push("account");
        lines.push(`Account equity: ${fmtMoney(alpacaAccount.equity || alpacaAccount.portfolioValue)}`);
      }
      if (positions.length) {
        objectsIncluded.push("positions_summary");
        lines.push(`Open positions (${positions.length}): ${positions.map((p) => p.symbol).join(", ")}`);
      }
      contextText = lines.join("\n");
      break;
    }

    default: {
      contextText = `[Screen: ${fmt(activeTab || "General")}]`;
      break;
    }
  }

  // Fundamentals — inject for Portfolio, Holdings, PersonalPicks screens
  const FUNDAMENTALS_SCREENS = ["Portfolio", "Holdings", "PersonalPicks"];
  if (FUNDAMENTALS_SCREENS.includes(source) && fundamentalsCache) {
    let fundSymbols = [];
    if (source === "Portfolio") fundSymbols = (Array.isArray(brokerPositionsWithIntent) ? brokerPositionsWithIntent : []).map((p) => p.symbol).filter(Boolean).slice(0, 10);
    if (source === "Holdings") fundSymbols = (Array.isArray(longTermBrokerPositions) ? longTermBrokerPositions : []).map((p) => p.symbol).filter(Boolean).slice(0, 10);
    if (source === "PersonalPicks") {
      const picks = loadPicksCacheForContext();
      fundSymbols = (Array.isArray(picks) ? picks : []).map((p) => p.symbol || p.ticker).filter(Boolean).slice(0, 5);
    }
    if (documentIntelligence?.symbol) {
      const docSym = String(documentIntelligence.symbol).toUpperCase();
      if (!fundSymbols.includes(docSym)) fundSymbols.push(docSym);
    }
    const fundCtx = buildFundamentalsContext(fundSymbols, fundamentalsCache);
    if (fundCtx) {
      objectsIncluded.push("fundamentals");
      contextText = contextText ? `${contextText}\n\n${fundCtx}` : fundCtx;
    }
  }

  // Scanner Results — inject for Portfolio, Holdings, PersonalPicks screens
  const SCANNER_SCREENS = ["Portfolio", "Holdings", "PersonalPicks"];
  if (SCANNER_SCREENS.includes(source) && scannerResults) {
    const scanCtx = buildScannerContext(scannerResults);
    if (scanCtx) {
      objectsIncluded.push("scanner_results");
      contextText = contextText ? `${contextText}\n\n${scanCtx}` : scanCtx;
    }
  }

  // Opportunity Ranking — inject for Portfolio, Holdings, PersonalPicks screens
  if (SCANNER_SCREENS.includes(source)) {
    const rankingPositions = source === "Holdings"
      ? (Array.isArray(longTermBrokerPositions) ? longTermBrokerPositions : [])
      : (Array.isArray(brokerPositionsWithIntent) ? brokerPositionsWithIntent : []);
    const rankCtx = buildOpportunityRankingContext({ scannerResults, fundamentalsCache, positions: rankingPositions, account: alpacaAccount });
    if (rankCtx) {
      objectsIncluded.push("opportunity_ranking");
      contextText = contextText ? `${contextText}\n\n${rankCtx}` : rankCtx;
    }
  }

  // Append document intelligence to all screens — always relevant if a document is loaded this session
  const docIntelCtx = buildDocumentIntelligenceContext(documentIntelligence);
  if (docIntelCtx) {
    objectsIncluded.push("document_intelligence");
    contextText = contextText ? `${contextText}\n\n${docIntelCtx}` : docIntelCtx;
  }

  // Append market snapshot to all screens where it adds value
  const MARKET_SNAPSHOT_SCREENS = ["Home", "Portfolio", "Holdings", "PersonalPicks", "MarketIntel", "LiveTrades"];
  if (MARKET_SNAPSHOT_SCREENS.includes(source)) {
    const snapshotCtx = buildMarketSnapshotContext(marketSnapshot);
    if (snapshotCtx) {
      objectsIncluded.push("market_snapshot");
      contextText = contextText ? `${contextText}\n\n${snapshotCtx}` : snapshotCtx;
    } else {
      contextText = contextText
        ? `${contextText}\n\n[Market Snapshot — unavailable this session]`
        : "[Market Snapshot — unavailable this session]";
    }
  }

  return { source, contextText, objectsIncluded };
}

// ─── End Universal Screen Context ────────────────────────────────────────────

function buildBehavioralPatternSummary(simTrades) {
  const trades = Array.isArray(simTrades) ? simTrades : [];
  if (trades.length < 5) return null;

  const recent = trades.slice(-15);
  const totalRecent = recent.length;

  const wins = recent.filter((t) => (t.profitLoss || 0) > 0);
  const longs = recent.filter((t) => t.direction === "long");
  const shorts = recent.filter((t) => t.direction === "short");
  const longWins = longs.filter((t) => (t.profitLoss || 0) > 0);
  const shortWins = shorts.filter((t) => (t.profitLoss || 0) > 0);

  let streakCount = 0;
  let streakType = null;
  for (let i = recent.length - 1; i >= 0; i--) {
    const type = (recent[i].profitLoss || 0) > 0 ? "win" : "loss";
    if (streakType === null) { streakType = type; streakCount = 1; }
    else if (type === streakType) streakCount++;
    else break;
  }

  const cutEarlyCount = recent.filter((t) => t.outcomeLabel === "Cut too early").length;
  const heldTooLongCount = recent.filter((t) => t.outcomeLabel === "Held too long").length;
  const strongExecCount = recent.filter((t) => t.executionGrade === "A" || t.executionGrade === "B").length;
  const poorExecCount = recent.filter((t) => t.executionGrade === "D").length;

  return {
    sampleSize: totalRecent,
    patternThresholdMet: totalRecent >= 5,
    winRate: Math.round((wins.length / totalRecent) * 100),
    longWinRate: longs.length >= 4 ? Math.round((longWins.length / longs.length) * 100) : null,
    longTradeCount: longs.length,
    shortWinRate: shorts.length >= 4 ? Math.round((shortWins.length / shorts.length) * 100) : null,
    shortTradeCount: shorts.length,
    currentStreak: streakType ? { type: streakType, count: streakCount } : null,
    cutEarlyCount,
    heldTooLongCount,
    strongExecCount,
    poorExecCount,
  };
}

function buildSelectedAssetChartSummary(chartContext) {
  if (!chartContext) return null;
  const bars = Array.isArray(chartContext?.recentBars) ? chartContext.recentBars : [];
  const firstClose = Number(chartContext?.chartSummary?.firstClose);
  const lastClose = Number(chartContext?.chartSummary?.lastClose);
  const barCount = Number(chartContext?.chartSummary?.barCount);
  const netChange = Number.isFinite(firstClose) && Number.isFinite(lastClose) ? lastClose - firstClose : null;
  const netChangePct = Number.isFinite(firstClose) && firstClose !== 0 && Number.isFinite(lastClose)
    ? ((lastClose - firstClose) / firstClose) * 100
    : null;
  return {
    timeframe: chartContext?.timeframe || "1D",
    barCount: Number.isFinite(barCount) ? barCount : bars.length || 0,
    firstClose: Number.isFinite(firstClose) ? firstClose : null,
    lastClose: Number.isFinite(lastClose) ? lastClose : null,
    netChange: Number.isFinite(netChange) ? roundMetric(netChange) : null,
    netChangePct: Number.isFinite(netChangePct) ? roundMetric(netChangePct) : null,
  };
}

function buildRaylaPicksContext({ trades, simulationTradeHistory }) {
  const realTrades = Array.isArray(trades) ? trades.filter(isStrategyInsightTrade) : [];
  const simTrades = Array.isArray(simulationTradeHistory) ? simulationTradeHistory : [];
  const minimumPickSample = 3;
  const bucketMap = new Map();
  const meta = {
    strategyRTrades: 0,
    missingDirectionTrades: 0,
    eligibleDirectionalTrades: 0,
    validDirectionTrades: 0,
    validResultTrades: 0,
  };

  const ensureBucket = (asset, assetType, direction) => {
    const key = `${assetType}:${direction}:${asset}`;
    if (!bucketMap.has(key)) {
      bucketMap.set(key, {
        asset,
        assetType,
        direction,
        totalTrades: 0,
        wins: 0,
        totalR: 0,
        realTrades: 0,
        simTrades: 0,
      });
    }
    return bucketMap.get(key);
  };

  realTrades.forEach((trade) => {
    const asset = normalizePickAssetSymbol(trade?.asset || trade?.symbol || trade?.ticker);
    const direction = normalizePickDirection(trade?.direction);
    const resultR = parsePickResultR(trade);
    if (!asset) return;
    if (!Number.isFinite(resultR)) return;
    meta.validResultTrades += 1;
    meta.strategyRTrades += 1;
    if (!["long", "short"].includes(direction)) {
      meta.missingDirectionTrades += 1;
      return;
    }
    meta.validDirectionTrades += 1;
    meta.eligibleDirectionalTrades += 1;
    const assetType = CRYPTO_SYMBOL_SET.has(asset) ? "crypto" : "stock";
    const bucket = ensureBucket(asset, assetType, direction);
    bucket.totalTrades += 1;
    bucket.realTrades += 1;
    bucket.totalR += resultR;
    if (resultR > 0) bucket.wins += 1;
  });

  simTrades.forEach((trade) => {
    const asset = normalizePickAssetSymbol(trade?.asset || trade?.symbol || trade?.ticker);
    const direction = normalizePickDirection(trade?.direction);
    const resultR = parsePickResultR(trade);
    if (!asset) return;
    if (!Number.isFinite(resultR)) return;
    meta.validResultTrades += 1;
    meta.strategyRTrades += 1;
    if (!["long", "short"].includes(direction)) {
      meta.missingDirectionTrades += 1;
      return;
    }
    meta.validDirectionTrades += 1;
    meta.eligibleDirectionalTrades += 1;
    const assetType = CRYPTO_SYMBOL_SET.has(asset) ? "crypto" : "stock";
    const bucket = ensureBucket(asset, assetType, direction);
    bucket.totalTrades += 1;
    bucket.simTrades += 1;
    bucket.totalR += resultR;
    if (resultR > 0) bucket.wins += 1;
  });

  const ranked = Array.from(bucketMap.values())
    .map((bucket) => ({
      ...bucket,
      avgR: bucket.totalTrades ? bucket.totalR / bucket.totalTrades : 0,
      winRate: bucket.totalTrades ? (bucket.wins / bucket.totalTrades) * 100 : 0,
    }))
    .sort((a, b) => {
      if (b.avgR !== a.avgR) return b.avgR - a.avgR;
      if (b.winRate !== a.winRate) return b.winRate - a.winRate;
      return b.totalTrades - a.totalTrades;
    });
  const bucketCounts = ranked.map((entry) => ({
    asset: entry.asset,
    assetType: entry.assetType,
    direction: entry.direction,
    totalTrades: entry.totalTrades,
    realTrades: entry.realTrades,
    simTrades: entry.simTrades,
    avgR: entry.avgR,
    winRate: entry.winRate,
    eligible: entry.totalTrades >= minimumPickSample,
  }));
  const watchedBucketCounts = ["ETH", "BTC", "AAPL", "NVDA", "NRG"].reduce((acc, symbol) => {
    acc[symbol] = bucketCounts.filter((entry) => entry.asset === symbol);
    return acc;
  }, {});

  const findBest = (assetType, direction) =>
    ranked.find((entry) =>
      entry.assetType === assetType &&
      entry.direction === direction &&
      entry.totalTrades >= minimumPickSample
    ) || null;

  const toPick = (entry, title) => {
    if (!entry) {
      return {
        title,
        asset: null,
        directionBias: null,
        explanation: "Not enough logged history yet in this category.",
        progress: "Log a few more trades or simulations here to unlock a personalized pick.",
        eligible: false,
      };
    }

    const biasLabel = entry.direction === "short" ? "Short bias" : "Long bias";
    const realLabel = `${entry.realTrades} real trade${entry.realTrades === 1 ? "" : "s"}`;
    const simLabel = `${entry.simTrades} simulation trade${entry.simTrades === 1 ? "" : "s"}`;
    const explanation = `${entry.asset} has the strongest relative edge in your logged history right now.`;
    const progress = `Built from ${realLabel} and ${simLabel} in this direction.`;

    return {
      title,
      asset: entry.asset,
      directionBias: biasLabel,
      explanation,
      progress,
      eligible: true,
      avgR: entry.avgR,
      winRate: entry.winRate,
      totalTrades: entry.totalTrades,
      realTrades: entry.realTrades,
      simTrades: entry.simTrades,
    };
  };

  return {
    meta,
    debug: {
      meta,
      minimumPickSample,
      bucketCounts,
      watchedBucketCounts,
      eligibleBuckets: bucketCounts.filter((entry) => entry.eligible),
    },
    stockLong: toPick(findBest("stock", "long"), "Best Stock to Buy"),
    stockShort: toPick(findBest("stock", "short"), "Best Stock to Short"),
    cryptoLong: toPick(findBest("crypto", "long"), "Best Crypto to Buy"),
    cryptoShort: toPick(findBest("crypto", "short"), "Best Crypto to Short"),
  };
}

function calculateSimulationPositionPnL(position, currentPrice) {
  if (!position || !Number.isFinite(currentPrice)) return { profitLoss: 0, rMultiple: null };
  const quantity = getSimulationPositionQuantity(position);
  if (!Number.isFinite(quantity) || quantity <= 0) return { profitLoss: 0, rMultiple: null };
  const priceMove = position.direction === "long"
    ? currentPrice - position.entryPrice
    : position.entryPrice - currentPrice;
  const profitLoss = quantity * priceMove;
  const plannedRisk = Math.abs(Number(position.plannedRisk));
  const rMultiple = plannedRisk > 0 ? profitLoss / plannedRisk : null;
  return { profitLoss, rMultiple };
}

function getSimulationRiskDebug(position) {
  if (!position) {
    return {
      plannedRiskRaw: null,
      plannedRiskAbs: null,
      riskPerUnit: null,
      stopLoss: null,
      originalStopLoss: null,
      initialRisk: null,
      source: "missing-position",
    };
  }

  const plannedRiskRaw = Number(position.plannedRisk);
  const plannedRiskAbs = Math.abs(plannedRiskRaw);
  if (Number.isFinite(plannedRiskRaw) && plannedRiskAbs > 0) {
    return {
      plannedRiskRaw: position.plannedRisk,
      plannedRiskAbs,
      riskPerUnit: position.riskPerUnit ?? null,
      stopLoss: position.stopLoss ?? null,
      originalStopLoss: position.originalStopLoss ?? null,
      initialRisk: plannedRiskAbs,
      source: "plannedRisk",
    };
  }

  const initialRiskRaw = Number(position.initialRisk);
  const initialRiskAbs = Math.abs(initialRiskRaw);
  if (Number.isFinite(initialRiskRaw) && initialRiskAbs > 0) {
    return {
      plannedRiskRaw: position.plannedRisk ?? null,
      plannedRiskAbs: Number.isFinite(plannedRiskRaw) ? plannedRiskAbs : null,
      riskPerUnit: position.riskPerUnit ?? null,
      stopLoss: position.stopLoss ?? null,
      originalStopLoss: position.originalStopLoss ?? null,
      initialRisk: initialRiskAbs,
      source: "initialRisk",
    };
  }

  return {
    plannedRiskRaw: position.plannedRisk ?? null,
    plannedRiskAbs: Number.isFinite(plannedRiskRaw) ? plannedRiskAbs : null,
    riskPerUnit: position.riskPerUnit ?? null,
    stopLoss: position.stopLoss ?? null,
    originalStopLoss: position.originalStopLoss ?? null,
    initialRisk: null,
    source: "none",
  };
}

function logRaylaSimulationDebug(label, payload) {
  if (
    typeof window === "undefined"
    || window.localStorage.getItem("rayla_debug_logs") !== "true"
  ) {
    return;
  }
  try {
    console.info(label, JSON.stringify(payload));
  } catch {
    console.info(label, payload);
  }
}

function getTradeRValue(trade) {
  const r = Number(trade?.result_r);
  if (Number.isFinite(r)) return r;
  const rm = Number(trade?.rMultiple);
  return Number.isFinite(rm) ? rm : 0;
}

function getTradePerformanceValue(trade) {
  const outcomeValue = getTradeOutcomeValue(trade);
  return Number.isFinite(outcomeValue) ? outcomeValue : 0;
}

function isBrokerImportSetup(value) {
  return String(value || "").trim().toLowerCase() === "broker import";
}

function isStrategyInsightTrade(trade) {
  return !trade?.isBrokerTrade && !isBrokerImportSetup(trade?.setup);
}

function isAppSimulationTrade(trade) {
  if (!trade?.id) return false;
  if (trade?.isBrokerTrade) return false;
  if (isBrokerImportSetup(trade?.setup)) return false;
  const source = String(trade?.source || "").trim().toLowerCase();
  const sourceLabel = String(trade?.source_label || "").trim().toLowerCase();
  const marketMode = String(trade?.marketMode || "").trim().toLowerCase();
  const sourceType = String(trade?.sourceType || "").trim().toLowerCase();
  return (
    source === "live_simulation"
    || sourceLabel === "live simulation"
    || sourceType === "live_sim_trade"
    || sourceType === "scenario_sim_trade"
    || marketMode === "live"
    || marketMode === "scenario"
  );
}

function isEditableManualTrade(trade) {
  if (!trade?.id) return false;
  if (trade?.isBrokerTrade) return false;
  if (isBrokerImportSetup(trade?.setup)) return false;
  if (isAppSimulationTrade(trade)) return false;
  const sourceText = [
    trade?.source,
    trade?.source_label,
    trade?.origin,
    trade?.provider,
  ].map((value) => String(value || "").trim().toLowerCase()).join(" ");
  if (sourceText.includes("broker") || sourceText.includes("alpaca") || sourceText.includes("sync") || sourceText.includes("import")) {
    return false;
  }
  return true;
}

function isDeletableAppTrade(trade) {
  return isEditableManualTrade(trade) || isAppSimulationTrade(trade);
}

function getPicksEligibilityIssue(trade) {
  if (!trade) return null;
  if (!isStrategyInsightTrade(trade)) return null;
  const missing = [];
  const asset = normalizePickAssetSymbol(trade?.asset || trade?.symbol || trade?.ticker);
  const direction = normalizePickDirection(trade?.direction);
  const resultR = parsePickResultR(trade);
  if (!asset) missing.push("Missing Asset");
  if (!["long", "short"].includes(direction)) missing.push("Missing Direction");
  if (!Number.isFinite(resultR)) missing.push("Missing R");
  return missing.length ? missing : null;
}

function buildPerformanceOutcomeReport(trades, { excludeBrokerTrades = false, valueAccessor = getTradePerformanceValue } = {}) {
  if (!trades || trades.length === 0) return null;
  const reportTrades = excludeBrokerTrades
    ? trades.filter(t => isStrategyInsightTrade(t) && parseOptionalTradeResult(t?.result_r) != null)
    : trades;
  if (!reportTrades.length) return null;
  const getValue = typeof valueAccessor === "function" ? valueAccessor : getTradePerformanceValue;
  const strategyTrades = reportTrades.filter(isStrategyInsightTrade);
  const brokerTradeCount = reportTrades.filter(t => t?.isBrokerTrade).length;
  const hasBrokerTrades = brokerTradeCount > 0;
  const hasStrategyTrades = strategyTrades.length > 0;
  const hasMixedUnits = hasBrokerTrades && hasStrategyTrades;

  const wins = reportTrades.filter(t => getValue(t) > 0);
  const losses = reportTrades.filter(t => getValue(t) < 0);
  const winRate = reportTrades.length ? (wins.length / reportTrades.length) * 100 : 0;
  const avgR = reportTrades.length ? reportTrades.reduce((s, t) => s + getValue(t), 0) / reportTrades.length : 0;
  const avgWin = wins.length ? wins.reduce((s, t) => s + getValue(t), 0) / wins.length : 0;
  const avgLoss = losses.length ? Math.abs(losses.reduce((s, t) => s + getValue(t), 0) / losses.length) : 0;
  const totalR = reportTrades.reduce((s, t) => s + getValue(t), 0);
  const profitFactor = avgLoss > 0 ? (avgWin * wins.length) / (avgLoss * losses.length) : null;
  const strategyWins = strategyTrades.filter(t => getValue(t) > 0);
  const strategyLosses = strategyTrades.filter(t => getValue(t) < 0);
  const strategyWinRate = strategyTrades.length ? (strategyWins.length / strategyTrades.length) * 100 : 0;
  const strategyAvgWin = strategyWins.length ? strategyWins.reduce((s, t) => s + getValue(t), 0) / strategyWins.length : 0;
  const strategyAvgLoss = strategyLosses.length ? Math.abs(strategyLosses.reduce((s, t) => s + getValue(t), 0) / strategyLosses.length) : 0;
  const strategyProfitFactor = strategyAvgLoss > 0 ? (strategyAvgWin * strategyWins.length) / (strategyAvgLoss * strategyLosses.length) : null;

  const setupMap = {};
  strategyTrades.forEach(t => {
    const setup = normalizeSetupType(t.setupType) || String(t.setup || "").trim();
    if (!setup) return;
    if (!setupMap[setup]) setupMap[setup] = { trades: 0, wins: 0, totalR: 0 };
    setupMap[setup].trades++;
    setupMap[setup].totalR += getValue(t);
    if (getValue(t) > 0) setupMap[setup].wins++;
  });
  const setupStats = Object.entries(setupMap)
    .map(([setup, s]) => ({ setup, trades: s.trades, winRate: (s.wins / s.trades) * 100, avgR: s.totalR / s.trades, totalR: s.totalR }))
    .sort((a, b) => b.avgR - a.avgR);

  const assetMap = {};
  reportTrades.forEach(t => {
    const asset = (t.asset || "Unknown").toUpperCase();
    if (!assetMap[asset]) assetMap[asset] = { trades: 0, wins: 0, totalR: 0 };
    assetMap[asset].trades++;
    assetMap[asset].totalR += getValue(t);
    if (getValue(t) > 0) assetMap[asset].wins++;
  });
  const assetStats = Object.entries(assetMap)
    .map(([asset, s]) => ({ asset, trades: s.trades, winRate: (s.wins / s.trades) * 100, avgR: s.totalR / s.trades, totalR: s.totalR }))
    .sort((a, b) => b.avgR - a.avgR);
  const topAssetBucket = assetStats.slice(0, 2);
  const remainingAssetBucket = assetStats.slice(2);
  const topAssetTrades = topAssetBucket.reduce((sum, asset) => sum + asset.trades, 0);
  const remainingAssetTrades = remainingAssetBucket.reduce((sum, asset) => sum + asset.trades, 0);
  const topAssetAvg = topAssetTrades
    ? topAssetBucket.reduce((sum, asset) => sum + (asset.avgR * asset.trades), 0) / topAssetTrades
    : null;
  const remainingAssetAvg = remainingAssetTrades
    ? remainingAssetBucket.reduce((sum, asset) => sum + (asset.avgR * asset.trades), 0) / remainingAssetTrades
    : null;
  const broadAssetSpreadIsHurting =
    assetStats.length > 4
    && remainingAssetTrades >= 3
    && Number.isFinite(topAssetAvg)
    && Number.isFinite(remainingAssetAvg)
    && topAssetAvg > 0
    && remainingAssetAvg < 0
    && (topAssetAvg - remainingAssetAvg) >= 0.5;

  const comboMap = {};
  strategyTrades.forEach(t => {
    const setup = normalizeSetupType(t.setupType) || String(t.setup || "").trim();
    if (!setup) return;
    const key = `${(t.asset||"").toUpperCase()}_${setup}`;
    if (!comboMap[key]) comboMap[key] = { asset: (t.asset||"").toUpperCase(), setup, trades: 0, wins: 0, totalR: 0 };
    comboMap[key].trades++;
    comboMap[key].totalR += getValue(t);
    if (getValue(t) > 0) comboMap[key].wins++;
  });
  const comboStats = Object.values(comboMap)
    .map(c => ({ ...c, winRate: (c.wins / c.trades) * 100, avgR: c.totalR / c.trades }))
    .filter(c => c.trades >= 2)
    .sort((a, b) => b.avgR - a.avgR);

  const warnings = [];
  if (strategyTrades.length >= 3 && strategyWinRate < 40) warnings.push("Win rate is below 40% — entries need refinement.");
  if (strategyTrades.length > 0 && strategyAvgLoss > strategyAvgWin && strategyWins.length > 0 && strategyLosses.length > 0) warnings.push("Avg loss is larger than avg win — cutting winners too early or letting losers run.");
  if (strategyTrades.length > 0 && strategyProfitFactor !== null && strategyProfitFactor < 1) warnings.push("Profit factor is below 1.0 — system is net negative. Review setups immediately.");
  if (strategyTrades.length >= 5 && strategyWinRate < 50) warnings.push("Win rate under 50% with 5+ trades — possible overtrading or setup quality issues.");
  if (!hasMixedUnits && broadAssetSpreadIsHurting) warnings.push(`Your weaker results are coming outside your top assets. Keep an eye on whether breadth is diluting edge quality.`);
  const recentLosses = strategyTrades.slice(0, 4).filter(t => getValue(t) < 0).length;
  if (recentLosses >= 3) warnings.push("3 or more losses in your last 4 trades — consider taking a break.");

  const actions = [];
  const bestCombo = comboStats[0];
  const worstSetup = setupStats[setupStats.length - 1];
  if (bestCombo) actions.push(`Focus on ${bestCombo.setup} setups on ${bestCombo.asset} — your strongest edge (${bestCombo.avgR.toFixed(2)} avg).`);
  if (worstSetup && setupStats.length > 1 && worstSetup.avgR < 0) actions.push(`Reduce or stop trading ${worstSetup.setup} setups — negative average result (${worstSetup.avgR.toFixed(2)}).`);
  if (strategyAvgLoss > strategyAvgWin) actions.push("Define your stop before entry on every trade and respect it without exception.");
  if (strategyTrades.length > 0 && strategyWinRate < 50) actions.push("Be more selective — only take your clearest A+ setups.");
  if (actions.length === 0) actions.push("Keep executing consistently. Log every trade and review weekly.");

  return { winRate, avgR, avgWin, avgLoss, totalR, profitFactor, trades: reportTrades.length, wins: wins.length, losses: losses.length, setupStats, assetStats, comboStats, warnings, actions, bestCombo, worstCombo: comboStats[comboStats.length - 1], hasBrokerTrades, hasStrategyTrades, hasMixedUnits };
}

function buildCoachReport(trades) {
  // Broker trades have dollar pnl_value, not R multiples — exclude to avoid unit mixing in coaching stats.
  return buildPerformanceOutcomeReport(trades, { excludeBrokerTrades: true });
}

function buildTopEdges(trades) {
  return Object.values(
    (Array.isArray(trades) ? trades : []).reduce((acc, trade) => {
      if (!isStrategyInsightTrade(trade)) return acc;
      const resultR = parseOptionalTradeResult(trade?.result_r);
      if (resultR == null) return acc;
      const key = `${trade.setup} × ${trade.session}`;
      if (!acc[key]) acc[key] = { name: key, trades: 0, totalR: 0 };
      acc[key].trades += 1;
      acc[key].totalR += resultR;
      return acc;
    }, {})
  ).map((edge) => ({ name: edge.name, trades: edge.trades, avgR: (edge.totalR / edge.trades).toFixed(2) + "R" }))
    .sort((a, b) => parseFloat(b.avgR) - parseFloat(a.avgR))
    .slice(0, 3);
}

