function PerfBreakdownTable({ title, rows, nameColor = "#94a3b8", maxHeight = null, hideOutcomeValues = false }) {
  if (!rows || rows.length === 0) return null;
  const maxAbs = Math.max(5, ...rows.map(r => Math.abs(r.totalR)));
  const rowAreaMaxHeight = Number.isFinite(Number(maxHeight)) ? Number(maxHeight) : 185;
  return (
    <div
      data-perf-breakdown-card={title}
      style={{
        background: "rgba(18,26,38,0.86)",
        border: "1px solid rgba(255,255,255,0.07)",
        borderRadius: 14,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        alignSelf: "start",
      }}
    >
      <div data-perf-breakdown-header={title} style={{ padding: "11px 16px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <div style={{ fontSize: 11, fontWeight: 600, color: "#7f8ea3", textTransform: "uppercase", letterSpacing: "0.6px" }}>{title}</div>
        {rows.length > 0 && (
          <div style={{ fontSize: 11, color: "#475569", whiteSpace: "nowrap" }}>{rows.length}</div>
        )}
      </div>
      <div
        data-perf-breakdown-rows={title}
        className="perfBreakdownScrollArea"
        style={{
          display: "block",
          padding: "4px 0",
          maxHeight: rowAreaMaxHeight,
          overflowY: "auto",
          overscrollBehavior: "contain",
          WebkitOverflowScrolling: "touch",
          flex: "0 0 auto",
          minHeight: 0,
        }}
      >
        {rows.map((row, i) => (
          <div key={i} style={{ padding: "9px 16px", borderBottom: i < rows.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none", display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ minWidth: 88, maxWidth: 120, fontSize: 12, color: nameColor, fontWeight: 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row.name}</div>
            <div style={{ fontSize: 11, color: "#475569", whiteSpace: "nowrap", flexShrink: 0 }}>{row.trades}t · {row.winRate.toFixed(0)}%</div>
            {hideOutcomeValues ? (
              <div style={{ flex: 1, textAlign: "right", fontSize: 11, color: "#64748b" }}>execution history included</div>
            ) : (
              <>
                <div style={{ flex: 1, height: 4, background: "rgba(255,255,255,0.05)", borderRadius: 2, overflow: "hidden" }}>
                  <div style={{ height: "100%", width: `${(Math.abs(row.totalR) / maxAbs) * 100}%`, background: row.totalR >= 0 ? "#4ade80" : "#f87171", borderRadius: 2 }} />
                </div>
                <div style={{ fontSize: 12, fontWeight: 700, color: row.totalR >= 0 ? "#4ade80" : "#f87171", minWidth: 54, textAlign: "right", flexShrink: 0 }}>{row.totalR >= 0 ? "+" : ""}{row.totalR.toFixed(2)}</div>
                <div style={{ fontSize: 11, color: row.avgR >= 0 ? "#4ade80" : "#f87171", minWidth: 42, textAlign: "right", flexShrink: 0 }}>{row.avgR >= 0 ? "+" : ""}{row.avgR.toFixed(2)}</div>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function PositionPerformanceInsights({
  positions = [],
  title = "Position Analytics",
  scopeLabel = "positions",
  totalValue = null,
  totalUnrealizedPl = null,
  unrealizedPct = null,
  onRefresh = null,
}) {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefreshedAt, setLastRefreshedAt] = useState(null);
  const safePositions = Array.isArray(positions) ? positions : [];
  if (!safePositions.length) return null;

  const resolvedTotalValue = Number.isFinite(Number(totalValue))
    ? Number(totalValue)
    : safePositions.reduce((sum, position) => sum + (Number(position?.marketValue) || 0), 0);
  const resolvedUnrealizedPl = Number.isFinite(Number(totalUnrealizedPl))
    ? Number(totalUnrealizedPl)
    : safePositions.reduce((sum, position) => sum + (Number(position?.unrealizedPl) || 0), 0);
  const costBasis = safePositions.reduce((sum, position) => {
    const qty = Math.abs(Number(position?.qty));
    const avg = Number(position?.avgEntryPrice);
    if (qty > 0 && avg > 0) return sum + qty * avg;
    return sum + Math.max(0, (Number(position?.marketValue) || 0) - (Number(position?.unrealizedPl) || 0));
  }, 0);
  const resolvedUnrealizedPct = Number.isFinite(Number(unrealizedPct))
    ? Number(unrealizedPct)
    : costBasis > 0 ? (resolvedUnrealizedPl / costBasis) * 100 : null;

  const sortedPositions = [...safePositions].sort((a, b) => (Number(b?.marketValue) || 0) - (Number(a?.marketValue) || 0));
  const winningPositions = safePositions.filter((position) => (Number(position?.unrealizedPl) || 0) > 0);
  const losingPositions = safePositions.filter((position) => (Number(position?.unrealizedPl) || 0) < 0);
  const flatPositions = safePositions.length - winningPositions.length - losingPositions.length;
  const topPosition = sortedPositions[0] || null;
  const topAllocation = topPosition && resolvedTotalValue > 0
    ? ((Number(topPosition.marketValue) || 0) / resolvedTotalValue) * 100
    : null;

  const buildGroupRows = (getKey, getName) => {
    const groups = new Map();
    safePositions.forEach((position) => {
      const key = getKey(position);
      const name = getName(position);
      const previous = groups.get(key) || { name, count: 0, value: 0, pl: 0 };
      previous.count += 1;
      previous.value += Number(position?.marketValue) || 0;
      previous.pl += Number(position?.unrealizedPl) || 0;
      groups.set(key, previous);
    });
    return Array.from(groups.values()).sort((a, b) => b.value - a.value);
  };

  const intentRows = buildGroupRows(
    (position) => position.positionType || "unclassified",
    (position) => position.positionTypeLabel || getPositionTypeMeta(position.positionType).label || "Unclassified"
  );
  const assetClassRows = buildGroupRows(
    (position) => String(position.assetClass || position.asset_class || "equity").toLowerCase(),
    (position) => {
      const assetClass = String(position.assetClass || position.asset_class || "equity").toLowerCase();
      return assetClass === "crypto" ? "Crypto" : "Equity";
    }
  );

  const scopedPositionNoun = losingPositions.length === 1 && scopeLabel.endsWith("s")
    ? scopeLabel.slice(0, -1)
    : scopeLabel;
  const concentrationWarning = Number.isFinite(topAllocation) && topAllocation >= 70
    ? `${topPosition.symbol} is ${topAllocation.toFixed(0)}% of this view. That concentration matters more than the number of positions.`
    : null;
  const lossWarning = losingPositions.length
    ? `${losingPositions.length} ${scopedPositionNoun}${losingPositions.length === 1 ? " is" : " are"} currently underwater. Check whether the reason you bought still holds.`
    : null;
  const nextAction = concentrationWarning
    ? "Check whether the largest allocation is intentional before adding more exposure."
    : lossWarning
      ? "Review the underwater positions first; separate temporary drawdown from evidence the setup broke down."
      : "Keep monitoring allocation, unrealized P/L, and whether each position still matches its intent.";

  const cardBase = { background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14 };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10 }}>
        {[
          { label: "Open Positions", value: safePositions.length, sub: scopeLabel, color: "#f3f7fc" },
          { label: "Unrealized P/L", value: `${resolvedUnrealizedPl >= 0 ? "+" : ""}${formatCurrency(resolvedUnrealizedPl)}`, sub: Number.isFinite(resolvedUnrealizedPct) ? formatPerformancePercent(resolvedUnrealizedPct) : "open P/L", color: resolvedUnrealizedPl >= 0 ? "#4ade80" : "#f87171" },
          { label: "Winning", value: winningPositions.length, sub: `${losingPositions.length} underwater`, color: winningPositions.length >= losingPositions.length ? "#4ade80" : "#f87171" },
          { label: "Top Position", value: topPosition?.symbol || "—", sub: Number.isFinite(topAllocation) ? `${topAllocation.toFixed(1)}% allocation` : "largest allocation", color: "#7CC4FF" },
        ].map((item) => (
          <div key={item.label} style={{ ...cardBase, padding: "14px 16px" }}>
            <div style={{ fontSize: 11, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: 6 }}>{item.label}</div>
            <div style={{ fontSize: 18, fontWeight: 800, color: item.color, marginBottom: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{item.value}</div>
            <div style={{ fontSize: 11, color: "#475569" }}>{item.sub}</div>
          </div>
        ))}
      </div>

      <div style={{ ...cardBase, padding: "16px 20px" }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#7f8ea3", textTransform: "uppercase", letterSpacing: "0.6px", marginBottom: 14 }}>
          Position Outcomes
        </div>
        <div style={{ display: "flex", gap: 20, flexWrap: "wrap" }}>
          {[
            { label: "Winning", count: winningPositions.length, color: "#4ade80" },
            { label: "Underwater", count: losingPositions.length, color: "#f87171" },
            ...(flatPositions > 0 ? [{ label: "Flat", count: flatPositions, color: "#64748b" }] : []),
          ].map((item) => (
            <div key={item.label} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 8, height: 8, borderRadius: "50%", background: item.color, flexShrink: 0 }} />
              <span style={{ fontSize: 13, fontWeight: 700, color: item.color }}>{item.count}</span>
              <span style={{ fontSize: 12, color: "#64748b" }}>{item.label} · {safePositions.length ? ((item.count / safePositions.length) * 100).toFixed(0) : 0}%</span>
            </div>
          ))}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 14, alignItems: "start" }}>
        <PositionBreakdownCard title="By Intent" rows={intentRows} totalValue={resolvedTotalValue} />
        <PositionBreakdownCard title="By Asset Class" rows={assetClassRows} totalValue={resolvedTotalValue} />
        <PositionBreakdownCard title="Largest Positions" rows={sortedPositions.slice(0, 6).map((position) => ({
          name: position.symbol,
          count: 1,
          value: Number(position?.marketValue) || 0,
          pl: Number(position?.unrealizedPl) || 0,
        }))} totalValue={resolvedTotalValue} />
      </div>

      <div style={cardBase}>
        <div style={{ padding: "14px 18px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, flexWrap: "wrap" }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: "#7CC4FF" }}>Rayla's Position Diagnosis</div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ fontSize: 11, color: "#475569" }}>{title}</div>
            {lastRefreshedAt ? (
              <div style={{ fontSize: 10, color: "#475569" }}>
                Updated {lastRefreshedAt.toLocaleTimeString()}
              </div>
            ) : null}
            {(() => {
              const disabled = typeof onRefresh !== "function" || !safePositions.length || isRefreshing;
              return (
                <button
                  type="button"
                  onClick={async () => {
                    if (typeof onRefresh !== "function" || !safePositions.length || isRefreshing) return;
                    setIsRefreshing(true);
                    try {
                      const result = onRefresh();
                      if (result && typeof result.then === "function") await result;
                    } finally {
                      setLastRefreshedAt(new Date());
                      setIsRefreshing(false);
                    }
                  }}
                  disabled={disabled}
                  style={{
                    background: disabled ? "rgba(124,196,255,0.04)" : "rgba(124,196,255,0.1)",
                    border: "1px solid rgba(124,196,255,0.25)",
                    borderRadius: 8,
                    padding: "6px 14px",
                    color: "#7CC4FF",
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: disabled ? "not-allowed" : "pointer",
                    opacity: disabled ? 0.5 : 1,
                    minWidth: 84,
                  }}
                >
                  {isRefreshing ? "Refreshing…" : "Refresh"}
                </button>
              );
            })()}
          </div>
        </div>
        <div style={{ padding: "16px 18px", display: "flex", flexDirection: "column", gap: 10 }}>
          {concentrationWarning ? (
            <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(251,191,36,0.07)", border: "1px solid rgba(251,191,36,0.18)", fontSize: 13, color: "#fbbf24", lineHeight: 1.6 }}>
              {concentrationWarning}
            </div>
          ) : null}
          {lossWarning ? (
            <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(248,113,113,0.06)", border: "1px solid rgba(248,113,113,0.14)", fontSize: 13, color: "#fecaca", lineHeight: 1.6 }}>
              {lossWarning}
            </div>
          ) : null}
          <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(124,196,255,0.06)", border: "1px solid rgba(124,196,255,0.15)" }}>
            <div style={{ fontSize: 11, color: "#7CC4FF", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: 8, fontWeight: 700 }}>Next Action</div>
            <div style={{ display: "flex", gap: 8, fontSize: 13, color: "#e2e8f0", lineHeight: 1.5 }}>
              <span style={{ color: "#7CC4FF", fontWeight: 800, flexShrink: 0 }}>1.</span>
              <span>{nextAction}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function PositionBreakdownCard({ title, rows = [], totalValue = 0 }) {
  if (!rows.length) return null;
  const maxValue = Math.max(100, ...rows.map((row) => Math.abs(Number(row.value) || 0)));
  return (
    <div style={{ background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14, overflow: "hidden" }}>
      <div style={{ padding: "11px 16px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#7f8ea3", textTransform: "uppercase", letterSpacing: "0.6px" }}>{title}</div>
        <div style={{ fontSize: 11, color: "#475569" }}>{rows.length}</div>
      </div>
      <div style={{ padding: "4px 0", maxHeight: 140, overflowY: "auto" }}>
        {rows.map((row, index) => {
          const value = Number(row.value) || 0;
          const pl = Number(row.pl) || 0;
          const allocation = totalValue > 0 ? (value / totalValue) * 100 : 0;
          return (
            <div key={`${row.name}-${index}`} style={{ padding: "10px 16px", borderBottom: index < rows.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none", display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ minWidth: 92, maxWidth: 140, fontSize: 12, color: "#e2e8f0", fontWeight: 700, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row.name}</div>
              <div style={{ fontSize: 11, color: "#475569", whiteSpace: "nowrap", flexShrink: 0 }}>{row.count} · {allocation.toFixed(0)}%</div>
              <div style={{ flex: 1, height: 4, background: "rgba(255,255,255,0.05)", borderRadius: 2, overflow: "hidden" }}>
                <div style={{ height: "100%", width: `${Math.max(4, (Math.abs(value) / maxValue) * 100)}%`, background: "#7CC4FF", borderRadius: 2 }} />
              </div>
              <div style={{ fontSize: 12, fontWeight: 800, color: pl >= 0 ? "#4ade80" : "#f87171", minWidth: 64, textAlign: "right", flexShrink: 0 }}>{pl >= 0 ? "+" : ""}{formatCurrency(pl)}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function PerformanceLiveChartCard({
  alpacaPositions,
  performanceLiveAppliedSelection,
  setPerformanceLiveAppliedSelection,
  tradePortfolioAllSymbols,
  tradeChartSymbol,
  tradeChartCurrentPrice,
  tradeChartQuote,
  tradeChartMatchingPosition,
  tradeChartAsset,
  tradeChartAssetType,
  tradeChartRange,
  setTradeChartRange,
  tradeChartMode,
  setTradeChartMode,
  tradeChartLastUpdated,
  tradeIsComparisonMode,
  tradeIsPortfolioTotalMode,
  tradePortfolioCombinedUnrealizedPl,
  tradePortfolioCombinedMarketValue,
  tradePortfolioDisplayedPositions,
  tradePortfolioChartsLoading,
  tradePortfolioCharts,
  brokerTradeLog,
  trades,
  tradePortfolioRequestedStartMs,
  tradePortfolioNowMs,
  tradeMarketChartLoading,
  tradeMarketChart,
}) {
  const cardBase = { background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14 };
  const [historyRange, setHistoryRange] = useState("MAX");
  const [assetListScrolling, setAssetListScrolling] = useState(false);
  const assetScrollTimerRef = useRef(null);
  const handleAssetListScroll = () => {
    setAssetListScrolling(true);
    clearTimeout(assetScrollTimerRef.current);
    assetScrollTimerRef.current = setTimeout(() => setAssetListScrolling(false), 1200);
  };
  useEffect(() => () => clearTimeout(assetScrollTimerRef.current), []);
  const closedTrades = useMemo(
    () => trades
      .map((trade) => ({
        ...trade,
        symbol: String(trade?.asset || trade?.symbol || trade?.ticker || "").trim().toUpperCase(),
        timeMs: parseTradeTimeMs(trade),
        pnl: getTradeProfitValue(trade),
      }))
      .filter((trade) => trade.symbol && Number.isFinite(trade.timeMs) && Number.isFinite(trade.pnl)),
    [trades]
  );
  const closedTradeSymbols = useMemo(
    () => Array.from(new Set(closedTrades.map((trade) => trade.symbol))).sort(),
    [closedTrades]
  );
  const rangeWindowMs = getChartSelectionWindowMs(historyRange);
  const nowMs = Date.now();
  const rangeStartMs = rangeWindowMs ? nowMs - rangeWindowMs : null;
  const rangeLabel = (CHART_RANGE_OPTIONS.find((option) => option.value === historyRange)?.label) || historyRange;
  const historyRangeOptions = useMemo(
    () => CHART_RANGE_OPTIONS.filter((option) => ["1D", "1W", "1M", "3M", "1Y", "5Y", "MAX"].includes(option.value)),
    []
  );
  const [assetSearchQuery, setAssetSearchQuery] = useState("");
  const normalizeSelection = (selection) => {
    const validSymbols = Array.from(new Set((selection?.symbols || []).filter((symbol) => closedTradeSymbols.includes(symbol))));
    const includePortfolio = Boolean(selection?.includePortfolio);
    if (!includePortfolio && validSymbols.length === 0) {
      return { includePortfolio: true, symbols: [] };
    }
    return { includePortfolio, symbols: validSymbols };
  };
  const buildSelectionKey = (selection) => {
    const normalized = normalizeSelection(selection);
    return `${normalized.includePortfolio ? "portfolio" : "assets"}:${normalized.symbols.join(",")}`;
  };
  const [appliedSelection, setAppliedSelection] = useState(() => normalizeSelection({ includePortfolio: true, symbols: [] }));
  const appliedSelectionKey = useMemo(() => buildSelectionKey(appliedSelection), [appliedSelection]);
  const [pendingSelection, setPendingSelection] = useState(appliedSelection);
  const [historyChartViewport, setHistoryChartViewport] = useState({ zoom: 1, offset: 1 });
  useEffect(() => {
    setAppliedSelection((prev) => normalizeSelection(prev));
    setPendingSelection((prev) => normalizeSelection(prev));
  }, [closedTradeSymbols.join(",")]);
  useEffect(() => {
    setHistoryChartViewport({ zoom: 1, offset: 1 });
  }, [historyRange, appliedSelectionKey]);
  const isAppliedPortfolioMode = appliedSelection.includePortfolio;
  const selectedTargets = pendingSelection.includePortfolio
    ? ["PORTFOLIO", ...pendingSelection.symbols]
    : pendingSelection.symbols;
  const isTargetSelected = (target) => selectedTargets.includes(target);
  const selectionDirty = buildSelectionKey(pendingSelection) !== buildSelectionKey(appliedSelection);
  const togglePendingPortfolio = () => {
    setPendingSelection((prev) => {
      if (prev.includePortfolio && prev.symbols.length === 0) return prev;
      return normalizeSelection({ ...prev, includePortfolio: !prev.includePortfolio });
    });
  };
  const togglePendingSymbol = (symbol) => {
    setPendingSelection((prev) => {
      const current = new Set(prev.symbols);
      if (current.has(symbol)) current.delete(symbol);
      else current.add(symbol);
      return normalizeSelection({ ...prev, symbols: Array.from(current) });
    });
  };
  const applyPendingSelection = () => {
    setAppliedSelection(normalizeSelection(pendingSelection));
  };
  const ASSET_PALETTE = ["#60a5fa", "#34d399", "#f59e0b", "#f87171", "#a78bfa", "#fb923c"];
  const assetColorMap = {};
  closedTradeSymbols.forEach((symbol, index) => {
    assetColorMap[symbol] = ASSET_PALETTE[index % ASSET_PALETTE.length];
  });
  const filteredAssetChoices = useMemo(() => {
    const normalizedQuery = assetSearchQuery.trim().toUpperCase();
    if (!normalizedQuery) return closedTradeSymbols;
    return closedTradeSymbols.filter((symbol) => symbol.includes(normalizedQuery));
  }, [assetSearchQuery, closedTradeSymbols]);
  const buildClosedTradeSeries = (tradeRows) => {
    const sortedTrades = [...tradeRows].sort((a, b) => a.timeMs - b.timeMs);
    if (!sortedTrades.length) return [];
    const baselineTimeMs = rangeStartMs ?? Math.max(0, sortedTrades[0].timeMs - 1);
    let runningValue = 0;
    const points = [{ timeMs: baselineTimeMs, value: 0 }];
    sortedTrades.forEach((trade) => {
      runningValue += Number(trade.pnl) || 0;
      points.push({ timeMs: trade.timeMs, value: runningValue });
    });
    return points;
  };
  const visibleClosedTrades = useMemo(
    () => closedTrades.filter((trade) => rangeStartMs == null || trade.timeMs >= rangeStartMs),
    [closedTrades, rangeStartMs]
  );
  const portfolioSeries = useMemo(
    () => buildClosedTradeSeries(visibleClosedTrades),
    [visibleClosedTrades, rangeStartMs]
  );
  const assetSeries = useMemo(
    () => appliedSelection.symbols.map((symbol) => ({
      symbol,
      color: assetColorMap[symbol] || "#60a5fa",
      points: buildClosedTradeSeries(visibleClosedTrades.filter((trade) => trade.symbol === symbol)),
    })),
    [appliedSelection.symbols, assetColorMap, visibleClosedTrades, rangeStartMs]
  );
  const displayedLines = useMemo(() => {
    const nextLines = [];
    if (appliedSelection.includePortfolio) {
      nextLines.push({ symbol: "Strategy Total", color: "#7CC4FF", points: portfolioSeries });
    }
    assetSeries.forEach((line) => {
      if (line.points.length) nextLines.push(line);
    });
    return nextLines;
  }, [appliedSelection.includePortfolio, portfolioSeries, assetSeries]);
  const allVisibleValues = displayedLines.flatMap((line) => line.points.map((point) => point.value)).filter(Number.isFinite);
  const xRangeStartMs = rangeStartMs ?? Math.min(...displayedLines.flatMap((line) => line.points.map((point) => point.timeMs)).filter(Number.isFinite));
  const xRangeEndMs = Math.max(nowMs, ...displayedLines.flatMap((line) => line.points.map((point) => point.timeMs)).filter(Number.isFinite));
  const historyViewport = resolveCustomChartViewport(xRangeStartMs, xRangeEndMs, historyChartViewport);
  const selectedClosedTrades = useMemo(
    () => visibleClosedTrades.filter((trade) => appliedSelection.includePortfolio || appliedSelection.symbols.includes(trade.symbol)),
    [visibleClosedTrades, appliedSelection]
  );
  const selectedRealizedPnl = selectedClosedTrades.reduce((sum, trade) => sum + (Number(trade.pnl) || 0), 0);
  const chartStatsLabel = appliedSelection.includePortfolio
    ? "Strategy total + selected assets"
    : "Selected assets only";

  return (
    <div className="performanceLiveChartCard" style={{ ...cardBase, padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
      <div>
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "1.1px", textTransform: "uppercase", color: "#7f8ea3", marginBottom: 6 }}>
            Closed Trade History
          </div>
          <div style={{ fontSize: 17, fontWeight: 700, color: "#e2e8f0" }}>
            {appliedSelection.includePortfolio ? "Strategy Realized P/L" : appliedSelection.symbols.length ? appliedSelection.symbols.join(", ") : "Select an asset"}
          </div>
          <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 2 }}>
            Closed trades only. Open positions are excluded from this chart and any asset overlays.
          </div>
        </div>
      </div>

      <div className="performanceHistoryGrid" style={{ display: "grid", gridTemplateColumns: "minmax(180px, 0.34fr) minmax(0, 1fr)", gap: 16, alignItems: "stretch" }}>
        <div className="performanceHistorySidebar" style={{ display: "flex", flexDirection: "column", gap: 10, minWidth: 0, minHeight: 0 }}>
          <div style={{ fontSize: 10, color: "#7f8ea3", letterSpacing: "0.4px", textTransform: "uppercase" }}>
            Select assets to overlay
          </div>
          <button
            type="button"
            disabled={!selectionDirty}
            onClick={applyPendingSelection}
            style={{
              padding: "13px 16px",
              borderRadius: 12,
              border: `1px solid ${selectionDirty ? "rgba(124,196,255,0.36)" : "rgba(255,255,255,0.08)"}`,
              background: selectionDirty ? "rgba(124,196,255,0.12)" : "rgba(255,255,255,0.03)",
              boxShadow: selectionDirty ? "0 0 0 1px rgba(124,196,255,0.14), 0 0 20px rgba(124,196,255,0.08)" : "none",
              color: selectionDirty ? "#d7efff" : "#7f8ea3",
              fontSize: 14,
              fontWeight: 800,
              letterSpacing: "0.2px",
              cursor: selectionDirty ? "pointer" : "default",
              width: "100%",
              textAlign: "center",
              transition: "border-color 160ms ease, background 160ms ease, box-shadow 160ms ease, color 160ms ease",
            }}
          >
            View in chart
          </button>
          <input
            value={assetSearchQuery}
            onChange={(event) => setAssetSearchQuery(event.target.value)}
            placeholder="Search traded assets"
            style={{
              width: "100%",
              borderRadius: 12,
              border: "1px solid rgba(255,255,255,0.08)",
              background: "rgba(255,255,255,0.03)",
              color: "#e2e8f0",
              fontSize: 13,
              padding: "11px 12px",
              outline: "none",
            }}
          />
          <div
            className={`performanceHistoryAssetList${assetListScrolling ? " is-scrolling" : ""}`}
            onScroll={handleAssetListScroll}
            style={{ display: "flex", flexDirection: "column", gap: 8, flex: "1 1 0", minHeight: 0, overflowY: "auto", overscrollBehavior: "contain" }}
          >
            <button
              type="button"
              onClick={togglePendingPortfolio}
              style={{
                padding: 12,
                borderRadius: 12,
                background: isTargetSelected("PORTFOLIO") ? "rgba(124,196,255,0.08)" : "rgba(255,255,255,0.03)",
                border: `1px solid ${isTargetSelected("PORTFOLIO") ? "rgba(124,196,255,0.45)" : "rgba(255,255,255,0.06)"}`,
                boxShadow: isTargetSelected("PORTFOLIO") ? "0 0 0 1px rgba(124,196,255,0.15), 0 0 18px rgba(124,196,255,0.08)" : "none",
                cursor: "pointer",
                textAlign: "left",
                width: "100%",
                transition: "border-color 160ms ease, background 160ms ease, box-shadow 160ms ease",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
                <div style={{ fontSize: 15, fontWeight: 700, color: "#e2e8f0" }}>Strategy Total</div>
                <div style={{ fontSize: 12, color: selectedRealizedPnl >= 0 ? "#4ade80" : "#f87171", fontWeight: 700 }}>
                  {`${selectedRealizedPnl >= 0 ? "+" : ""}${formatCurrency(selectedRealizedPnl)}`}
                </div>
              </div>
              <div style={{ marginTop: 6, fontSize: 12, color: "#94a3b8", lineHeight: 1.6 }}>
                Realized P/L across the selected range. Closed trades only.
              </div>
            </button>
            {filteredAssetChoices.map((symbol) => {
              const visible = pendingSelection.symbols.includes(symbol);
              const lineColor = assetColorMap[symbol] || "#60a5fa";
              const appliedVisible = appliedSelection.symbols.includes(symbol);
              const symbolTrades = visibleClosedTrades.filter((trade) => trade.symbol === symbol);
              const symbolPnl = symbolTrades.reduce((sum, trade) => sum + (Number(trade.pnl) || 0), 0);
              const highlighted = visible;
              return (
                <button
                  key={symbol}
                  type="button"
                  onClick={() => togglePendingSymbol(symbol)}
                  style={{
                    padding: 12,
                    borderRadius: 12,
                    background: highlighted ? "rgba(124,196,255,0.08)" : "rgba(255,255,255,0.03)",
                    border: `1px solid ${highlighted ? "rgba(124,196,255,0.45)" : "rgba(255,255,255,0.06)"}`,
                    boxShadow: highlighted ? "0 0 0 1px rgba(124,196,255,0.15), 0 0 18px rgba(124,196,255,0.08)" : "none",
                    cursor: "pointer",
                    textAlign: "left",
                    width: "100%",
                    opacity: !visible ? 0.45 : 1,
                    transition: "border-color 160ms ease, background 160ms ease, box-shadow 160ms ease, opacity 160ms ease",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <div style={{ width: 8, height: 8, borderRadius: "50%", background: visible ? lineColor : "rgba(255,255,255,0.18)", flexShrink: 0 }} />
                      <div style={{ fontSize: 15, fontWeight: 700, color: "#e2e8f0" }}>{symbol}</div>
                      {isAppliedPortfolioMode && appliedVisible ? (
                        <span style={{ fontSize: 10, fontWeight: 700, color: "#d7efff", border: "1px solid rgba(124,196,255,0.2)", borderRadius: 999, padding: "2px 7px", background: "rgba(124,196,255,0.05)" }}>
                          Visible
                        </span>
                      ) : null}
                    </div>
                    <div style={{ fontSize: 12, color: symbolPnl >= 0 ? "#4ade80" : "#f87171", fontWeight: 700 }}>
                      {`${symbolPnl >= 0 ? "+" : ""}${formatCurrency(symbolPnl)}`}
                    </div>
                  </div>
                  <div style={{ marginTop: 6, fontSize: 12, color: "#94a3b8", lineHeight: 1.6 }}>
                    {symbolTrades.length} closed trade{symbolTrades.length === 1 ? "" : "s"} in range
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="performanceHistoryChartPanel" style={{ display: "flex", flexDirection: "column", gap: 12, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, flexWrap: "wrap" }}>
            <div style={{ display: "flex", flexDirection: "column", gap: 6, flex: 1, minWidth: 0 }}>
              <ChartTimeframeDropdown
                value={historyRange}
                onChange={setHistoryRange}
                options={historyRangeOptions}
                width={88}
              />
            </div>
            <div className="customChartInteractionHint">
              Scroll to zoom · drag to pan
            </div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
              <div style={{ fontSize: 12, fontWeight: 700, color: selectedRealizedPnl >= 0 ? "#4ade80" : "#f87171" }}>
                {`${selectedRealizedPnl >= 0 ? "+" : ""}${formatCurrency(selectedRealizedPnl)}`}
              </div>
              <div style={{ fontSize: 10, color: "#7f8ea3", textAlign: "right" }}>
                {rangeLabel} · Closed trades only
              </div>
            </div>
          </div>

          {allVisibleValues.length >= 1 ? (() => {
            const visibleStartMs = historyViewport.startMs;
            const visibleEndMs = historyViewport.endMs;
            const chartVisibleValues = displayedLines
              .flatMap((line) => line.points
                .filter((point) => point.timeMs >= visibleStartMs && point.timeMs <= visibleEndMs)
                .map((point) => point.value))
              .filter(Number.isFinite);
            const scaleValues = chartVisibleValues.length ? chartVisibleValues : allVisibleValues;
            const xL = 24;
            const xR = 238;
            const yT = 28;
            const yB = 178;
            const chartW = xR - xL;
            const chartH = yB - yT;
            const yMin = Math.min(...scaleValues);
            const yMax = Math.max(...scaleValues);
            const yPad = (yMax - yMin) * 0.16 || 25;
            const yLo = yMin - yPad;
            const yHi = yMax + yPad;
            const valueToY = (value) => yB - ((value - yLo) / (yHi - yLo || 1)) * chartH;
            const ySteps = Array.from({ length: 5 }, (_, index) => {
              const ratio = index / 4;
              return { y: yT + chartH * ratio, value: yHi - ((yHi - yLo) * ratio) };
            });
            const zeroY = valueToY(0);
            const xTicks = buildTradePortfolioTicks(visibleStartMs, visibleEndMs, historyRange);
            const lineMeta = displayedLines.map((line) => ({
              ...line,
              lastValue: line.points[line.points.length - 1]?.value,
              pointsSvg: line.points.map((point) => {
                const ratio = (point.timeMs - visibleStartMs) / Math.max(1, visibleEndMs - visibleStartMs);
                return `${xL + (ratio * chartW)},${valueToY(point.value)}`;
              }).join(" "),
            }));
            return (
              <div
                className="performanceHistoryChartBox"
                style={{ borderRadius: 12, overflow: "hidden", background: "#0d1117", border: "1px solid rgba(255,255,255,0.08)", position: "relative" }}
              >
                <InteractiveLineChart
                  className="performanceHistoryEngineChart"
                  height={380}
                  lines={lineMeta}
                  valueFormatter={(value) => Number.isFinite(Number(value)) ? `${Number(value) >= 0 ? "+" : ""}${formatCurrency(value)}` : "--"}
                  emptyMessage="No closed trades match this range yet."
                />
              </div>
            );
          })() : (
            <div className="emptyState">
              <div className="emptyStateTitle">No closed trades in this range yet</div>
              <div className="emptyStateCopy">Open positions stay out of this realized performance chart so the review stays clean once trades are complete.</div>
            </div>
          )}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 10 }}>
        <div>
          <div style={{ fontSize: 12, color: "#7f8ea3", marginBottom: 4 }}>Assets Selected</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#e2e8f0" }}>{appliedSelection.symbols.length + (isAppliedPortfolioMode ? 1 : 0)}</div>
        </div>
        <div>
          <div style={{ fontSize: 12, color: "#7f8ea3", marginBottom: 4 }}>View</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#e2e8f0" }}>
            {chartStatsLabel}
          </div>
        </div>
        <div>
          <div style={{ fontSize: 12, color: "#7f8ea3", marginBottom: 4 }}>Closed Trades</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#e2e8f0" }}>
            {selectedClosedTrades.length}
          </div>
        </div>
        <div>
          <div style={{ fontSize: 12, color: "#7f8ea3", marginBottom: 4 }}>Realized P/L</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: selectedRealizedPnl >= 0 ? "#4ade80" : "#f87171" }}>
            {`${selectedRealizedPnl >= 0 ? "+" : ""}${formatCurrency(selectedRealizedPnl)}`}
          </div>
        </div>
      </div>
    </div>
  );
}

function PortfolioTrendCard({
  positions = [],
  alpacaAccount = null,
  tradePortfolioCharts = {},
  tradePortfolioChartsLoading = false,
  portfolioSnapshots = [],
  portfolioSnapshotsLoading = false,
  snapshotView = "portfolio",
  portfolioRange = "MAX",
  setPortfolioRange = () => {},
  title = "Portfolio",
  subtitle = "Portfolio value including all open and closed positions.",
  emptyMessage = "Performance history grows automatically as Rayla collects broker snapshots.",
  statusLabel = null,
  chartHeight = 340,
  useAccountValue = true,
  timeZone = null,
  prebuiltPoints = null,
  rangeNote = null,
  openPnl = null,
  openPct = null,
  preferPaper = false,
  intentOverrides = null,
}) {
  const allPositions = Array.isArray(positions) ? positions : [];
  const totalMarketValue = allPositions.reduce((s, p) => s + (Number(p?.marketValue) || 0), 0);
  const accountPortfolioValue = useAccountValue
    ? Number(alpacaAccount?.portfolioValue ?? alpacaAccount?.equity)
    : null;
  const portfolioValue = Number.isFinite(accountPortfolioValue) && accountPortfolioValue > 0
    ? accountPortfolioValue
    : totalMarketValue || 0;
  const resolvedStatusLabel = statusLabel ?? (alpacaAccount?.isPaper != null ? (alpacaAccount.isPaper ? "Paper" : "Live") : null);
  // Prefer the account currently in the UI over the preference flag. Otherwise the
  // chart can request live history while stats/positions show paper — brokerPreferPaper
  // is per-origin localStorage that can drift from alpacaAccount when the account was
  // fetched via an explicit override (Switch-to-Paper button, OAuth callback on a
  // different origin, etc). alpacaAccount.isPaper is what the rest of the UI displays.
  const resolvedPreferPaper = alpacaAccount?.isPaper != null
    ? Boolean(alpacaAccount.isPaper)
    : preferPaper;

  return (
    <PortfolioHistoryChart
      title={title}
      subtitle={subtitle}
      currentValue={portfolioValue}
      positionsCount={allPositions.length}
      positionsValue={totalMarketValue}
      statusLabel={resolvedStatusLabel}
      range={portfolioRange}
      onRangeChange={setPortfolioRange}
      height={chartHeight}
      timeZone={timeZone}
      emptyMessage={emptyMessage}
      className={`portfolioHistoryChart-${snapshotView}`}
      fallbackSnapshots={portfolioSnapshots}
      snapshotView={snapshotView}
      prebuiltPoints={prebuiltPoints}
      rangeNote={rangeNote}
      openPnl={openPnl}
      openPct={openPct}
      preferPaper={resolvedPreferPaper}
      intentOverrides={intentOverrides}
    />
  );
}

function PortfolioPerformancePanel({
  positions = [],
  alpacaAccount = null,
  alpacaConnected = false,
  tradePortfolioCharts = {},
  tradePortfolioChartsLoading = false,
  portfolioSnapshots = [],
  portfolioSnapshotsLoading = false,
  brokerTradeLog = [],
  portfolioRange = "MAX",
  setPortfolioRange = () => {},
  equityPoints = [],
  sourceLabel = "Portfolio",
  chartRange = "ALL",
  setChartRange = () => {},
  benchmarkSymbol = "SPY",
  benchmarkLabel = "SPY",
  onSelectBenchmark = () => {},
  benchmarkOptions = [],
  benchmarkPoints = [],
  benchmarkLoading = false,
  timeZone = null,
  positionActions = null,
  portfolioInceptionMs = null,
  preferPaper = false,
  onRefresh = null,
}) {
  const portfolioRanges = [
    { value: "1D", label: "1D" },
    { value: "1M", label: "1M" },
    { value: "1Y", label: "1Y" },
    { value: "MAX", label: "All" },
  ];
  const rangeMs = getChartSelectionWindowMs(portfolioRange);
  const nowMs = Date.now();
  const myRequestedStartMs = rangeMs ? nowMs - rangeMs : null;

  const allPositions = Array.isArray(positions) ? positions : [];
  const totalMarketValue = allPositions.reduce((s, p) => s + (Number(p?.marketValue) || 0), 0);
  const totalUnrealizedPl = allPositions.reduce((s, p) => s + (Number(p?.unrealizedPl) || 0), 0);
  const totalCostBasis = getOpenPositionCostBasis(allPositions);
  const unrealizedPct = totalCostBasis > 0 ? (totalUnrealizedPl / totalCostBasis) * 100 : null;
  const dayPnL = calculateBrokerDayPnL(allPositions, alpacaAccount);
  // Broker source-of-truth Day P/L pct for the Performance Portfolio 1D headline.
  // Mirrors the Home-page pattern (App.jsx homePortfolioDayPnLPct) so Performance,
  // Home, and Live Trades all show identical Day P/L. Only used when range === "1D".
  const dayPnLBaseline = Number.isFinite(dayPnL) && dayPnL != null
    ? (Number(alpacaAccount?.equity ?? alpacaAccount?.portfolioValue) || 0) - dayPnL
    : null;
  const dayPnLPct = Number.isFinite(dayPnL) && Number.isFinite(dayPnLBaseline) && dayPnLBaseline > 0
    ? (dayPnL / dayPnLBaseline) * 100
    : null;
  const portfolioValue = Number(alpacaAccount?.portfolioValue ?? alpacaAccount?.equity) || totalMarketValue || 0;
  const cash = alpacaAccount ? (Number(alpacaAccount.cash) || 0) : null;
  const plPos = totalUnrealizedPl >= 0;
  const dayPos = Number.isFinite(dayPnL) && dayPnL >= 0;
  const sortedPositions = useMemo(
    () => [...allPositions].sort((a, b) => (Number(b?.marketValue) || 0) - (Number(a?.marketValue) || 0)),
    [allPositions]
  );

  const portfolioBenchmarkChart = useMemo(
    () => buildPortfolioChartFromSnapshots(
      portfolioSnapshots,
      myRequestedStartMs,
      nowMs,
      "portfolio",
      "Performance Portfolio"
    ),
    [portfolioSnapshots, myRequestedStartMs, nowMs]
  );
  const portfolioLinePoints = useMemo(
    () => buildOpenPositionReturnLinePoints(portfolioBenchmarkChart, totalCostBasis),
    [portfolioBenchmarkChart, totalCostBasis]
  );
  const portfolioReturnPct = unrealizedPct;
  const portfolioPositive = totalUnrealizedPl >= 0;
  const portfolioLineColor = "#7CC4FF";
  const performancePortfolioLines = [
    portfolioLinePoints.length >= 2
      ? { symbol: "Portfolio", color: portfolioLineColor, points: portfolioLinePoints }
      : null,
  ].filter(Boolean);

  if (!alpacaConnected) {
    return (
      <div style={{ padding: "48px 24px", textAlign: "center", color: "#4a5568", fontSize: 13 }}>
        Connect your broker to view your live portfolio here.
      </div>
    );
  }
  if (!allPositions.length) {
    return (
      <div style={{ padding: "48px 24px", textAlign: "center", color: "#4a5568", fontSize: 13 }}>
        No open positions. Portfolio view shows your live broker positions.
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>

      <div data-tour-id="perf-portfolio-chart">
        <PortfolioTrendCard
          positions={allPositions}
          alpacaAccount={alpacaAccount}
          tradePortfolioCharts={tradePortfolioCharts}
          tradePortfolioChartsLoading={tradePortfolioChartsLoading}
          portfolioSnapshots={portfolioSnapshots}
          portfolioSnapshotsLoading={portfolioSnapshotsLoading}
          snapshotView="portfolio"
          portfolioRange={portfolioRange}
          setPortfolioRange={setPortfolioRange}
          title="Investing"
          subtitle="Portfolio value including all open and closed positions."
          chartHeight={520}
          timeZone={timeZone}
          rangeNote={buildPortfolioRangeNote(portfolioRange, portfolioInceptionMs)}
          openPnl={portfolioRange === "1D" ? dayPnL : null}
          openPct={portfolioRange === "1D" ? dayPnLPct : null}
          preferPaper={preferPaper}
        />
      </div>

      {/* ── Secondary stats strip ────────────────────────────────── */}
      <div data-tour-id="perf-portfolio-stats" style={{
        display: "grid",
        gridTemplateColumns: "repeat(3, 1fr)",
        background: "rgba(8,16,26,0.7)",
        border: "1px solid rgba(255,255,255,0.06)",
        borderRadius: 14,
        overflow: "hidden",
      }}>
        {[
          { label: "Cash", value: cash !== null ? formatCurrency(cash) : "—", color: "#e2e8f0" },
          {
            label: "Open positions today",
            value: Number.isFinite(dayPnL) ? `${dayPos ? "+" : ""}${formatCurrency(dayPnL)}` : "—",
            color: Number.isFinite(dayPnL) ? (dayPos ? "#4ade80" : "#f87171") : "#e2e8f0",
          },
          { label: "Positions", value: String(allPositions.length), color: "#e2e8f0" },
        ].map((m, idx, arr) => (
          <div
            key={m.label}
            style={{
              padding: "13px 18px",
              borderRight: idx < arr.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none",
            }}
          >
            <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#334155", marginBottom: 5 }}>
              {m.label}
            </div>
            <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.value}</div>
          </div>
        ))}
      </div>

      {/* ── Allocation + Positions ───────────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12 }}>

        {/* Allocation */}
        <div data-tour-id="perf-portfolio-allocation" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#94a3b8", marginBottom: 16 }}>
            Allocation
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 13, maxHeight: 250, overflowY: "auto" }}>
            {sortedPositions.map((pos) => {
              const mv = Number(pos?.marketValue) || 0;
              const alloc = totalMarketValue > 0 ? (mv / totalMarketValue) * 100 : 0;
              const pl = Number(pos?.unrealizedPl) || 0;
              return (
                <div key={pos.symbol}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 7 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: "#dde6f0" }}>{pos.symbol}</span>
                    <span style={{ fontSize: 12, color: "#94a3b8" }}>{formatPerformancePercent(alloc)}</span>
                  </div>
                  <div style={{ height: 5, borderRadius: 999, background: "rgba(255,255,255,0.05)" }}>
                    <div style={{
                      width: `${Math.max(0, Math.min(100, alloc))}%`,
                      height: "100%",
                      borderRadius: 999,
                      background: pl >= 0
                        ? "linear-gradient(90deg, #4ade80, #60a5fa)"
                        : "linear-gradient(90deg, #f87171, #fb923c)",
                      opacity: 0.75,
                    }} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Positions */}
        <div data-tour-id="perf-portfolio-positions" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#94a3b8", marginBottom: 16 }}>
            Positions
          </div>
          {positionActions && positionActions}
          <div style={{ maxHeight: 200, overflowY: "auto" }}>
            {sortedPositions.map((pos, idx) => {
              const pl = Number(pos?.unrealizedPl) || 0;
              const plpc = Number(pos?.unrealizedPlpc);
              const isEquity = pos.assetClass && pos.assetClass !== "crypto";
              return (
                <div
                  key={pos.symbol}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 12,
                    padding: "12px 0",
                    borderBottom: idx < sortedPositions.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none",
                  }}
                >
                  <div>
                    <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                      <span style={{ fontSize: 14, fontWeight: 800, color: "#f0f6ff" }}>{pos.symbol}</span>
                      <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: isEquity ? "#4a7fa8" : "#7c6aad" }}>
                        {isEquity ? "EQ" : "CR"}
                      </span>
                    </div>
                    <div style={{ fontSize: 11, color: "#94a3b8", marginTop: 3 }}>
                      {formatBrokerQuantity(pos.qty)} × {formatCurrency(pos.avgEntryPrice || 0)} · {formatCurrency(pos.marketValue)}
                    </div>
                  </div>
                  <div style={{ textAlign: "right", flexShrink: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: pl >= 0 ? "#4ade80" : "#f87171" }}>
                      {pl >= 0 ? "+" : ""}{formatCurrency(pl)}
                    </div>
                    <div style={{ fontSize: 11, color: pl >= 0 ? "#6ee7b7" : "#fca5a5", marginTop: 2, opacity: 0.85 }}>
                      {Number.isFinite(plpc) ? formatPerformancePercent(plpc * 100) : "—"}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

      </div>

      <PositionPerformanceInsights
        title="Portfolio"
        scopeLabel="positions"
        positions={sortedPositions}
        totalValue={totalMarketValue}
        totalUnrealizedPl={totalUnrealizedPl}
        unrealizedPct={unrealizedPct}
        onRefresh={onRefresh}
      />
    </div>
  );
}

function HoldingsPerformancePanel({
  positions = [],
  alpacaConnected = false,
  tradePortfolioCharts = {},
  tradePortfolioChartsLoading = false,
  portfolioSnapshots = [],
  portfolioSnapshotsLoading = false,
  brokerTradeLog = [],
  portfolioRange = "MAX",
  setPortfolioRange = () => {},
  timeZone = null,
  onAskRayla = null,
  onSaveThesis = null,
  portfolioInceptionMs = null,
  intentOverrides = null,
  preferPaper = false,
  onRefresh = null,
}) {
  const holdings = Array.isArray(positions) ? positions : [];
  const rangeOptions = [
    { value: "1D", label: "1D" },
    { value: "1M", label: "1M" },
    { value: "1Y", label: "1Y" },
    { value: "MAX", label: "All" },
  ];
  const rangeMs = getChartSelectionWindowMs(portfolioRange);
  const nowMs = Date.now();
  const myRequestedStartMs = rangeMs ? nowMs - rangeMs : null;

  const summary = useMemo(() => {
    const totalValue = holdings.reduce((sum, p) => sum + (Number(p?.marketValue) || 0), 0);
    const totalUnrealizedPl = holdings.reduce((sum, p) => sum + (Number(p?.unrealizedPl) || 0), 0);
    const totalCostBasis = getOpenPositionCostBasis(holdings);
    const unrealizedPct = totalCostBasis > 0 ? (totalUnrealizedPl / totalCostBasis) * 100 : null;
    return { totalValue, totalUnrealizedPl, totalCostBasis, unrealizedPct };
  }, [holdings]);
  const plPos = summary.totalUnrealizedPl >= 0;

  const sortedHoldings = useMemo(
    () => [...holdings].sort((a, b) => (Number(b?.marketValue) || 0) - (Number(a?.marketValue) || 0)),
    [holdings]
  );

  const holdingsBenchmarkChart = useMemo(
    () => buildPortfolioChartFromSnapshots(
      portfolioSnapshots,
      myRequestedStartMs,
      nowMs,
      "holdings",
      "Performance Long-Term Holdings",
      intentOverrides
    ),
    [portfolioSnapshots, myRequestedStartMs, nowMs, intentOverrides]
  );
  const holdingsLinePoints = useMemo(
    () => buildOpenPositionReturnLinePoints(holdingsBenchmarkChart, summary.totalCostBasis),
    [holdingsBenchmarkChart, summary.totalCostBasis]
  );

  const holdingsPeriodReturn = useMemo(() => buildPeriodReturnFromChart(holdingsBenchmarkChart), [holdingsBenchmarkChart]);
  const holdingsDisplayPnl = Number.isFinite(holdingsPeriodReturn?.pnl) ? holdingsPeriodReturn.pnl : null;
  const holdingsReturnPct = Number.isFinite(holdingsPeriodReturn?.returnPct) ? holdingsPeriodReturn.returnPct : null;
  const holdingsPositive = Number.isFinite(holdingsDisplayPnl) ? holdingsDisplayPnl >= 0 : true;
  const holdingsLineColor = "#7CC4FF";
  const chartLines = holdingsLinePoints.length >= 2
    ? [{ symbol: "Holdings", color: holdingsLineColor, points: holdingsLinePoints }]
    : [];

  import.meta.env.DEV && console.log("[HoldingsPerformancePanel]", {
    timeframe: portfolioRange,
    firstPortfolioValue: holdingsPeriodReturn?.firstValue ?? null,
    lastPortfolioValue: holdingsPeriodReturn?.lastValue ?? null,
    periodPnL: holdingsPeriodReturn?.pnl ?? null,
    periodReturnPct: holdingsPeriodReturn?.returnPct ?? null,
    includedSymbols: holdings.map((p) => p.symbol),
    includedSnapshotsCount: holdingsPeriodReturn?.barsCount ?? 0,
  });

  if (!alpacaConnected) {
    return (
      <div className="emptyState">
        <div className="emptyStateTitle">Connect your broker to view holdings</div>
        <div className="emptyStateCopy">Long-term positions will appear here with trend, allocation, and unrealized P/L once broker data is available.</div>
      </div>
    );
  }
  if (!holdings.length) {
    return (
      <div className="emptyState">
        <div className="emptyStateTitle">No long-term holdings selected yet</div>
        <div className="emptyStateCopy">Classify a broker position as Investment in Live Trades and Rayla will move it into this view.</div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>

      <div data-tour-id="perf-holdings-hero">
        <PortfolioTrendCard
          positions={holdings}
          alpacaAccount={null}
          tradePortfolioCharts={tradePortfolioCharts}
          tradePortfolioChartsLoading={tradePortfolioChartsLoading}
          portfolioSnapshots={portfolioSnapshots}
          portfolioSnapshotsLoading={portfolioSnapshotsLoading}
          snapshotView="holdings"
          portfolioRange={portfolioRange}
          setPortfolioRange={setPortfolioRange}
          title="Long-Term Holdings"
          subtitle="Broker positions classified as investments or long-term holds."
          emptyMessage="Performance history grows automatically as Rayla collects broker snapshots."
          statusLabel="Holdings"
          chartHeight={420}
          useAccountValue={false}
          timeZone={timeZone}
          openPnl={summary.totalUnrealizedPl}
          openPct={summary.unrealizedPct}
          rangeNote={buildPortfolioRangeNote(portfolioRange, portfolioInceptionMs)}
          intentOverrides={intentOverrides}
          preferPaper={preferPaper}
        />
      </div>

      {/* ── Stats strip ─────────────────────────────────────────── */}
      <div data-tour-id="perf-holdings-stats" style={{
        display: "grid",
        gridTemplateColumns: "repeat(3, 1fr)",
        background: "rgba(8,16,26,0.7)",
        border: "1px solid rgba(255,255,255,0.06)",
        borderRadius: 14,
        overflow: "hidden",
      }}>
        {[
          { label: "Holdings Value", value: formatCurrency(summary.totalValue), color: "#e2e8f0" },
          {
            label: "Unrealized P/L",
            value: `${plPos ? "+" : ""}${formatCurrency(summary.totalUnrealizedPl)}`,
            color: plPos ? "#4ade80" : "#f87171",
          },
          {
            label: "Unrealized %",
            value: summary.unrealizedPct == null ? "—" : formatPerformancePercent(summary.unrealizedPct),
            color: plPos ? "#4ade80" : "#f87171",
          },
        ].map((m, idx, arr) => (
          <div key={m.label} style={{ padding: "13px 18px", borderRight: idx < arr.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none" }}>
            <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#334155", marginBottom: 5 }}>
              {m.label}
            </div>
            <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.value}</div>
          </div>
        ))}
      </div>

      {/* ── Allocation + Holdings list ───────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12 }}>

        <div data-tour-id="perf-holdings-allocation" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#334155", marginBottom: 16 }}>
            Allocation
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 13 }}>
            {sortedHoldings.map((pos) => {
              const mv = Number(pos?.marketValue) || 0;
              const alloc = summary.totalValue > 0 ? (mv / summary.totalValue) * 100 : 0;
              const pl = Number(pos?.unrealizedPl) || 0;
              return (
                <div key={pos.symbol}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 7 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: "#dde6f0" }}>{pos.symbol}</span>
                    <span style={{ fontSize: 12, color: "#334155" }}>{formatPerformancePercent(alloc)}</span>
                  </div>
                  <div style={{ height: 5, borderRadius: 999, background: "rgba(255,255,255,0.05)" }}>
                    <div style={{
                      width: `${Math.max(0, Math.min(100, alloc))}%`,
                      height: "100%",
                      borderRadius: 999,
                      background: pl >= 0 ? "linear-gradient(90deg, #4ade80, #60a5fa)" : "linear-gradient(90deg, #f87171, #fb923c)",
                      opacity: 0.75,
                    }} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div data-tour-id="perf-holdings-list" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#334155", marginBottom: 16 }}>
            Holdings
          </div>
          <div>
            {sortedHoldings.map((pos, idx) => {
              const pl = Number(pos?.unrealizedPl) || 0;
              const plpc = Number(pos?.unrealizedPlpc);
              const isEquity = pos.assetClass && pos.assetClass !== "crypto";
              return (
                <div
                  key={pos.symbol}
                  style={{
                    padding: "12px 0",
                    borderBottom: idx < sortedHoldings.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
                    <div>
                      <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                        <span style={{ fontSize: 14, fontWeight: 800, color: "#f0f6ff" }}>{pos.symbol}</span>
                        <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: isEquity ? "#4a7fa8" : "#7c6aad" }}>
                          {isEquity ? "EQ" : "CR"}
                        </span>
                      </div>
                      <div style={{ fontSize: 11, color: "#334155", marginTop: 3 }}>
                        {formatBrokerQuantity(pos.qty)} × {formatCurrency(pos.avgEntryPrice || 0)} · {formatCurrency(pos.marketValue)}
                      </div>
                    </div>
                    <div style={{ textAlign: "right", flexShrink: 0 }}>
                      <div style={{ fontSize: 14, fontWeight: 700, color: pl >= 0 ? "#4ade80" : "#f87171" }}>
                        {pl >= 0 ? "+" : ""}{formatCurrency(pl)}
                      </div>
                      <div style={{ fontSize: 11, color: pl >= 0 ? "#6ee7b7" : "#fca5a5", marginTop: 2, opacity: 0.85 }}>
                        {Number.isFinite(plpc) ? formatPerformancePercent(plpc * 100) : "—"}
                      </div>
                      {onAskRayla && (
                        <button
                          type="button"
                          onClick={() => onAskRayla(pos.symbol)}
                          style={{ fontSize: 10, fontWeight: 600, color: "#7CC4FF", background: "none", border: "none", cursor: "pointer", padding: "4px 0 0 0", display: "block", marginLeft: "auto" }}
                        >
                          Ask Rayla →
                        </button>
                      )}
                    </div>
                  </div>
                  {onSaveThesis && (
                    <div style={{ marginTop: 8 }}>
                      <div style={{ fontSize: 10, color: "#475569", marginBottom: 4, fontWeight: 500, letterSpacing: "0.03em" }}>
                        Why I Own It <span style={{ color: "#334155", fontWeight: 400 }}>optional · used by Rayla</span>
                      </div>
                      <textarea
                        defaultValue={pos.thesis || ""}
                        onBlur={(e) => onSaveThesis(pos.symbol, e.target.value)}
                        placeholder="AI infrastructure growth, cloud expansion, dividend income, undervalued business, long-term compounder, 5+ year hold…"
                        rows={2}
                        style={{ width: "100%", background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)", borderRadius: 8, padding: "7px 10px", color: "#cbd5e1", fontSize: 11, resize: "vertical", outline: "none", fontFamily: "inherit", boxSizing: "border-box", lineHeight: 1.55 }}
                      />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

      </div>

      <PositionPerformanceInsights
        title="Long-Term Holdings"
        scopeLabel="holdings"
        positions={sortedHoldings}
        totalValue={summary.totalValue}
        totalUnrealizedPl={summary.totalUnrealizedPl}
        unrealizedPct={summary.unrealizedPct}
        onRefresh={onRefresh}
      />
    </div>
  );
}

function ActiveTradesPerformancePanel({
  positions = [],
  alpacaConnected = false,
  tradePortfolioCharts = {},
  tradePortfolioChartsLoading = false,
  portfolioSnapshots = [],
  portfolioSnapshotsLoading = false,
  portfolioRange = "MAX",
  setPortfolioRange = () => {},
  brokerTradeLog = [],
  closedEquityPoints = [],
  sourceLabel = "Built from closed day and swing trades.",
  chartRange = "ALL",
  setChartRange = () => {},
  benchmarkSymbol = "SPY",
  benchmarkLabel = "SPY",
  onSelectBenchmark = () => {},
  benchmarkOptions = [],
  benchmarkPoints = [],
  benchmarkLoading = false,
  coachSummary = null,
  showNoNewTrades = false,
  onRunAnalysis = null,
  timeZone = null,
  startingCapital = 0,
  onChangeStartingCapital = null,
  intentOverrides = null,
  preferPaper = false,
  onRefresh = null,
}) {
  const trades = Array.isArray(positions) ? positions : [];
  const nowMs = Date.now();
  const rangeMs = getChartSelectionWindowMs(portfolioRange);
  const myRequestedStartMs = rangeMs ? nowMs - rangeMs : null;

  const closedActiveTrades = useMemo(() => {
    const normalized = buildNormalizedBrokerTrades(brokerTradeLog);
    return normalized.filter((t) => t.tradeType === "day_trade" || t.tradeType === "swing_trade");
  }, [brokerTradeLog]);

  const closedStats = useMemo(() => {
    if (!closedActiveTrades.length) return null;
    const totalRealizedPl = closedActiveTrades.reduce((sum, t) => sum + (Number(t.pnl_value) || 0), 0);
    const winners = closedActiveTrades.filter((t) => (Number(t.pnl_value) || 0) > 0).length;
    const losers = closedActiveTrades.filter((t) => (Number(t.pnl_value) || 0) < 0).length;
    const count = closedActiveTrades.length;
    const winRate = count > 0 ? (winners / count) * 100 : null;
    return { totalRealizedPl, winners, losers, count, winRate };
  }, [closedActiveTrades]);

  const summary = useMemo(() => {
    const totalValue = trades.reduce((sum, p) => sum + (Number(p?.marketValue) || 0), 0);
    const totalUnrealizedPl = trades.reduce((sum, p) => sum + (Number(p?.unrealizedPl) || 0), 0);
    const totalCostBasis = getOpenPositionCostBasis(trades);
    const unrealizedPct = totalCostBasis > 0 ? (totalUnrealizedPl / totalCostBasis) * 100 : null;
    return { totalValue, totalUnrealizedPl, totalCostBasis, unrealizedPct };
  }, [trades]);

  const sortedTrades = useMemo(
    () => [...trades].sort((a, b) => (Number(b?.marketValue) || 0) - (Number(a?.marketValue) || 0)),
    [trades]
  );

  const benchmarkChart = useMemo(
    () => buildPortfolioChartFromSnapshots(
      portfolioSnapshots,
      myRequestedStartMs,
      nowMs,
      "active",
      "Performance Day Trades",
      intentOverrides
    ),
    [portfolioSnapshots, myRequestedStartMs, nowMs, intentOverrides]
  );
  const linePoints = useMemo(() => {
    const pts = buildOpenPositionReturnLinePoints(benchmarkChart, summary.totalCostBasis);
    if (pts.length >= 2) return pts;
    // Fallback: self-normalize from the first bar when there is no open-position cost basis
    const bars = extractChartBars(benchmarkChart);
    if (bars.length < 2) return [];
    const firstClose = Number(bars[0]?.close);
    if (!Number.isFinite(firstClose) || firstClose <= 0) return [];
    return bars.map((bar) => {
      const timeMs = getChartBarTimeMs(bar);
      const value = Number(bar?.close);
      if (!Number.isFinite(timeMs) || !Number.isFinite(value) || value <= 0) return null;
      return { timeMs, value: ((value - firstClose) / firstClose) * 100, rawValue: value, costBasis: firstClose };
    }).filter(Boolean).sort((a, b) => a.timeMs - b.timeMs);
  }, [benchmarkChart, summary.totalCostBasis]);

  const activePeriodReturn = useMemo(() => buildPeriodReturnFromChart(benchmarkChart), [benchmarkChart]);
  const activeDisplayPnl = Number.isFinite(activePeriodReturn?.pnl) ? activePeriodReturn.pnl : null;
  const returnPct = Number.isFinite(activePeriodReturn?.returnPct) ? activePeriodReturn.returnPct : null;
  const plPos = Number.isFinite(activeDisplayPnl) ? activeDisplayPnl >= 0 : true;
  const currentPlPos = summary.totalUnrealizedPl >= 0;
  const lineColor = "#7CC4FF";
  const chartLines = linePoints.length >= 2
    ? [{ symbol: "Day Trades", color: lineColor, points: linePoints }]
    : [];

  const hasOpenTrades = trades.length > 0;
  const hasClosedTrades = closedActiveTrades.length > 0;
  const canRunAiAnalysis = typeof onRunAnalysis === "function";


  if (!alpacaConnected) {
    return (
      <div className="emptyState">
        <div className="emptyStateTitle">Connect your broker to view day trades</div>
        <div className="emptyStateCopy">Open day-trade and swing-trade positions will appear here with unrealized P/L once broker data is available.</div>
      </div>
    );
  }
  if (!hasOpenTrades && !hasClosedTrades) {
    return (
      <div className="emptyState">
        <div className="emptyStateTitle">No day trades yet</div>
        <div className="emptyStateCopy">Day and swing trades will appear here once you open a broker position or close a day/swing trade.</div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>

      <div data-tour-id="perf-daytrades-hero">
        {hasOpenTrades ? (
          <PortfolioTrendCard
            positions={trades}
            alpacaAccount={null}
            tradePortfolioCharts={tradePortfolioCharts}
            tradePortfolioChartsLoading={tradePortfolioChartsLoading}
            portfolioSnapshots={portfolioSnapshots}
            portfolioSnapshotsLoading={portfolioSnapshotsLoading}
            snapshotView="active"
            portfolioRange={portfolioRange}
            setPortfolioRange={setPortfolioRange}
            title="Day Trades"
            subtitle="Open day/swing positions only. Closed trade performance remains in the equity curve below."
            emptyMessage="Performance history grows automatically as Rayla collects broker snapshots."
            statusLabel="Day Trades"
            chartHeight={420}
            useAccountValue={false}
            timeZone={timeZone}
            preferPaper={preferPaper}
          />
        ) : hasClosedTrades ? (
          <div className="performancePortfolioTrendCard" style={{
            minHeight: 0,
            background: "linear-gradient(180deg, rgba(12,18,28,0.96), rgba(7,11,18,0.98))",
            border: "1px solid rgba(148,163,184,0.16)",
            borderRadius: 18,
            padding: "22px 24px",
          }}>
            <div className="performancePortfolioHomeTitle">Day Trades</div>
            <div className="performancePortfolioHomeValueRow">
              <span
                className="performancePortfolioHomeInlineChange"
                style={{ color: closedStats.totalRealizedPl >= 0 ? "#4ade80" : "#f87171" }}
              >
                {closedStats.totalRealizedPl >= 0 ? "+" : ""}{formatCurrency(closedStats.totalRealizedPl)}
              </span>
            </div>
            <div className="performancePortfolioHomeSubcopy">
              Showing closed day/swing trade performance. Open day trades will appear here when active.
            </div>
          </div>
        ) : null}
      </div>

      {/* ── No-open-trades banner ──────────────────────────────────── */}
      {!hasOpenTrades && (
        <div style={{
          background: "rgba(167,139,250,0.06)",
          border: "1px solid rgba(167,139,250,0.15)",
          borderRadius: 12,
          padding: "12px 16px",
          fontSize: 13,
          color: "#94a3b8",
          textAlign: "center",
        }}>
          No open day trades. Showing closed day/swing trade performance below.
        </div>
      )}

      {hasClosedTrades && (
        <div data-tour-id="perf-daytrades-equity">
          <EquityCurveCard
            equityPoints={closedEquityPoints}
            sourceLabel={sourceLabel}
            chartRange={chartRange}
            setChartRange={setChartRange}
            benchmarkSymbol={benchmarkSymbol}
            benchmarkLabel={benchmarkLabel}
            onSelectBenchmark={onSelectBenchmark}
            benchmarkOptions={benchmarkOptions}
            benchmarkPoints={benchmarkPoints}
            benchmarkLoading={benchmarkLoading}
            alpacaConnected={alpacaConnected}
            timeZone={timeZone}
            startingCapital={startingCapital}
            onChangeStartingCapital={onChangeStartingCapital}
          />
        </div>
      )}

      {/* ── Open positions stats strip ────────────────────────────── */}
      {hasOpenTrades && (
        <div data-tour-id="perf-daytrades-open-stats" style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          background: "rgba(8,16,26,0.7)",
          border: "1px solid rgba(255,255,255,0.06)",
          borderRadius: 14,
          overflow: "hidden",
        }}>
          {[
            { label: "Position Value", value: formatCurrency(summary.totalValue), color: "#e2e8f0" },
            {
              label: "Unrealized P/L",
              value: `${currentPlPos ? "+" : ""}${formatCurrency(summary.totalUnrealizedPl)}`,
              color: currentPlPos ? "#4ade80" : "#f87171",
            },
            {
              label: "Unrealized %",
              value: summary.unrealizedPct == null ? "—" : formatPerformancePercent(summary.unrealizedPct),
              color: currentPlPos ? "#4ade80" : "#f87171",
            },
          ].map((m, idx, arr) => (
            <div key={m.label} style={{ padding: "13px 18px", borderRight: idx < arr.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none" }}>
              <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#334155", marginBottom: 5 }}>
                {m.label}
              </div>
              <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.value}</div>
            </div>
          ))}
        </div>
      )}

      {/* ── Realized P/L stats strip ──────────────────────────────── */}
      {closedStats && (
        <div data-tour-id="perf-daytrades-closed-stats" style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          background: "rgba(8,16,26,0.7)",
          border: "1px solid rgba(255,255,255,0.06)",
          borderRadius: 14,
          overflow: "hidden",
        }}>
          {[
            {
              label: "Realized P/L",
              value: `${closedStats.totalRealizedPl >= 0 ? "+" : ""}${formatCurrency(closedStats.totalRealizedPl)}`,
              color: closedStats.totalRealizedPl >= 0 ? "#4ade80" : "#f87171",
            },
            { label: "Closed Trades", value: String(closedStats.count), color: "#e2e8f0" },
            { label: "Win / Loss", value: `${closedStats.winners}W / ${closedStats.losers}L`, color: "#e2e8f0" },
            {
              label: "Win Rate",
              value: closedStats.winRate == null ? "—" : `${closedStats.winRate.toFixed(0)}%`,
              color: closedStats.winRate != null && closedStats.winRate >= 50 ? "#4ade80" : "#f87171",
            },
          ].map((m, idx, arr) => (
            <div key={m.label} style={{ padding: "13px 18px", borderRight: idx < arr.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none" }}>
              <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#334155", marginBottom: 5 }}>
                {m.label}
              </div>
              <div style={{ fontSize: 15, fontWeight: 700, color: m.color }}>{m.value}</div>
            </div>
          ))}
        </div>
      )}

      {/* ── Open positions list ───────────────────────────────────── */}
      {hasOpenTrades && (
        <div data-tour-id="perf-daytrades-open-positions" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#334155", marginBottom: 16 }}>
            Positions
          </div>
          <div>
            {sortedTrades.map((pos, idx) => {
              const pl = Number(pos?.unrealizedPl) || 0;
              const plpc = Number(pos?.unrealizedPlpc);
              const isEquity = pos.assetClass && pos.assetClass !== "crypto";
              return (
                <div
                  key={pos.symbol}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 12,
                    padding: "12px 0",
                    borderBottom: idx < sortedTrades.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none",
                  }}
                >
                  <div>
                    <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                      <span style={{ fontSize: 14, fontWeight: 800, color: "#f0f6ff" }}>{pos.symbol}</span>
                      <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: isEquity ? "#4a7fa8" : "#7c6aad" }}>
                        {isEquity ? "EQ" : "CR"}
                      </span>
                    </div>
                    <div style={{ fontSize: 11, color: "#334155", marginTop: 3 }}>
                      {formatBrokerQuantity(pos.qty)} × {formatCurrency(pos.avgEntryPrice || 0)} · {formatCurrency(pos.marketValue)}
                    </div>
                  </div>
                  <div style={{ textAlign: "right", flexShrink: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: pl >= 0 ? "#4ade80" : "#f87171" }}>
                      {pl >= 0 ? "+" : ""}{formatCurrency(pl)}
                    </div>
                    <div style={{ fontSize: 11, color: pl >= 0 ? "#6ee7b7" : "#fca5a5", marginTop: 2, opacity: 0.85 }}>
                      {Number.isFinite(plpc) ? formatPerformancePercent(plpc * 100) : "—"}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ── Closed trade history ──────────────────────────────────── */}
      {closedActiveTrades.length > 0 && (
        <div data-tour-id="perf-daytrades-history" style={{ background: "rgba(8,16,26,0.7)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 16, padding: "18px 22px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#334155", marginBottom: 16 }}>
            Closed Day Trades
          </div>
          <div>
            {closedActiveTrades.slice(0, 50).map((t, idx) => {
              const pl = Number(t.pnl_value) || 0;
              const tradeIsPos = pl >= 0;
              const typeLabel = t.tradeType === "swing_trade" ? "Swing" : "Day";
              const exitDate = t.exit_time ? new Date(t.exit_time).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "2-digit" }) : "—";
              return (
                <div
                  key={t.id}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 12,
                    padding: "12px 0",
                    borderBottom: idx < Math.min(closedActiveTrades.length, 50) - 1 ? "1px solid rgba(255,255,255,0.04)" : "none",
                  }}
                >
                  <div>
                    <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                      <span style={{ fontSize: 14, fontWeight: 800, color: "#f0f6ff" }}>{t.asset}</span>
                      <span style={{ fontSize: 9, fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", padding: "2px 5px", borderRadius: 4, background: t.tradeType === "swing_trade" ? "rgba(99,102,241,0.15)" : "rgba(167,139,250,0.12)", color: t.tradeType === "swing_trade" ? "#818cf8" : "#a78bfa" }}>
                        {typeLabel}
                      </span>
                    </div>
                    <div style={{ fontSize: 11, color: "#334155", marginTop: 3 }}>
                      {formatCurrency(t.entry_price)} → {formatCurrency(t.exit_price)} · {exitDate}
                    </div>
                  </div>
                  <div style={{ textAlign: "right", flexShrink: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: tradeIsPos ? "#4ade80" : "#f87171" }}>
                      {tradeIsPos ? "+" : ""}{formatCurrency(pl)}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {hasOpenTrades && (
        <PositionPerformanceInsights
          title="Day Trades"
          scopeLabel="day trades"
          positions={sortedTrades}
          totalValue={summary.totalValue}
          totalUnrealizedPl={summary.totalUnrealizedPl}
          unrealizedPct={summary.unrealizedPct}
          onRefresh={onRefresh}
        />
      )}

      {hasClosedTrades && (
        <div data-tour-id="perf-daytrades-ai" style={{ background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14 }}>
          <div style={{ padding: "14px 18px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#7CC4FF" }}>Rayla's Day Trade Analysis</div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              {showNoNewTrades && <span style={{ fontSize: 11, color: "#334155" }}>No new trades since last run</span>}
              {canRunAiAnalysis ? (
                <button type="button" onClick={onRunAnalysis}
                  style={{ background: "rgba(124,196,255,0.1)", border: "1px solid rgba(124,196,255,0.25)", borderRadius: 8, padding: "6px 14px", color: "#7CC4FF", fontSize: 12, cursor: "pointer" }}>
                  Run AI Analysis
                </button>
              ) : null}
            </div>
          </div>
          <div style={{ padding: "16px 18px", display: "flex", flexDirection: "column", gap: 10 }}>
            {coachSummary?.strongestEdge ? (
              <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(74,222,128,0.07)", border: "1px solid rgba(74,222,128,0.15)", fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>
                <span style={{ color: "#4ade80", fontWeight: 700 }}>Strongest Edge: </span>{coachSummary.strongestEdge}
              </div>
            ) : null}
            {coachSummary?.weakestPattern ? (
              <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(248,113,113,0.07)", border: "1px solid rgba(248,113,113,0.15)", fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>
                <span style={{ color: "#f87171", fontWeight: 700 }}>Weakest Pattern: </span>{coachSummary.weakestPattern}
              </div>
            ) : null}
            {coachSummary?.nextAction ? (
              <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(124,196,255,0.06)", border: "1px solid rgba(124,196,255,0.15)", fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>
                <span style={{ color: "#7CC4FF", fontWeight: 700 }}>Next: </span>{coachSummary.nextAction}
              </div>
            ) : (
              <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)", fontSize: 13, color: "#7f8ea3", lineHeight: 1.6 }}>
                Run AI Analysis to review the closed day/swing trades in this view.
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function PerformanceDashboard({
  trades,
  performanceSourceLabel = "Live Trades",
  alternateEmptyHint = null,
  equityPoints,
  sourceLabel,
  chartRange,
  setChartRange,
  benchmarkSymbol,
  benchmarkLabel,
  onSelectBenchmark,
  benchmarkOptions,
  benchmarkPoints,
  benchmarkLoading,
  alpacaConnected,
  alpacaAccount,
  coachSummary,
  showNoNewTrades,
  onRunAnalysis,
  alpacaPositions,
  activeBrokerPositions = [],
  performanceLiveAppliedSelection,
  setPerformanceLiveAppliedSelection,
  tradeAppliedSelection,
  applyTradeSelection,
  tradePortfolioAllSymbols,
  tradeChartSymbol,
  tradeChartCurrentPrice,
  tradeChartQuote,
  tradeChartMatchingPosition,
  tradeChartAsset,
  tradeChartAssetType,
  tradeChartRange,
  setTradeChartRange,
  tradeChartMode,
  setTradeChartMode,
  tradeChartLastUpdated,
  tradeIsComparisonMode,
  tradeIsPortfolioTotalMode,
  tradePortfolioCombinedUnrealizedPl,
  tradePortfolioCombinedMarketValue,
  tradePortfolioDisplayedPositions,
  tradePortfolioChartsLoading,
  tradePortfolioCharts,
  portfolioSnapshots = [],
  portfolioSnapshotsLoading = false,
  performancePortfolioRange = "MAX",
  setPerformancePortfolioRange = () => {},
  timeZone = null,
  brokerTradeLog,
  tradePortfolioRequestedStartMs,
  tradePortfolioNowMs,
  tradeMarketChartLoading,
  tradeMarketChart,
}) {
  const isSimulationSource = performanceSourceLabel === "Live Simulation";
  const effectiveCoachSummary = coachSummary;
  const effectiveShowNoNewTrades = showNoNewTrades;
  const getOutcomeValue = useCallback((trade) => {
    if (isSimulationSource) {
      const pnl = getTradeProfitValue(trade);
      if (Number.isFinite(pnl)) return pnl;
    }
    return getTradePerformanceValue(trade);
  }, [isSimulationSource]);
  const formatOutcomeValue = useCallback((value) => {
    if (isSimulationSource) return `${value >= 0 ? "+" : ""}${formatCurrency(Math.abs(value))}`;
    return `${value >= 0 ? "+" : ""}${value.toFixed(2)}`;
  }, [isSimulationSource]);
  const canRunAiAnalysis = typeof onRunAnalysis === "function";
  const [fAsset, setFAsset] = useState("all");
  const [fSetup, setFSetup] = useState("all");
  const [fSession, setFSession] = useState("all");
  const [fDir, setFDir] = useState("all");
  const [fResult, setFResult] = useState("all");
  const [tooltip, setTooltip] = useState(null);

  const strategyTradesForFilters = useMemo(() => trades.filter(isStrategyInsightTrade), [trades]);
  const allAssets = useMemo(() => [...new Set(trades.map(t => (t.asset || "").toUpperCase()).filter(Boolean))].sort(), [trades]);
  const allSetups = useMemo(() => [...new Set(strategyTradesForFilters.map(t => t.setup).filter(Boolean))].sort(), [strategyTradesForFilters]);
  const allSessions = useMemo(() => [...new Set(trades.map(t => t.session).filter(Boolean))].sort(), [trades]);

  const ft = useMemo(() => trades
    .filter(t => fAsset === "all" || (t.asset || "").toUpperCase() === fAsset)
    .filter(t => fSetup === "all" || t.setup === fSetup)
    .filter(t => fSession === "all" || t.session === fSession)
    .filter(t => fDir === "all" || (t.direction || "").toLowerCase() === fDir)
    .filter(t => {
      if (fResult === "all") return true;
      const r = getOutcomeValue(t);
      return fResult === "win" ? r > 0 : fResult === "loss" ? r < 0 : r === 0;
    }), [trades, fAsset, fSetup, fSession, fDir, fResult, getOutcomeValue]);

  const dashboardEquityPoints = useMemo(
    () => normalizeChartSeriesToStrictAscending(
      addSingleTradeEquityBaseline(filterEquityCurvePointsByRange(buildLoggedEquityCurvePoints(ft, 0), chartRange), 0)
    ),
    [ft, chartRange]
  );

  const report = useMemo(() => buildPerformanceOutcomeReport(ft, { valueAccessor: getOutcomeValue }), [ft, getOutcomeValue]);
  const hasMixedResultUnits = Boolean(report?.hasMixedUnits);
  const strategyFilteredTrades = useMemo(() => ft.filter(isStrategyInsightTrade), [ft]);
  const strategyReport = useMemo(() => buildCoachReport(ft), [ft]);
  const strategyInsightCount = strategyFilteredTrades.length;
  const hasFilters = fAsset !== "all" || fSetup !== "all" || fSession !== "all" || fDir !== "all" || fResult !== "all";

  const sessionStats = useMemo(() => {
    const map = {};
    strategyFilteredTrades.forEach(t => {
      const k = t.session || "Untagged";
      if (!map[k]) map[k] = { trades: 0, wins: 0, totalR: 0 };
      map[k].trades++;
      map[k].totalR += getOutcomeValue(t);
      if (getOutcomeValue(t) > 0) map[k].wins++;
    });
    return Object.entries(map)
      .map(([session, s]) => ({ session, trades: s.trades, winRate: s.trades > 0 ? (s.wins / s.trades) * 100 : 0, avgR: s.trades > 0 ? s.totalR / s.trades : 0, totalR: s.totalR }))
      .sort((a, b) => b.totalR - a.totalR);
  }, [strategyFilteredTrades, getOutcomeValue]);

  const recent5 = useMemo(() => [...trades]
    .sort((a, b) => (b.entry_time ? new Date(b.entry_time).getTime() : 0) - (a.entry_time ? new Date(a.entry_time).getTime() : 0))
    .slice(0, 5), [trades]);

  const lossStreak = useMemo(() => {
    const sorted = [...trades].sort((a, b) => (b.entry_time ? new Date(b.entry_time).getTime() : 0) - (a.entry_time ? new Date(a.entry_time).getTime() : 0));
    let streak = 0;
    for (const t of sorted) {
      if (getOutcomeValue(t) < 0) streak++;
      else break;
    }
    return streak;
  }, [trades, getOutcomeValue]);

  const rStdDev = useMemo(() => {
    if (ft.length < 3) return null;
    const rs = ft
      .map(t => {
        const r = Number(t?.result_r);
        return Number.isFinite(r) ? r : null;
      })
      .filter(v => v !== null);
    if (rs.length < 3) return null;
    const mean = rs.reduce((a, b) => a + b, 0) / rs.length;
    const variance = rs.reduce((a, r) => a + (r - mean) ** 2, 0) / rs.length;
    return Math.sqrt(variance);
  }, [ft]);

  const TOOLTIP_CONTENT = {
    winrate: { title: "Win Rate", body: "Win rate is the percentage of your trades that finished as winners. Higher isn't always better — what matters is win rate in combination with how much you make vs. lose per trade." },
    avgr: { title: "Avg R / Trade", body: "Average R shows what your typical completed trade earns or loses across the trades currently included in Rayla analytics." },
    totalr: { title: "Total R", body: "Total R is the cumulative strategy result across the trades currently included in Rayla analytics." },
    pf: { title: "Profit Factor", body: "Profit Factor = total gross wins ÷ total gross losses. Above 1.0 means the system is net profitable. Below 1.0 means losses are outpacing wins in dollar terms." },
  };

  const cardBase = { background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14 };
  const diagnosisStrongestEdge = effectiveCoachSummary?.strongestEdge
    || (strategyReport?.bestCombo
      ? `${strategyReport.bestCombo.setup} on ${strategyReport.bestCombo.asset} — ${strategyReport.bestCombo.avgR.toFixed(2)} avg across ${strategyReport.bestCombo.trades} trade${strategyReport.bestCombo.trades === 1 ? "" : "s"} · ${strategyReport.bestCombo.winRate.toFixed(0)}% win rate.${strategyReport.bestCombo.trades < 3 ? " Early signal — build sample size here before scaling." : ""}`
      : null);
  const diagnosisConsistencyNote = rStdDev != null
    ? `R std deviation: ${rStdDev.toFixed(2)}. ${rStdDev < 1.2
      ? "Outcomes are fairly consistent."
      : rStdDev < 2.5
        ? "Moderate variance in R outcomes. Review whether sizing and execution are staying consistent."
        : "High variance in R outcomes. Risk sizing or execution inconsistency is likely a factor."}`
    : null;
  const weakestSetup = strategyReport?.setupStats?.length > 1 ? strategyReport.setupStats[strategyReport.setupStats.length - 1] : null;
  const fallbackDiagnosisWarning = strategyReport?.totalR < 0
    ? "The current sample is net negative. Focus on which setups or management decisions are doing the damage."
    : strategyReport?.trades >= 3 && strategyReport?.winRate < 50
      ? "The current sample is still below breakeven quality. Stay selective until one pattern is proving itself."
      : null;
  const diagnosisWarning = effectiveCoachSummary?.warning
    || report?.warnings?.[0]
    || (weakestSetup && weakestSetup.avgR < 0
      ? `${weakestSetup.setup} is your weakest setup right now at ${weakestSetup.avgR.toFixed(2)} average per trade.`
      : null)
    || fallbackDiagnosisWarning;
  const diagnosisNextAction = effectiveCoachSummary?.nextAction || report?.actions?.[0] || null;

  if (trades.length === 0) {
    return (
        <div className="emptyState">
          <div className="emptyStateTitle">
            {isSimulationSource ? "No live simulation trades to analyze yet" : "No trades to analyze yet"}
          </div>
          <div className="emptyStateCopy">
            {isSimulationSource
              ? "Close one live simulation trade and Rayla will turn it into win rate, P/L, and review context automatically."
              : <>Start with <strong style={{ color: "#7CC4FF" }}>Simulation</strong>, then log or sync the trade when you are ready. Your analytics dashboard will unlock here.</>}
          </div>
          {alternateEmptyHint ? (
          <div className="emptyStateCopy" style={{ marginTop: 2 }}>
            {alternateEmptyHint}
          </div>
        ) : null}
      </div>
    );
  }

  const winCount = report?.wins || 0;
  const lossCount = report?.losses || 0;
  const beCount = ft.filter(t => getOutcomeValue(t) === 0).length;
  const totalCount = ft.length;

  function clearFilters() {
    setFAsset("all"); setFSetup("all"); setFSession("all"); setFDir("all"); setFResult("all");
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Filter bar */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        {allAssets.length > 1 && (
          <RaylaDropdown
            value={fAsset}
            onChange={setFAsset}
            options={[{ value: "all", label: "All Assets" }, ...allAssets.map((asset) => ({ value: asset, label: asset }))]}
            width={150}
            minWidth={150}
            size="compact"
            ariaLabel="Performance asset filter"
          />
        )}
        {allSetups.length > 0 && (
          <RaylaDropdown
            value={fSetup}
            onChange={setFSetup}
            options={[{ value: "all", label: "All Setups" }, ...allSetups.map((setup) => ({ value: setup, label: setup }))]}
            width={150}
            minWidth={150}
            size="compact"
            ariaLabel="Performance setup filter"
          />
        )}
        <div style={{ display: "flex", gap: 8, flexShrink: 0 }}>
          {allSessions.length > 0 && (
            <RaylaDropdown
              value={fSession}
              onChange={setFSession}
              options={[{ value: "all", label: "All Sessions" }, ...allSessions.map((session) => ({ value: session, label: session }))]}
              width={110}
              minWidth={100}
              size="compact"
              ariaLabel="Performance session filter"
            />
          )}
          <RaylaDropdown
            value={fDir}
            onChange={setFDir}
            options={PERFORMANCE_DIRECTION_FILTER_OPTIONS}
            width={110}
            minWidth={100}
            size="compact"
            ariaLabel="Performance direction filter"
          />
          <RaylaDropdown
            value={fResult}
            onChange={setFResult}
            options={PERFORMANCE_RESULT_FILTER_OPTIONS}
            width={110}
            minWidth={100}
            size="compact"
            ariaLabel="Performance result filter"
          />
        </div>
        {hasFilters && (
          <button type="button" onClick={clearFilters}
            style={{ background: "transparent", border: "1px solid rgba(248,113,113,0.3)", borderRadius: 10, padding: "8px 12px", color: "#f87171", fontSize: 12, cursor: "pointer" }}>
            Clear
          </button>
        )}
        <div style={{ marginLeft: "auto", fontSize: 12, color: "#475569" }}>{ft.length} of {trades.length} trades</div>
      </div>

      {/* Stats grid */}
      {report ? (
        <div data-tour-id="perf-stats" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 10 }}>
          {[
            { label: "Trades", value: report.trades, sub: `${winCount}W · ${lossCount}L`, color: "#f3f7fc" },
            { label: "Win Rate", value: hasMixedResultUnits ? "Blended" : `${report.winRate.toFixed(1)}%`, sub: hasMixedResultUnits ? "strategy + broker history" : "% of winners", color: hasMixedResultUnits ? "#94a3b8" : report.winRate >= 50 ? "#4ade80" : "#f87171", tip: hasMixedResultUnits ? null : "winrate" },
            { label: isSimulationSource ? "Total P/L" : "Total R", value: hasMixedResultUnits ? "Blended" : formatOutcomeValue(report.totalR), sub: hasMixedResultUnits ? "strategy + broker history" : isSimulationSource ? "money made" : "strategy result", color: hasMixedResultUnits ? "#94a3b8" : report.totalR >= 0 ? "#4ade80" : "#f87171", tip: hasMixedResultUnits || isSimulationSource ? null : "totalr" },
            { label: isSimulationSource ? "Avg P/L / Trade" : "Avg R / Trade", value: hasMixedResultUnits ? "Blended" : formatOutcomeValue(report.avgR), sub: hasMixedResultUnits ? "strategy + broker history" : "per trade", color: hasMixedResultUnits ? "#94a3b8" : report.avgR >= 0 ? "#4ade80" : "#f87171", tip: hasMixedResultUnits || isSimulationSource ? null : "avgr" },
            { label: "Avg Win", value: hasMixedResultUnits ? "Blended" : report.avgWin > 0 ? formatOutcomeValue(report.avgWin) : "—", sub: hasMixedResultUnits ? "strategy + broker history" : "avg winner", color: hasMixedResultUnits ? "#94a3b8" : "#4ade80" },
            { label: "Avg Loss", value: hasMixedResultUnits ? "Blended" : report.avgLoss > 0 ? formatOutcomeValue(-report.avgLoss) : "—", sub: hasMixedResultUnits ? "strategy + broker history" : "avg loser", color: hasMixedResultUnits ? "#94a3b8" : "#f87171" },
            ...(report.profitFactor !== null && !hasMixedResultUnits ? [{ label: "Profit Factor", value: report.profitFactor.toFixed(2), sub: ">1.0 profitable", color: report.profitFactor >= 1 ? "#4ade80" : "#f87171", tip: "pf" }] : []),
            ...(report.setupStats.length > 0 ? [{ label: "Best Setup", value: report.setupStats[0].setup, sub: `${report.setupStats[0].avgR >= 0 ? "+" : ""}${report.setupStats[0].avgR.toFixed(2)} avg`, color: "#7CC4FF" }] : []),
            ...(report.setupStats.length > 1 ? [{ label: "Weakest Setup", value: report.setupStats[report.setupStats.length - 1].setup, sub: `${report.setupStats[report.setupStats.length - 1].avgR >= 0 ? "+" : ""}${report.setupStats[report.setupStats.length - 1].avgR.toFixed(2)} avg`, color: "#f87171" }] : []),
          ].map(item => (
            <div key={item.label}
              onClick={item.tip ? () => setTooltip(item.tip) : undefined}
              style={{ ...cardBase, padding: "14px 16px", cursor: item.tip ? "pointer" : "default" }}>
              <div style={{ fontSize: 11, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: 6, display: "flex", alignItems: "center", gap: 4 }}>
                {item.label}
                {item.tip && <span style={{ fontSize: 10, color: "#334155" }}>ⓘ</span>}
              </div>
              <div style={{ fontSize: 18, fontWeight: 700, color: item.color, marginBottom: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{item.value}</div>
              <div style={{ fontSize: 11, color: "#475569" }}>{item.sub}</div>
            </div>
          ))}
        </div>
      ) : (
        <div className="emptyState emptyStateCompact">
          <div className="emptyStateTitle">No trades match these filters</div>
          <div className="emptyStateCopy">The current dataset is still intact. Clear filters to bring the trades back into view.</div>
          <button type="button" onClick={clearFilters}
            style={{ background: "transparent", border: "none", color: "#7CC4FF", fontSize: 14, cursor: "pointer", textDecoration: "underline", padding: 0 }}>
            Clear filters
          </button>
        </div>
      )}

      {/* Tooltip modal */}
      {tooltip && TOOLTIP_CONTENT[tooltip] && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 9999 }}
          onClick={() => setTooltip(null)}>
          <div className="card" style={{ maxWidth: 380 }} onClick={e => e.stopPropagation()}>
            <div className="cardHeader"><h2>{TOOLTIP_CONTENT[tooltip].title}</h2></div>
            <div className="cardBody" style={{ lineHeight: 1.7 }}>{TOOLTIP_CONTENT[tooltip].body}</div>
            <button className="ghostButton" onClick={() => setTooltip(null)} style={{ marginTop: 10 }}>Got it</button>
          </div>
        </div>
      )}

      {!isSimulationSource ? (
        <div data-tour-id="perf-equity" style={{ display: "contents" }}>
          <EquityCurveCard
            equityPoints={dashboardEquityPoints}
            sourceLabel={sourceLabel}
            chartRange={chartRange}
            setChartRange={setChartRange}
            benchmarkSymbol={benchmarkSymbol}
            benchmarkLabel={benchmarkLabel}
            onSelectBenchmark={onSelectBenchmark}
            benchmarkOptions={benchmarkOptions}
            benchmarkPoints={benchmarkPoints}
            benchmarkLoading={benchmarkLoading}
            alpacaConnected={alpacaConnected}
            timeZone={timeZone}
          />
        </div>
      ) : null}

      {!isSimulationSource ? (
        <PortfolioTrendCard
          positions={activeBrokerPositions}
          alpacaAccount={alpacaAccount}
          tradePortfolioCharts={tradePortfolioCharts}
          tradePortfolioChartsLoading={tradePortfolioChartsLoading}
          portfolioSnapshots={portfolioSnapshots}
          portfolioSnapshotsLoading={portfolioSnapshotsLoading}
          snapshotView="active"
          portfolioRange={performancePortfolioRange}
          setPortfolioRange={setPerformancePortfolioRange}
          title="Open Day Trade Positions"
          subtitle="Open day/swing trades only. The equity curve above stays tied to closed logged trades."
          emptyMessage="Performance history grows automatically as Rayla collects broker snapshots."
          statusLabel={alpacaConnected ? "Open" : null}
          useAccountValue={false}
          timeZone={timeZone}
          preferPaper={preferPaper}
        />
      ) : null}

      {trades.length > 0 ? (
        <PerformanceLiveChartCard
          alpacaPositions={alpacaPositions}
          performanceLiveAppliedSelection={performanceLiveAppliedSelection}
          setPerformanceLiveAppliedSelection={setPerformanceLiveAppliedSelection}
          tradePortfolioAllSymbols={tradePortfolioAllSymbols}
          tradeChartSymbol={tradeChartSymbol}
          tradeChartCurrentPrice={tradeChartCurrentPrice}
          tradeChartQuote={tradeChartQuote}
          tradeChartMatchingPosition={tradeChartMatchingPosition}
          tradeChartAsset={tradeChartAsset}
          tradeChartAssetType={tradeChartAssetType}
          tradeChartRange={tradeChartRange}
          setTradeChartRange={setTradeChartRange}
          tradeChartMode={tradeChartMode}
          setTradeChartMode={setTradeChartMode}
          tradeChartLastUpdated={tradeChartLastUpdated}
          tradeIsComparisonMode={tradeIsComparisonMode}
          tradeIsPortfolioTotalMode={tradeIsPortfolioTotalMode}
          tradePortfolioCombinedUnrealizedPl={tradePortfolioCombinedUnrealizedPl}
          tradePortfolioCombinedMarketValue={tradePortfolioCombinedMarketValue}
          tradePortfolioDisplayedPositions={tradePortfolioDisplayedPositions}
          tradePortfolioChartsLoading={tradePortfolioChartsLoading}
          tradePortfolioCharts={tradePortfolioCharts}
          brokerTradeLog={brokerTradeLog}
          trades={trades}
          tradePortfolioRequestedStartMs={tradePortfolioRequestedStartMs}
          tradePortfolioNowMs={tradePortfolioNowMs}
          tradeMarketChartLoading={tradeMarketChartLoading}
          tradeMarketChart={tradeMarketChart}
        />
      ) : null}

      {/* Trade outcome overview */}
      {report && totalCount > 0 && (
        <div data-tour-id="perf-trade-outcomes" style={{ ...cardBase, padding: "16px 20px" }}>
          <div style={{ fontSize: 11, fontWeight: 600, color: "#7f8ea3", textTransform: "uppercase", letterSpacing: "0.6px", marginBottom: 14 }}>Trade Outcomes</div>
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap" }}>
            {[
              { label: "Winners", count: winCount, color: "#4ade80", detail: report.avgWin > 0 ? `${formatOutcomeValue(report.avgWin)} avg` : "" },
              { label: "Losers", count: lossCount, color: "#f87171", detail: report.avgLoss > 0 ? `${formatOutcomeValue(-report.avgLoss)} avg` : "" },
              ...(beCount > 0 ? [{ label: "Breakeven", count: beCount, color: "#64748b", detail: "" }] : []),
            ].map(item => (
              <div key={item.label} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 8, height: 8, borderRadius: "50%", background: item.color, flexShrink: 0 }} />
                <span style={{ fontSize: 13, fontWeight: 600, color: item.color }}>{item.count}</span>
                <span style={{ fontSize: 12, color: "#64748b" }}>{item.label} · {totalCount ? (item.count / totalCount * 100).toFixed(0) : 0}%</span>
                {item.detail && <span style={{ fontSize: 12, color: "#475569" }}>· {item.detail}</span>}
              </div>
            ))}
          </div>
          {recent5.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 14, paddingTop: 14, borderTop: "1px solid rgba(255,255,255,0.05)" }}>
              <span style={{ fontSize: 11, color: "#475569", textTransform: "uppercase", letterSpacing: "0.4px" }}>Recent form</span>
              <div style={{ display: "flex", gap: 5 }}>
                {recent5.map((t, i) => {
                  const r = getOutcomeValue(t);
                  return (
                    <div key={i}
                      title={`${(t.asset || "").toUpperCase()} · ${formatOutcomeValue(r)}`}
                      style={{ width: 11, height: 11, borderRadius: "50%", background: r > 0 ? "#4ade80" : r < 0 ? "#f87171" : "#64748b" }} />
                  );
                })}
              </div>
              {lossStreak >= 3 && (
                <span style={{ fontSize: 11, color: "#fbbf24", background: "rgba(251,191,36,0.09)", border: "1px solid rgba(251,191,36,0.2)", borderRadius: 6, padding: "1px 8px" }}>
                  {lossStreak} consecutive losses
                </span>
              )}
            </div>
          )}
        </div>
      )}

      {/* Breakdown tables: Setup | Asset | Session */}
      {report && (report.setupStats.length > 0 || report.assetStats.length > 0 || sessionStats.length > 0) && (
        <div data-tour-id="perf-breakdown" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 14, alignItems: "start" }}>
          <PerfBreakdownTable
            title="By Setup"
            rows={report.setupStats.map(s => ({ name: s.setup, trades: s.trades, winRate: s.winRate, avgR: s.avgR, totalR: s.totalR }))}
            nameColor="#7CC4FF"
          />
          <PerfBreakdownTable
            title="By Asset"
            rows={report.assetStats.map(a => ({ name: a.asset, trades: a.trades, winRate: a.winRate, avgR: a.avgR, totalR: a.totalR }))}
            nameColor="#e2e8f0"
            hideOutcomeValues={hasMixedResultUnits}
          />
          {sessionStats.length > 0 && (
            <PerfBreakdownTable
              title="By Session"
              rows={sessionStats.map(s => ({ name: s.session, trades: s.trades, winRate: s.winRate, avgR: s.avgR, totalR: s.totalR }))}
              nameColor="#94a3b8"
              hideOutcomeValues={hasMixedResultUnits}
            />
          )}
        </div>
      )}

      {/* Strongest patterns (Asset + Setup combos) */}
      {report && report.comboStats.length > 0 && (
        <div style={cardBase}>
          <div style={{ padding: "11px 16px", borderBottom: "1px solid rgba(255,255,255,0.05)", fontSize: 11, fontWeight: 600, color: "#7f8ea3", textTransform: "uppercase", letterSpacing: "0.6px" }}>
            Strongest Patterns — Asset + Setup
          </div>
          <div style={{ padding: "4px 0" }}>
            {report.comboStats.slice(0, 5).map((c, i) => (
              <div key={i} style={{ padding: "10px 16px", borderBottom: i < Math.min(report.comboStats.length, 5) - 1 ? "1px solid rgba(255,255,255,0.04)" : "none", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                <div style={{ flex: "1 1 160px" }}>
                  <span style={{ fontSize: 13, fontWeight: 600, color: "#f3f7fc" }}>{c.asset}</span>
                  <span style={{ fontSize: 12, color: "#475569" }}> · </span>
                  <span style={{ fontSize: 12, color: "#7CC4FF" }}>{c.setup}</span>
                </div>
                <span style={{ fontSize: 11, color: "#64748b", whiteSpace: "nowrap" }}>{c.trades} trades · {c.winRate.toFixed(0)}% win</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: c.avgR >= 0 ? "#4ade80" : "#f87171", whiteSpace: "nowrap" }}>{c.avgR >= 0 ? "+" : ""}{c.avgR.toFixed(2)} avg</span>
                <span style={{ fontSize: 12, color: c.totalR >= 0 ? "#4ade80" : "#f87171", whiteSpace: "nowrap" }}>{c.totalR >= 0 ? "+" : ""}{c.totalR.toFixed(2)} total</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Rayla Diagnosis */}
      {trades.length > 0 && (
        <div data-tour-id="perf-ai" style={cardBase}>
          <div style={{ padding: "14px 18px", borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#7CC4FF" }}>Rayla&apos;s Diagnosis</div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              {effectiveShowNoNewTrades && <span style={{ fontSize: 11, color: "#334155" }}>No new trades since last run</span>}
              {canRunAiAnalysis ? (
                <button type="button" onClick={onRunAnalysis}
                  style={{ background: "rgba(124,196,255,0.1)", border: "1px solid rgba(124,196,255,0.25)", borderRadius: 8, padding: "6px 14px", color: "#7CC4FF", fontSize: 12, cursor: "pointer" }}>
                  Run AI Analysis
                </button>
              ) : null}
              {(() => {
                const disabled = typeof onRunAnalysis !== "function" || !trades.length;
                return (
                  <button
                    type="button"
                    onClick={() => { if (!disabled) onRunAnalysis(); }}
                    disabled={disabled}
                    style={{
                      background: disabled ? "rgba(124,196,255,0.04)" : "rgba(124,196,255,0.1)",
                      border: "1px solid rgba(124,196,255,0.25)",
                      borderRadius: 8,
                      padding: "6px 14px",
                      color: "#7CC4FF",
                      fontSize: 12,
                      cursor: disabled ? "not-allowed" : "pointer",
                      opacity: disabled ? 0.5 : 1,
                    }}
                  >
                    Refresh
                  </button>
                );
              })()}
            </div>
          </div>
          <div style={{ padding: "16px 18px", display: "flex", flexDirection: "column", gap: 10 }}>
            {strategyInsightCount > 0 && strategyInsightCount < 20 && (
              <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(124,196,255,0.06)", border: "1px solid rgba(124,196,255,0.15)", fontSize: 13, color: "#7CC4FF", lineHeight: 1.6 }}>
                {strategyInsightCount < 5
                  ? `Only ${strategyInsightCount} strategy trade${strategyInsightCount === 1 ? "" : "s"} logged — keep logging manual or screenshot trades to unlock meaningful patterns.`
                  : `${strategyInsightCount} strategy trades logged — patterns are forming. Aim for 30+ before drawing firm conclusions from setup stats.`}
              </div>
            )}
            {diagnosisStrongestEdge && (
              <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(74,222,128,0.07)", border: "1px solid rgba(74,222,128,0.15)" }}>
                <div style={{ fontSize: 11, color: "#4ade80", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: 5, fontWeight: 600 }}>Strongest Edge</div>
                <div style={{ fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>
                  {diagnosisStrongestEdge}
                </div>
              </div>
            )}
            {diagnosisConsistencyNote && (
              <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)", fontSize: 13, color: "#e2e8f0", lineHeight: 1.6 }}>
                <span style={{ color: "#7f8ea3", fontWeight: 600 }}>Consistency · </span>
                {diagnosisConsistencyNote}
              </div>
            )}
            {diagnosisWarning && (
              <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(251,191,36,0.07)", border: "1px solid rgba(251,191,36,0.18)", fontSize: 13, color: "#fbbf24", lineHeight: 1.6 }}>
                ⚠ {diagnosisWarning}
              </div>
            )}
            {diagnosisNextAction && (
              <div style={{ padding: "12px 14px", borderRadius: 10, background: "rgba(124,196,255,0.06)", border: "1px solid rgba(124,196,255,0.15)" }}>
                <div style={{ fontSize: 11, color: "#7CC4FF", textTransform: "uppercase", letterSpacing: "0.5px", marginBottom: 8, fontWeight: 600 }}>Next Action</div>
                <div style={{ display: "flex", gap: 8, fontSize: 13, color: "#e2e8f0", lineHeight: 1.5 }}>
                  <span style={{ color: "#7CC4FF", fontWeight: 700, flexShrink: 0 }}>1.</span>
                  <span>{diagnosisNextAction}</span>
                </div>
              </div>
            )}
            {!diagnosisStrongestEdge && !diagnosisConsistencyNote && !diagnosisWarning && !diagnosisNextAction && (
              <div style={{ padding: "11px 14px", borderRadius: 10, background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)", fontSize: 13, color: "#7f8ea3", lineHeight: 1.6 }}>
                {strategyInsightCount === 0
                  ? "Strategy diagnosis uses manual, screenshot, and simulation trades with R results. Broker imports stay visible in equity and history."
                  : `Run AI Analysis to snapshot the current ${isSimulationSource ? "live simulation" : "strategy trade"} dataset, or keep logging trades until the patterns are more distinct.`}
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

function AICoachTab({ trades, onRunAnalysis, showNoNewTrades, coachSummary, hideOverall = false }) {
  const report = useMemo(() => buildCoachReport(trades), [trades]);

  if (!report) {
    return (
      <div className="card">
        <div className="emptyState">
          <div className="emptyStateTitle">No strategy trades to coach yet</div>
          <div className="emptyStateCopy">Log a manual or screenshot trade with a result and Rayla will turn the sample into focused strategy notes.</div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div className="card" style={{ borderColor: "rgba(124,196,255,0.2)" }}>
        <div className="cardHeader"><h2>Coach Insights</h2></div>
        <div className="cardBody">
          <div style={{ fontSize: 14, color: "#e2e8f0", lineHeight: 1.7 }}>
            {`Win Rate: ${report.winRate.toFixed(1)}% · Avg R: ${report.avgR >= 0 ? "+" : ""}${report.avgR.toFixed(2)} · Trades: ${report.trades}`}
          </div>
          {report.bestCombo && (
            <div style={{ marginTop: 10, fontSize: 14, color: "#e2e8f0", lineHeight: 1.7 }}>
              {`Your strongest edge is ${report.bestCombo.setup} on ${report.bestCombo.asset} — ${report.bestCombo.avgR.toFixed(2)} avg · ${report.bestCombo.winRate.toFixed(0)}% win rate across ${report.bestCombo.trades} trades.${report.bestCombo.trades < 3 ? " (early edge forming — low sample size)" : ""}`}
            </div>
          )}
          {report.warnings.length > 0 && (
            <div style={{ marginTop: 10, fontSize: 14, color: "#fbbf24", lineHeight: 1.7 }}>{report.warnings[0]}</div>
          )}
          {report.actions.length > 0 && (
            <div style={{ marginTop: 10, fontSize: 14, color: "#7CC4FF", lineHeight: 1.7 }}>{`Next step: ${report.actions[0]}`}</div>
          )}
          <button className="ghostButton" type="button" onClick={onRunAnalysis} style={{ marginTop: 12 }}>
            Refresh Analysis
          </button>
          {showNoNewTrades && (
            <div style={{ marginTop: 8, padding: "10px 12px", borderRadius: 10, background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.12)", fontSize: 13, color: "#7f8ea3" }}>
              No new trades since last analysis
            </div>
          )}
          {coachSummary && (
            <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 8 }}>
              <div style={{ fontSize: 10, color: "#7f8ea3", letterSpacing: "1px", textTransform: "uppercase" }}>Last run · {coachSummary.generatedAt}</div>
              {coachSummary.strongestEdge && (
                <div style={{ background: "rgba(74,222,128,0.07)", border: "1px solid rgba(74,222,128,0.15)", borderRadius: 10, padding: "10px 12px", fontSize: 13, color: "#4ade80" }}>
                  <strong>Strongest Edge:</strong> {coachSummary.strongestEdge}
                </div>
              )}
              {coachSummary.weakestPattern && (
                <div style={{ background: "rgba(248,113,113,0.07)", border: "1px solid rgba(248,113,113,0.15)", borderRadius: 10, padding: "10px 12px", fontSize: 13, color: "#f87171" }}>
                  <strong>Weakest Pattern:</strong> {coachSummary.weakestPattern}
                </div>
              )}
              {coachSummary.warning && (
                <div style={{ background: "rgba(251,191,36,0.07)", border: "1px solid rgba(251,191,36,0.2)", borderRadius: 10, padding: "10px 12px", fontSize: 13, color: "#fbbf24" }}>
                  ⚠ {coachSummary.warning}
                </div>
              )}
              {coachSummary.nextAction && (
                <div style={{ background: "rgba(124,196,255,0.07)", border: "1px solid rgba(124,196,255,0.15)", borderRadius: 10, padding: "10px 12px", fontSize: 13, color: "#7CC4FF" }}>
                  <strong>Next:</strong> {coachSummary.nextAction}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {!hideOverall && (
      <div className="card">
        <div className="cardHeader"><h2>Strategy Performance</h2></div>
        <div className="cardBody">
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(100px, 1fr))", gap: 12 }}>
            {[
              { label: "Trades", value: report.trades },
              { label: "Win Rate", value: `${report.winRate.toFixed(1)}%`, tone: report.winRate >= 50 ? "positive" : "negative" },
              { label: "Avg R", value: `${report.avgR >= 0 ? "+" : ""}${report.avgR.toFixed(2)}`, tone: report.avgR >= 0 ? "positive" : "negative" },
              { label: "Total R", value: `${report.totalR >= 0 ? "+" : ""}${report.totalR.toFixed(2)}`, tone: report.totalR >= 0 ? "positive" : "negative" },
              { label: "Avg Win", value: `+${report.avgWin.toFixed(2)}R`, tone: "positive" },
              { label: "Avg Loss", value: `-${report.avgLoss.toFixed(2)}R`, tone: "negative" },
              ...(report.profitFactor !== null ? [{ label: "Profit Factor", value: report.profitFactor.toFixed(2), tone: report.profitFactor >= 1 ? "positive" : "negative" }] : []),
            ].map(item => (
              <div key={item.label} style={{ background: "rgba(255,255,255,0.03)", borderRadius: 12, padding: "12px 14px" }}>
                <div style={{ fontSize: 11, color: "#7f8ea3", marginBottom: 4 }}>{item.label}</div>
                <div style={{ fontSize: 18, fontWeight: 700, color: item.tone === "positive" ? "#4ade80" : item.tone === "negative" ? "#f87171" : "#e2e8f0" }}>{item.value}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
      )}

      <div className="card">
        <div className="cardHeader"><h2>Edge Analysis</h2></div>
        <div className="cardBody">
          {report.comboStats.length === 0 ? (
            <div style={{ fontSize: 13, color: "#7f8ea3" }}>Need at least 2 trades in the same setup to identify an edge.</div>
          ) : (
            <>
              <CoachSection label="Strongest Edge" accent="#4ade80">
                {report.comboStats.slice(0, 3).map((c, i) => (
                  <CoachRow key={i} left={`${c.asset} · ${c.setup}`} sub={`${c.trades} trades · ${c.winRate.toFixed(0)}% win rate`} right={`${c.avgR >= 0 ? "+" : ""}${c.avgR.toFixed(2)} avg`} tone="positive" />
                ))}
              </CoachSection>
              {report.comboStats.length > 1 && (
                <CoachSection label="Weakest Edge" accent="#f87171">
                  {report.comboStats.slice(-Math.min(2, report.comboStats.length)).reverse().map((c, i) => (
                    <CoachRow key={i} left={`${c.asset} · ${c.setup}`} sub={`${c.trades} trades · ${c.winRate.toFixed(0)}% win rate`} right={`${c.avgR >= 0 ? "+" : ""}${c.avgR.toFixed(2)} avg`} tone={c.avgR < 0 ? "negative" : "neutral"} />
                  ))}
                </CoachSection>
              )}
            </>
          )}
        </div>
      </div>

      {report.setupStats.length > 0 && (
        <div className="card">
          <div className="cardHeader"><h2>Setup Insights</h2></div>
          <div className="cardBody">
            {report.setupStats.map((s, i) => (
              <CoachRow key={i} left={s.setup} sub={`${s.trades} trades · ${s.winRate.toFixed(0)}% win rate`} right={`${s.avgR >= 0 ? "+" : ""}${s.avgR.toFixed(2)} avg`} tone={s.avgR > 0 ? "positive" : s.avgR < 0 ? "negative" : "neutral"} />
            ))}
          </div>
        </div>
      )}

      {report.assetStats.length > 0 && (
        <div className="card">
          <div className="cardHeader"><h2>Asset Insights</h2></div>
          <div className="cardBody">
            {report.assetStats.map((a, i) => (
              <CoachRow key={i} left={a.asset} sub={`${a.trades} trades · ${a.winRate.toFixed(0)}% win rate`} right={`${a.avgR >= 0 ? "+" : ""}${a.avgR.toFixed(2)} avg`} tone={a.avgR > 0 ? "positive" : a.avgR < 0 ? "negative" : "neutral"} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function Card({ title, children, className = "" }) {
  return (
    <section className={`card ${className}`}>
      <div className="cardHeader"><h2>{title}</h2></div>
      <div className="cardBody">{children}</div>
    </section>
  );
}

class PerformanceRenderBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { error: null, componentStack: "" };
  }

  static getDerivedStateFromError(error) {
    return { error };
  }

  componentDidCatch(error, info) {
    console.error("Performance page render error:", error, info);
    this.setState({ componentStack: info?.componentStack || "" });
  }

  componentDidUpdate(prevProps) {
    if (prevProps.resetKey !== this.props.resetKey && this.state.error) {
      this.setState({ error: null, componentStack: "" });
    }
  }

  render() {
  if (this.state.error) {
      return (
        <div style={{ background: "rgba(18,26,38,0.86)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: 14, padding: 24, color: "#94a3b8", display: "flex", flexDirection: "column", gap: 10 }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#f3f7fc" }}>Performance is temporarily unavailable.</div>
          <div style={{ fontSize: 13, color: "#cbd5e1", lineHeight: 1.6 }}>
            Switch sources or refresh the page. Your trades are not changed by this display issue.
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

function formatNumber(value, digits = 2) {
  return new Intl.NumberFormat("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
}

function formatCompactPrice(value) {
  if (value == null || Number.isNaN(value)) return "--";
  return formatNumber(value, 2);
}

function formatCurrency(value) {
  if (!Number.isFinite(Number(value))) return "--";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2,
  }).format(Number(value));
}

function formatCompactCurrencyAxis(value, span = 0) {
  if (!Number.isFinite(Number(value))) return "--";
  const numericValue = Number(value);
  const absolute = Math.abs(numericValue);
  if (span <= 25) return formatCurrency(numericValue);
  if (span <= 250) return `${numericValue < 0 ? "-" : ""}$${Math.round(absolute).toLocaleString()}`;
  if (absolute >= 1_000_000) return `${numericValue < 0 ? "-" : ""}$${(absolute / 1_000_000).toFixed(1)}M`;
  if (absolute >= 1_000) return `${numericValue < 0 ? "-" : ""}$${(absolute / 1_000).toFixed(1)}k`;
  return `${numericValue < 0 ? "-" : ""}$${Math.round(absolute).toLocaleString()}`;
}

function formatPctChange(value) {
  if (value == null || Number.isNaN(value)) return "--";
  const sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(2)}%`;
}

function formatPerformancePercent(value) {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) return "—";
  const sign = numericValue >= 0 ? "+" : "";
  const absolute = Math.abs(numericValue);
  const decimals = absolute > 0 && absolute < 0.01 ? 3 : 2;
  return `${sign}${numericValue.toFixed(decimals)}%`;
}

function getSvgZoomFactor(data, zoomLevel = "normal") {
  const baseFactor =
    data.length <= 30 ? 0.22 :
    data.length <= 60 ? 0.28 :
    data.length <= 120 ? 0.36 :
    0.44;

  if (zoomLevel === "wide") return baseFactor * 1.45;
  if (zoomLevel === "close") return baseFactor * 0.75;
  return baseFactor;
}

function buildSvgLinePoints(
  data,
  zoomLevel = "normal",
  slotCount = data.length,
  xStart = 14,
  xEnd = 100,
  xRatios = null
) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const zoomFactor = getSvgZoomFactor(data, zoomLevel);

  const paddedMax = max + range * zoomFactor;
  const paddedMin = min - range * zoomFactor;
  const xDivisor = Math.max(1, (slotCount || data.length) - 1);
  const xSpan = xEnd - xStart;

  return data.map((value, index) => {
    const xRatio = Array.isArray(xRatios) && xRatios[index] != null
      ? xRatios[index]
      : index / xDivisor;
    const x = xStart + xRatio * xSpan;
    const y = 88 - ((value - paddedMin) / (paddedMax - paddedMin || 1)) * 68;
    return `${x},${y}`;
  }).join(" ");
}

function buildSvgStepLinePoints(
  data,
  zoomLevel = "normal",
  slotCount = data.length,
  xStart = 14,
  xEnd = 100,
  xRatios = null
) {
  if (!Array.isArray(data) || data.length === 0) return "";
  if (data.length === 1) {
    const point = buildSvgPointCoords(data, 0, zoomLevel, slotCount, xStart, xEnd, xRatios);
    return `${point.x},${point.y}`;
  }

  const points = [];
  for (let index = 0; index < data.length; index += 1) {
    const current = buildSvgPointCoords(data, index, zoomLevel, slotCount, xStart, xEnd, xRatios);
    if (index === 0) {
      points.push(`${current.x},${current.y}`);
      continue;
    }
    const previous = buildSvgPointCoords(data, index - 1, zoomLevel, slotCount, xStart, xEnd, xRatios);
    points.push(`${current.x},${previous.y}`);
    points.push(`${current.x},${current.y}`);
  }

  return points.join(" ");
}

function buildSvgPointCoords(
  data,
  index,
  zoomLevel = "normal",
  slotCount = data.length,
  xStart = 14,
  xEnd = 100,
  xRatios = null
) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const zoomFactor = getSvgZoomFactor(data, zoomLevel);
  const paddedMax = max + range * zoomFactor;
  const paddedMin = min - range * zoomFactor;
  const safeIndex = Math.max(0, Math.min(index, data.length - 1));
  const value = data[safeIndex];
  const xDivisor = Math.max(1, (slotCount || data.length) - 1);
  const xSpan = xEnd - xStart;
  const xRatio = Array.isArray(xRatios) && xRatios[safeIndex] != null
    ? xRatios[safeIndex]
    : safeIndex / xDivisor;

  return {
    x: xStart + xRatio * xSpan,
    y: 88 - ((value - paddedMin) / (paddedMax - paddedMin || 1)) * 68,
  };
}

function getScenarioAnchorY(scenarioType) {
  if (scenarioType === "uptrend") return 74;
  if (scenarioType === "downtrend") return 26;
  return 50;
}

function clampScenarioChartY(value) {
  return Math.max(10, Math.min(90, value));
}

function buildSvgValueY(data, value, zoomLevel = "normal") {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const zoomFactor = getSvgZoomFactor(data, zoomLevel);
  const paddedMax = max + range * zoomFactor;
  const paddedMin = min - range * zoomFactor;
  return 88 - ((value - paddedMin) / (paddedMax - paddedMin || 1)) * 68;
}

function buildSvgPriceScale(data, steps = 6, zoomLevel = "normal") {
  if (!Array.isArray(data) || data.length < 2) return [];
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const zoomFactor = getSvgZoomFactor(data, zoomLevel);
  const paddedMax = max + range * zoomFactor;
  const paddedMin = min - range * zoomFactor;

  return Array.from({ length: steps }, (_, index) => {
    const ratio = index / (steps - 1 || 1);
    const y = 14 + (72 * ratio);
    const value = paddedMax - ((paddedMax - paddedMin) * ratio);
    return { y, label: formatCompactCurrencyAxis(value, range) };
  });
}

function parseTradeTimeMs(trade) {
  const candidates = [
    trade?.exit_time,
    trade?.closed_at,
    trade?.filled_at,
    trade?.entry_time,
  ];
  for (const candidate of candidates) {
    const value = Date.parse(String(candidate || ""));
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function resolveEquityTradeTimestamp(trade) {
  const candidates = [
    ["exit_time", trade?.exit_time],
    ["closed_at", trade?.closed_at],
    ["filled_at", trade?.filled_at],
    ["entry_time", trade?.entry_time],
  ];

  for (const [field, candidate] of candidates) {
    const value = Date.parse(String(candidate || ""));
    if (Number.isFinite(value)) {
      return { timeMs: value, field };
    }
  }

  return { timeMs: null, field: null };
}

function parseTradeEntryTimeMs(trade) {
  const candidates = [
    trade?.entry_time,
    trade?.created_at,
    trade?.updated_at,
  ];
  for (const candidate of candidates) {
    const value = Date.parse(String(candidate || ""));
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function calculateTradeDollarPnl(trade) {
  const explicitPnl = Number(trade?.pnl_value);
  if (Number.isFinite(explicitPnl)) return explicitPnl;
  const explicitPnlDollars = Number(trade?.pnl_dollars);
  if (Number.isFinite(explicitPnlDollars)) return explicitPnlDollars;

  const entryPrice = Number(trade?.entry_price);
  const exitPrice = Number(trade?.exit_price);
  const entrySize = Number(trade?.entry_size);
  const direction = String(trade?.direction || "long").trim().toLowerCase();

  if (!Number.isFinite(entryPrice) || entryPrice <= 0) return null;
  if (!Number.isFinite(exitPrice) || exitPrice <= 0) return null;
  if (!Number.isFinite(entrySize) || entrySize <= 0) return null;

  const pctMove = direction === "short"
    ? (entryPrice - exitPrice) / entryPrice
    : (exitPrice - entryPrice) / entryPrice;

  if (!Number.isFinite(pctMove)) return null;
  return entrySize * pctMove;
}

function buildUsableClosedTradesForEquity(trades) {
  return [...(Array.isArray(trades) ? trades : [])]
    .map((trade, originalIndex) => {
      const timestamp = resolveEquityTradeTimestamp(trade);
      const entryTimeMs = parseTradeEntryTimeMs(trade);
      const pnl = calculateTradeDollarPnl(trade);
      if (!Number.isFinite(timestamp.timeMs) || !Number.isFinite(pnl)) return null;
      return {
        trade,
        timeMs: timestamp.timeMs,
        timestampField: timestamp.field,
        entryTimeMs,
        pnl,
        originalIndex,
      };
    })
    .filter(Boolean)
    .sort((a, b) => {
      if (a.timeMs !== b.timeMs) return a.timeMs - b.timeMs;
      const safeEntryA = Number.isFinite(a.entryTimeMs) ? a.entryTimeMs : a.timeMs;
      const safeEntryB = Number.isFinite(b.entryTimeMs) ? b.entryTimeMs : b.timeMs;
      if (safeEntryA !== safeEntryB) return safeEntryA - safeEntryB;
      return a.originalIndex - b.originalIndex;
    });
}

function buildLoggedEquityCurvePoints(trades, startingEquity = 10000) {
  const sortedTrades = buildUsableClosedTradesForEquity(trades);

  if (!sortedTrades.length) return [];

  let equity = Number(startingEquity);
  return sortedTrades.map((item) => {
    equity += item.pnl;
    const source = item.trade?.source || (item.trade?.isBrokerTrade ? "broker" : "manual");
    return {
      time: new Date(item.timeMs).toISOString(),
      timeMs: item.timeMs,
      value: equity,
      equity,
      changeFromStart: equity - Number(startingEquity),
      tradeId: item.trade?.id || null,
      tradeIds: item.trade?.id ? [item.trade.id] : [],
      source,
      pnl: item.pnl,
      timestampField: item.timestampField,
      tradeCount: 1,
      trade: item.trade || null,
    };
  });
}

function addSingleTradeEquityBaseline(points, startingEquity = 10000) {
  const normalizedPoints = Array.isArray(points) ? points.filter(Boolean) : [];
  if (normalizedPoints.length !== 1) return normalizedPoints;

  const point = normalizedPoints[0];
  const pointTimeMs = Number.isFinite(Number(point?.timeMs))
    ? Number(point.timeMs)
    : Date.parse(String(point?.time || ""));
  if (!Number.isFinite(pointTimeMs)) return normalizedPoints;

  const baselineTimeMs = pointTimeMs - 1000;
  return [
    {
      time: new Date(baselineTimeMs).toISOString(),
      timeMs: baselineTimeMs,
      value: Number(startingEquity),
      equity: Number(startingEquity),
      changeFromStart: 0,
      tradeId: null,
      tradeIds: [],
      source: "baseline",
      pnl: 0,
      timestampField: "baseline",
      tradeCount: 0,
      trade: null,
      isDisplayBaseline: true,
    },
    point,
  ];
}

function normalizeChartSeriesToStrictAscending(points) {
  const normalizedPoints = Array.isArray(points) ? points : [];
  if (!normalizedPoints.length) return [];

  const sorted = [...normalizedPoints]
    .map((point, index) => {
      const parsedTimeMs = Number.isFinite(Number(point?.timeMs))
        ? Number(point.timeMs)
        : Date.parse(String(point?.time || ""));
      return {
        point,
        index,
        timeMs: Number.isFinite(parsedTimeMs) ? parsedTimeMs : null,
      };
    })
    .filter((entry) => entry.timeMs != null)
    .sort((a, b) => {
      if (a.timeMs !== b.timeMs) return a.timeMs - b.timeMs;
      return a.index - b.index;
    });

  let previousSecond = null;
  return sorted.map(({ point, timeMs }) => {
    let nextSecond = Math.floor(timeMs / 1000);
    if (previousSecond != null && nextSecond <= previousSecond) {
      nextSecond = previousSecond + 1;
    }
    previousSecond = nextSecond;
    const nextTimeMs = nextSecond * 1000;
    return {
      ...point,
      timeMs: nextTimeMs,
      time: new Date(nextTimeMs).toISOString(),
    };
  });
}

function inferBenchmarkRangeFromEquityPoints(points) {
  if (!Array.isArray(points) || points.length < 2) return "1M";
  const first = points[0]?.timeMs || 0;
  const last = points[points.length - 1]?.timeMs || first;
  const spanMs = Math.max(0, last - first);
  const dayMs = 24 * 60 * 60 * 1000;
  if (spanMs <= dayMs) return "1D";
  if (spanMs <= 7 * dayMs) return "1W";
  if (spanMs <= 30 * dayMs) return "1M";
  if (spanMs <= 90 * dayMs) return "3M";
  if (spanMs <= 365 * dayMs) return "1Y";
  if (spanMs <= 5 * 365 * dayMs) return "5Y";
  return "MAX";
}

function normalizeBenchmarkSeries(chart, startingEquity = 10000) {
  const bars = extractChartBars(chart);
  if (bars.length < 2) return [];

  const normalizedPoints = bars.map((bar, index) => {
    const close = Number(bar?.close);
    const timeMs = Date.parse(String(bar?.time || ""));
    if (!Number.isFinite(close) || close <= 0 || !Number.isFinite(timeMs)) return null;
    return {
      id: `benchmark-${index}`,
      time: new Date(timeMs).toISOString(),
      timeMs,
      close,
    };
  }).filter(Boolean);

  if (normalizedPoints.length < 2) return [];

  const firstClose = Number(normalizedPoints[0]?.close);
  if (!Number.isFinite(firstClose) || firstClose <= 0) return [];

  const valuePoints = normalizedPoints.map((point) => {
    const value = Number(startingEquity) * (point.close / firstClose);
    return {
      ...point,
      value,
      equity: value,
    };
  });

  const firstValue = Number(valuePoints[0]?.value);
  if (!Number.isFinite(firstValue) || firstValue <= 0) return [];

  return valuePoints.map((point) => {
    const pctChange = ((point.value - firstValue) / firstValue) * 100;
    return {
      ...point,
      time: point.time,
      value: point.value,
      pctChange,
      changeFromStart: point.value - firstValue,
      pnl: point.value - firstValue,
    };
  });
}

function readBenchmarkPointValue(point) {
  const value = Number(point?.equity ?? point?.value);
  return Number.isFinite(value) ? value : null;
}

function readBenchmarkPointPctChange(point, baselineValue = null) {
  const pctChange = Number(point?.pctChange);
  if (Number.isFinite(pctChange)) return pctChange;

  const value = readBenchmarkPointValue(point);
  if (!Number.isFinite(value) || !Number.isFinite(baselineValue) || baselineValue <= 0) {
    return null;
  }

  return ((value / baselineValue) - 1) * 100;
}

function sliceBenchmarkBarsToVisibleWindow(chart, visibleStart, visibleEnd) {
  const bars = extractChartBars(chart);
  if (!bars.length) return [];

  const normalizedBars = bars
    .map((bar) => {
      const timeMs = Date.parse(String(bar?.time || ""));
      return Number.isFinite(timeMs) ? { ...bar, timeMs } : null;
    })
    .filter(Boolean);

  const withinWindow = normalizedBars.filter((bar) => bar.timeMs >= visibleStart && bar.timeMs <= visibleEnd);
  const priorBar = [...normalizedBars].reverse().find((bar) => bar.timeMs <= visibleStart) || null;

  const result = [];
  if (priorBar) result.push(priorBar);
  withinWindow.forEach((bar) => {
    if (!result.some((existing) => existing.timeMs === bar.timeMs)) {
      result.push(bar);
    }
  });

  if (result.length >= 2) return result.map(({ timeMs, ...bar }) => bar);

  const nearestBars = normalizedBars
    .map((bar) => ({
      ...bar,
      distance: Math.min(Math.abs(bar.timeMs - visibleStart), Math.abs(bar.timeMs - visibleEnd)),
    }))
    .sort((a, b) => a.distance - b.distance)
    .slice(0, 12)
    .sort((a, b) => a.timeMs - b.timeMs);

  return nearestBars.map(({ timeMs, distance, ...bar }) => bar);
}

function buildPortfolioBenchmarkChart(positionCharts, positions, visibleStart, visibleEnd, debugContext = null) {
  const normalizedPositions = Array.isArray(positions) ? positions : [];
  const chartEntries = normalizedPositions.map((position) => {
    const symbol = String(position?.symbol || "").trim().toUpperCase();
    const chart = positionCharts?.[symbol] || null;
    const bars = Array.isArray(chart?.bars) ? chart.bars : [];
    const qty = Math.abs(Number(position?.qty) || 0);
    const entryTimeMs = Number(chart?.entryTimeMs);
    const avgEntryPrice = Number(position?.avgEntryPrice);
    const marketValue = Number(position?.marketValue);
    const unrealized = Number(position?.unrealizedPl);
    const inferredCostBasis = Number.isFinite(marketValue) && Number.isFinite(unrealized)
      ? marketValue - unrealized
      : null;
    const costBasis = Number.isFinite(qty) && qty > 0 && Number.isFinite(avgEntryPrice) && avgEntryPrice > 0
      ? qty * avgEntryPrice
      : Number.isFinite(inferredCostBasis) && inferredCostBasis > 0
        ? inferredCostBasis
        : null;
    const filteredBars = buildBrokerPositionCurveBars({
      position,
      rawBars: bars,
      entryTimeMs,
      requestedStartMs: Number.isFinite(visibleStart) ? visibleStart : null,
      nowMs: Number.isFinite(visibleEnd) ? visibleEnd : Date.now(),
      debugContext,
    }).map((bar) => ({ timeMs: bar.barTime, close: Number(bar.close), source: bar.source || "market_bar_after_position_open" }));
    return {
      symbol,
      qty,
      costBasis,
      entryTimeMs: Number.isFinite(entryTimeMs) ? entryTimeMs : null,
      bars: filteredBars,
    };
  }).filter((entry) => entry.qty > 0 && Number.isFinite(entry.costBasis) && entry.costBasis > 0 && entry.bars.length);

  const logDebug = (chartBars) => {
    if (!debugContext) return;
    const compactBars = Array.isArray(chartBars) ? chartBars : [];
    const includedSymbolsByPoint = compactBars.map((bar) => ({
      time: bar.time,
      symbols: Array.isArray(bar.symbols) ? bar.symbols : [],
    }));
    import.meta.env.DEV && console.log("[Rayla portfolio timeframe debug]", {
      timeframe: debugContext.timeframe || "MAX",
      view: debugContext.view || "Portfolio",
      positionSymbols: normalizedPositions.map((position) => String(position?.symbol || "").trim().toUpperCase()).filter(Boolean),
      resolvedOpenTimes: chartEntries.map((entry) => ({
        symbol: entry.symbol,
        openTime: formatDebugIso(entry.entryTimeMs),
      })),
      includedSnapshotsCount: compactBars.length,
      includedSymbolsByPoint,
      firstPoint: compactBars[0] || null,
      lastPoint: compactBars[compactBars.length - 1] || null,
      currentPositionsUsedOnlyForCurrentPoint: compactBars.every((bar) => (
        Array.isArray(bar.sources)
          ? !bar.sources.some((source) => source === "broker_current_point") || bar.timeMs === visibleEnd
          : true
      )),
    });
  };

  if (!chartEntries.length) {
    logDebug([]);
    return null;
  }

  const timeMap = new Map();
  chartEntries.forEach((entry) => {
    entry.bars.forEach((bar) => {
      const existing = timeMap.get(bar.timeMs) || {};
      existing[entry.symbol] = {
        close: bar.close,
        source: bar.source || "market_bar_after_position_open",
      };
      timeMap.set(bar.timeMs, existing);
    });
  });

  const sortedTimes = Array.from(timeMap.keys()).sort((a, b) => a - b);
  if (sortedTimes.length < 2) {
    logDebug([]);
    return null;
  }

  const latestCloseBySymbol = {};
  const bars = [];
  sortedTimes.forEach((timeMs) => {
    const updates = timeMap.get(timeMs) || {};
    Object.entries(updates).forEach(([symbol, point]) => {
      latestCloseBySymbol[symbol] = Number(point?.close);
    });
    let totalCloseValue = 0;
    let totalCostBasis = 0;
    let contributing = 0;
    const symbols = [];
    const sources = [];
    chartEntries.forEach((entry) => {
      if (Number.isFinite(entry.entryTimeMs) && timeMs < entry.entryTimeMs) return;
      const close = latestCloseBySymbol[entry.symbol];
      if (!Number.isFinite(close)) return;
      totalCloseValue += close * entry.qty;
      totalCostBasis += entry.costBasis;
      contributing += 1;
      symbols.push(entry.symbol);
      const source = updates[entry.symbol]?.source || null;
      if (source) sources.push(source);
    });
    if (contributing > 0 && Number.isFinite(totalCloseValue) && totalCloseValue > 0 && Number.isFinite(totalCostBasis) && totalCostBasis > 0) {
      bars.push({
        time: new Date(timeMs).toISOString(),
        timeMs,
        close: totalCloseValue,
        costBasis: totalCostBasis,
        symbols,
        sources,
      });
    }
  });

  logDebug(bars);

  if (bars.length < 2) return null;

  return {
    symbol: "Broker Portfolio Benchmark",
    rangeMode: "portfolio_benchmark",
    bars,
  };
}

function getOpenPositionCostBasis(positions) {
  return (Array.isArray(positions) ? positions : []).reduce((sum, position) => {
    const qty = Math.abs(Number(position?.qty));
    const avg = Number(position?.avgEntryPrice);
    if (Number.isFinite(qty) && Number.isFinite(avg) && qty > 0 && avg > 0) {
      return sum + qty * avg;
    }

    const marketValue = Number(position?.marketValue);
    const unrealized = Number(position?.unrealizedPl);
    const inferredBasis = marketValue - unrealized;
    return Number.isFinite(inferredBasis) && inferredBasis > 0 ? sum + inferredBasis : sum;
  }, 0);
}

function getSnapshotPositionTradeType(position) {
  return normalizePositionType(position?.trade_type || position?.tradeType || position?.position_type || position?.positionType);
}

function snapshotPositionMatchesView(position, view = "portfolio") {
  const tradeType = getSnapshotPositionTradeType(position);
  if (view === "holdings") return tradeType === "investment";
  if (view === "active") return tradeType === "day_trade" || tradeType === "swing_trade";
  return true;
}

function normalizePortfolioSnapshotRows(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => {
      const timestampMs = Date.parse(String(row?.timestamp || row?.created_at || ""));
      if (!Number.isFinite(timestampMs)) return null;
      const positions = Array.isArray(row?.positions_json)
        ? row.positions_json
        : Array.isArray(row?.positions)
          ? row.positions
          : [];
      return {
        id: row?.id || `${timestampMs}`,
        timestamp: new Date(timestampMs).toISOString(),
        timestampMs,
        source: row?.source || "broker_refresh",
        timeframe: row?.timeframe || "snapshot",
        totalMarketValue: Number(row?.total_market_value ?? 0),
        cash: Number(row?.cash ?? 0),
        equity: Number(row?.equity ?? 0),
        dayPl: Number(row?.day_pl ?? 0),
        positionsCount: Number(row?.positions_count ?? positions.length ?? 0),
        positions,
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.timestampMs - b.timestampMs);
}

function getPortfolioChartVisibleTimeRange(snapshots, points, range, nowMs = Date.now()) {
  const endMs = Number.isFinite(Number(nowMs)) ? Number(nowMs) : Date.now();
  const rangeMs = getChartSelectionWindowMs(range);
  const pointTimes = (Array.isArray(points) ? points : [])
    .map((point) => Number(point?.timeMs))
    .filter((timestampMs) => Number.isFinite(timestampMs));
  const requestedStartMs = Number.isFinite(rangeMs) && rangeMs > 0 ? endMs - rangeMs : null;
  const selectedPointTimes = requestedStartMs == null
    ? pointTimes
    : pointTimes.filter((timestampMs) => timestampMs >= requestedStartMs && timestampMs <= endMs);
  const domainTimes = selectedPointTimes.length ? selectedPointTimes : pointTimes;

  let firstMs = Math.min(...domainTimes);
  let lastMs = Math.max(...domainTimes);
  if (!Number.isFinite(firstMs) || !Number.isFinite(lastMs)) {
    const snapshotTimes = normalizePortfolioSnapshotRows(snapshots)
      .map((snapshot) => snapshot.timestampMs)
      .filter((timestampMs) => Number.isFinite(timestampMs));
    firstMs = Math.min(...snapshotTimes);
    lastMs = Math.max(...snapshotTimes);
  }
  if (!Number.isFinite(firstMs) || !Number.isFinite(lastMs)) return null;
  if (firstMs === lastMs) {
    const padMs = 12 * 60 * 60 * 1000;
    return { fromMs: firstMs - padMs, toMs: lastMs + padMs };
  }
  const dataSpanMs = lastMs - firstMs;
  const minPadMs = Number.isFinite(rangeMs) && rangeMs <= DAY_MS ? 15 * 60 * 1000 : 60 * 60 * 1000;
  const padMs = Math.max(dataSpanMs * 0.05, minPadMs);
  return { fromMs: firstMs - padMs, toMs: lastMs + padMs };
}

function buildPortfolioChartFromSnapshots(snapshots, requestedStartMs, requestedEndMs, view = "portfolio", debugLabel = view, intentOverrides = null) {
  const startMs = Number.isFinite(Number(requestedStartMs)) ? Number(requestedStartMs) : null;
  const endMs = Number.isFinite(Number(requestedEndMs)) ? Number(requestedEndMs) : Date.now();
  const normalizedRows = normalizePortfolioSnapshotRows(snapshots);
  const discardReasons = {};
  const addDiscard = (reason) => {
    discardReasons[reason] = (discardReasons[reason] || 0) + 1;
  };
  const rows = normalizedRows
    .filter((snapshot) => {
      const keep = (
      (startMs == null || snapshot.timestampMs >= startMs)
      && snapshot.timestampMs <= endMs
      );
      if (!keep) addDiscard("outside_selected_window");
      return keep;
    });

  const bars = rows.map((snapshot) => {
    const filteredPositions = (Array.isArray(snapshot.positions) ? snapshot.positions : [])
      .filter((position) => {
        if (!intentOverrides || view === "portfolio") return snapshotPositionMatchesView(position, view);
        const key = getPositionIntentKey(String(position?.symbol || ""));
        const override = key ? intentOverrides[key] : null;
        const effectiveType = override?.tradeType || override?.trade_type || override?.positionType || position?.trade_type || position?.tradeType;
        return snapshotPositionMatchesView({ ...position, trade_type: effectiveType }, view);
      });
    if (view !== "portfolio" && !filteredPositions.length) {
      addDiscard(view === "portfolio" ? "snapshot_has_no_positions" : `snapshot_has_no_${view}_positions`);
      return null;
    }

    let close = 0;
    let costBasis = 0;
    const symbols = [];
    filteredPositions.forEach((position) => {
      const symbol = String(position?.symbol || "").trim().toUpperCase();
      const marketValue = Number(position?.market_value ?? position?.marketValue ?? 0);
      const qty = Math.abs(Number(position?.qty ?? 0));
      const avgEntryPrice = Number(position?.avg_entry_price ?? position?.avgEntryPrice ?? 0);
      const unrealizedPl = Number(position?.unrealized_pl ?? position?.unrealizedPl ?? 0);
      const inferredBasis = marketValue - unrealizedPl;
      const positionBasis = Number.isFinite(qty) && qty > 0 && Number.isFinite(avgEntryPrice) && avgEntryPrice > 0
        ? qty * avgEntryPrice
        : Number.isFinite(inferredBasis) && inferredBasis > 0
          ? inferredBasis
          : null;
      if (Number.isFinite(marketValue)) close += marketValue;
      if (Number.isFinite(positionBasis) && positionBasis > 0) costBasis += positionBasis;
      if (symbol) symbols.push(symbol);
    });

    if (view === "portfolio") {
      const snapshotEquity = Number(snapshot.equity);
      const snapshotMarketValue = Number(snapshot.totalMarketValue);
      const snapshotCash = Number(snapshot.cash);
      const accountValue = Number.isFinite(snapshotEquity) && snapshotEquity > 0
        ? snapshotEquity
        : Number.isFinite(snapshotMarketValue) && Number.isFinite(snapshotCash) && (snapshotMarketValue + snapshotCash) > 0
          ? snapshotMarketValue + snapshotCash
          : Number.isFinite(snapshotMarketValue) && snapshotMarketValue > 0
            ? snapshotMarketValue
            : close;
      if (Number.isFinite(accountValue) && accountValue > 0) {
        close = accountValue;
      }
      if (!Number.isFinite(costBasis) || costBasis <= 0) {
        costBasis = close;
      }
    }

    if (!Number.isFinite(close) || close <= 0) {
      addDiscard("invalid_market_value");
      return null;
    }
    if (!Number.isFinite(costBasis) || costBasis <= 0) {
      addDiscard("invalid_cost_basis");
      return null;
    }
    return {
      time: snapshot.timestamp,
      timeMs: snapshot.timestampMs,
      close,
      costBasis,
      symbols,
      sources: [snapshot.source || "portfolio_snapshot"],
      positionsCount: filteredPositions.length,
    };
  }).filter(Boolean);

  const audit = {
    chart: debugLabel,
    timeframe: startMs == null ? "ALL" : `${new Date(startMs).toISOString()}..${new Date(endMs).toISOString()}`,
    view,
    snapshotTable: "portfolio_snapshots",
    snapshotTableCount: normalizedRows.length,
    firstSnapshotTimestamp: normalizedRows[0]?.timestamp || null,
    lastSnapshotTimestamp: normalizedRows[normalizedRows.length - 1]?.timestamp || null,
    rowsReturned: normalizedRows.length,
    rowsAfterFiltering: rows.length,
    discardedRowsByReason: discardReasons,
    includedSnapshotsCount: bars.length,
    includedSymbolsByPoint: bars.map((bar) => ({ time: bar.time, symbols: bar.symbols })),
    firstPoint: bars[0] || null,
    lastPoint: bars[bars.length - 1] || null,
    finalChartPoints: bars.length,
    currentPositionsUsedOnlyForCurrentPoint: false,
  };
  if (typeof window !== "undefined") {
    window.__raylaSnapshotAudit = {
      ...(window.__raylaSnapshotAudit || {}),
      [debugLabel]: audit,
    };
  }
  if (bars.length < 2) return null;

  return {
    symbol: "Portfolio Snapshot History",
    rangeMode: "portfolio_snapshots",
    returnMode: view === "portfolio" ? "account_equity" : "position_cost_basis",
    bars,
  };
}

function buildOpenPositionReturnLinePoints(chart, costBasis) {
  const fallback = Number(costBasis);
  const bars = extractChartBars(chart);
  const firstAccountValue = chart?.returnMode === "account_equity"
    ? Number(bars.find((bar) => Number.isFinite(Number(bar?.close)) && Number(bar?.close) > 0)?.close)
    : null;

  return bars
    .map((bar) => {
      const timeMs = getChartBarTimeMs(bar);
      const value = Number(bar?.close);
      const barBasis = Number(bar?.costBasis);
      const basis = Number.isFinite(firstAccountValue) && firstAccountValue > 0
        ? firstAccountValue
        : Number.isFinite(barBasis) && barBasis > 0 ? barBasis : fallback;
      if (!Number.isFinite(timeMs) || !Number.isFinite(value) || value <= 0) return null;
      if (!Number.isFinite(basis) || basis <= 0) return null;
      return {
        timeMs,
        value: ((value - basis) / basis) * 100,
        rawValue: value,
        costBasis: basis,
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.timeMs - b.timeMs);
}

function buildPeriodReturnFromChart(chart) {
  const bars = extractChartBars(chart);
  if (bars.length < 2) return null;
  const firstValue = Number(bars[0]?.close);
  const lastValue = Number(bars[bars.length - 1]?.close);
  if (!Number.isFinite(firstValue) || firstValue <= 0 || !Number.isFinite(lastValue) || lastValue <= 0) return null;
  const pnl = lastValue - firstValue;
  const returnPct = (pnl / firstValue) * 100;
  return { pnl, returnPct, firstValue, lastValue, barsCount: bars.length };
}

function calculateSeriesDrawdown(points) {
  let peak = null;
  let maxDrawdown = 0;
  (Array.isArray(points) ? points : []).forEach((point) => {
    const value = Number(point?.equity ?? point?.value);
    if (!Number.isFinite(value)) return;
    if (peak == null || value > peak) peak = value;
    if (peak > 0) {
      const drawdown = ((value - peak) / peak) * 100;
      if (drawdown < maxDrawdown) maxDrawdown = drawdown;
    }
  });
  return maxDrawdown;
}

const EQUITY_BENCHMARKS = {
  SPY: { symbol: "SPY", type: "stock" },
  QQQ: { symbol: "QQQ", type: "stock" },
  BTC: { symbol: "BTC", type: "crypto" },
  ETH: { symbol: "ETH", type: "crypto" },
};

function buildPercentScale(values, steps = 4) {
  if (!Array.isArray(values) || values.length < 2) return [];
  const max = Math.max(...values);
  const min = Math.min(...values);
  const range = max - min || 1;
  const paddedMax = max + range * 0.18;
  const paddedMin = min - range * 0.18;

  return Array.from({ length: steps }, (_, index) => {
    const ratio = index / (steps - 1 || 1);
    const y = 14 + (72 * ratio);
    const value = paddedMax - ((paddedMax - paddedMin) * ratio);
    return {
      y,
      label: `${value >= 0 ? "+" : ""}${value.toFixed(0)}%`,
    };
  });
}

function findNearestPointByTime(points, targetTimeMs) {
  if (!Array.isArray(points) || !points.length || !Number.isFinite(targetTimeMs)) return null;
  let nearest = points[0];
  let nearestDistance = Math.abs((nearest?.timeMs || 0) - targetTimeMs);
  for (let index = 1; index < points.length; index += 1) {
    const point = points[index];
    const distance = Math.abs((point?.timeMs || 0) - targetTimeMs);
    if (distance < nearestDistance) {
      nearest = point;
      nearestDistance = distance;
    }
  }
  return nearest;
}

function filterEquityCurvePointsByRange(points, range) {
  if (!Array.isArray(points) || !points.length) return points;
  if (range === "ALL") {
    const firstPoint = points[0];
    const firstPnl = Number(firstPoint?.pnl);
    const baselineEquity = Number.isFinite(firstPnl)
      ? Number(firstPoint.equity) - firstPnl
      : Number(firstPoint?.equity);
    if (!Number.isFinite(baselineEquity)) return points;
    const baselineTimeMs = Math.max(0, Number(firstPoint.timeMs || 0) - 1);
    return [
      {
        ...firstPoint,
        time: new Date(baselineTimeMs).toISOString(),
        timeMs: baselineTimeMs,
        value: baselineEquity,
        equity: baselineEquity,
        changeFromStart: 0,
        tradeId: null,
        tradeIds: [],
        source: "baseline",
        pnl: 0,
        timestampField: "range_baseline",
        tradeCount: 0,
        trade: null,
      },
      ...points,
    ];
  }
  const nowMs = Date.now();
  const todayStartMs = (() => {
    const date = new Date(nowMs);
    date.setHours(0, 0, 0, 0);
    return date.getTime();
  })();
  const todayEndMs = (() => {
    const date = new Date(nowMs);
    date.setHours(23, 59, 59, 999);
    return date.getTime();
  })();
  const endMs = range === "1D" ? todayEndMs : nowMs;
  const windowMs = (
    range === "1D" ? 24 * 60 * 60 * 1000
    : range === "1W" ? 7 * 24 * 60 * 60 * 1000
    : range === "1M" ? 30 * 24 * 60 * 60 * 1000
    : 90 * 24 * 60 * 60 * 1000
  );
  const startMs = range === "1D" ? todayStartMs : endMs - windowMs;
  const filtered = points.filter((point) => point.timeMs >= startMs && point.timeMs <= endMs);
  if (!filtered.length) return [];

  const previousPoint = [...points].reverse().find((point) => point.timeMs < startMs);
  if (previousPoint) {
    const previousEquity = Number(previousPoint.equity);
    if (Number.isFinite(previousEquity)) {
      return [
        {
          ...previousPoint,
          time: new Date(startMs).toISOString(),
          timeMs: startMs,
          value: previousEquity,
          equity: previousEquity,
          changeFromStart: 0,
          tradeId: null,
          tradeIds: [],
          source: "baseline",
          pnl: 0,
          timestampField: "range_baseline",
          tradeCount: 0,
          trade: null,
        },
        ...filtered,
      ];
    }
  }

  const firstPoint = filtered[0];
  const firstPnl = Number(firstPoint?.pnl);
  const baselineEquity = Number.isFinite(firstPnl)
    ? Number(firstPoint.equity) - firstPnl
    : Number(firstPoint?.equity);
  if (!Number.isFinite(baselineEquity)) return filtered;

  return [
    {
      ...firstPoint,
      time: new Date(Math.max(0, Math.min(startMs, firstPoint.timeMs - 1))).toISOString(),
      timeMs: Math.max(0, Math.min(startMs, firstPoint.timeMs - 1)),
      value: baselineEquity,
      equity: baselineEquity,
      changeFromStart: 0,
      tradeId: null,
      tradeIds: [],
      source: "baseline",
      pnl: 0,
      timestampField: "range_baseline",
      tradeCount: 0,
      trade: null,
    },
    ...filtered,
  ];
}

function buildEquityTimeScale(points, range) {
  if (!Array.isArray(points) || !points.length) return [];
  const firstTime = points[0]?.timeMs || 0;
  const lastTime = points[points.length - 1]?.timeMs || firstTime;
  const spanMs = Math.max(0, lastTime - firstTime);
  const count = Math.min(points.length, range === "1D" ? 4 : range === "1W" ? 5 : 6);
  const lastIndex = points.length - 1;
  const labels = [];
  const seen = new Set();

  for (let i = 0; i < count; i += 1) {
    const index = Math.round((lastIndex * i) / Math.max(1, count - 1));
    const point = points[index];
    if (!point) continue;
    const label = new Date(point.timeMs).toLocaleDateString([], (
      spanMs <= 24 * 60 * 60 * 1000
        ? { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }
        : spanMs <= 7 * 24 * 60 * 60 * 1000
          ? { month: "short", day: "numeric", hour: "numeric" }
          : spanMs <= 120 * 24 * 60 * 60 * 1000
            ? { month: "short", day: "numeric" }
            : { month: "short", year: "numeric" }
    ));
    if (seen.has(label)) continue;
    seen.add(label);
    labels.push({
      label,
      ratio: lastIndex === 0 ? 0 : index / lastIndex,
    });
  }

  return labels;
}

