                  <div className="listSubtext">
                    Qty {position.qty || "--"} · Avg {position.avgEntryPrice ? `$${Number(position.avgEntryPrice).toFixed(2)}` : "--"} · Value {position.marketValue ? formatCurrency(position.marketValue) : "--"}
                  </div>
