function RaylaDropdown({
  value,
  onChange,
  options,
  width = "100%",
  minWidth,
  disabled = false,
  ariaLabel,
  size = "default",
  buttonLabel,
  renderOption,
  menuHeader = null,
  menuWidth,
  menuAlign = "left",
  useFixed = false,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [menuPos, setMenuPos] = useState(null);
  const rootRef = useRef(null);
  const menuRef = useRef(null);
  const buttonRef = useRef(null);
  const optionRefs = useRef([]);
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const selectedOption = options[selectedIndex] || options[0] || { value, label: value };

  useEffect(() => {
    if (!isOpen) return undefined;
    const handlePointerDown = (event) => {
      if (!rootRef.current?.contains(event.target) && !menuRef.current?.contains(event.target)) setIsOpen(false);
    };
    const handleEscape = (event) => {
      if (event.key === "Escape") {
        setIsOpen(false);
        buttonRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || !useFixed) return undefined;
    const close = () => setIsOpen(false);
    window.addEventListener("scroll", close, true);
    window.addEventListener("resize", close);
    return () => {
      window.removeEventListener("scroll", close, true);
      window.removeEventListener("resize", close);
    };
  }, [isOpen, useFixed]);

  // Compute viewport-anchored position after the DOM commits so getBoundingClientRect
  // always reflects the live layout. useLayoutEffect runs before the browser paints,
  // so the user never sees an intermediate unpositioned state.
  useEffect(() => {
    if (!isOpen || !useFixed || !buttonRef.current) {
      if (!isOpen) setMenuPos(null);
      return;
    }
    const rect = buttonRef.current.getBoundingClientRect();
    const mw = menuWidth || rect.width;
    setMenuPos({
      position: "fixed",
      top: rect.bottom + 7,
      left: menuAlign === "right" ? rect.right - mw : rect.left,
      right: "auto",
      width: mw,
      zIndex: 9999,
    });
  }, [isOpen, useFixed, menuWidth, menuAlign]);

  const openMenu = (index = selectedIndex) => {
    if (disabled) return;
    setIsOpen(true);
    window.requestAnimationFrame(() => {
      optionRefs.current[index]?.focus({ preventScroll: true });
    });
  };

  const selectOption = (option) => {
    if (!option || disabled) return;
    onChange(option.value);
    setIsOpen(false);
    buttonRef.current?.focus();
  };

  const handleButtonKeyDown = (event) => {
    if (["ArrowDown", "Enter", " "].includes(event.key)) {
      event.preventDefault();
      openMenu(selectedIndex);
    }
    if (event.key === "ArrowUp") {
      event.preventDefault();
      openMenu(Math.max(0, selectedIndex - 1));
    }
  };

  const handleOptionKeyDown = (event, index) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      optionRefs.current[Math.min(options.length - 1, index + 1)]?.focus();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      optionRefs.current[Math.max(0, index - 1)]?.focus();
    } else if (event.key === "Home") {
      event.preventDefault();
      optionRefs.current[0]?.focus();
    } else if (event.key === "End") {
      event.preventDefault();
      optionRefs.current[options.length - 1]?.focus();
    } else if (event.key === "Escape") {
      event.preventDefault();
      setIsOpen(false);
      buttonRef.current?.focus();
    }
  };

  return (
    <div
      ref={rootRef}
      className={`raylaDropdown${isOpen ? " open" : ""}${disabled ? " disabled" : ""}${size === "compact" ? " compact" : ""}`}
      style={{ width, minWidth: minWidth ?? width }}
    >
      <button
        ref={buttonRef}
        type="button"
        className="raylaDropdownButton"
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-label={ariaLabel}
        disabled={disabled}
        onClick={() => isOpen ? setIsOpen(false) : openMenu()}
        onKeyDown={handleButtonKeyDown}
      >
        <span>{buttonLabel || selectedOption.label}</span>
        <span className="raylaDropdownChevron" aria-hidden="true" />
      </button>
      {isOpen && (() => {
        const menuEl = (
          <div
            ref={menuRef}
            className="raylaDropdownMenu"
            role="listbox"
            aria-label={ariaLabel}
            style={useFixed && menuPos ? menuPos : {
              width: menuWidth,
              left: menuWidth && menuAlign === "right" ? "auto" : undefined,
              right: menuWidth && menuAlign === "right" ? 0 : undefined,
            }}
          >
            {menuHeader}
            {options.map((option, index) => {
              const active = option.value === value;
              return (
                <button
                  key={option.value}
                  ref={(node) => { optionRefs.current[index] = node; }}
                  type="button"
                  className={`raylaDropdownOption${active ? " active" : ""}`}
                  role="option"
                  aria-selected={active}
                  onClick={() => selectOption(option)}
                  onKeyDown={(event) => handleOptionKeyDown(event, index)}
                >
                  {renderOption ? renderOption(option, active) : option.label}
                </button>
              );
            })}
          </div>
        );
        return useFixed ? createPortal(menuEl, document.body) : menuEl;
      })()}
    </div>
  );
}

