function formatBillingDate(value) {
  if (!value) return "";
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return "";
  return date.toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" });
}

function getSubscriptionPresentation(subscription) {
  const status = String(subscription?.status || "inactive");
  if (subscription?.plan_key === "rayla_discount" && status === "active") return { label: "Discount", tone: "blue", detail: "Discount access is active." };
  if (status === "active") return { label: "Active", tone: "green", detail: "Your Rayla subscription is active." };
  if (status === "trialing") return { label: "Trial", tone: "blue", detail: subscription?.trial_ends_at ? `Trial ends ${formatBillingDate(subscription.trial_ends_at)}.` : "Your Rayla trial is active." };
  if (status === "past_due") return { label: "Past due", tone: "amber", detail: "Update billing in Stripe to keep access current." };
  if (status === "checkout_started") return { label: "Checkout started", tone: "blue", detail: "Finish checkout in Stripe to activate billing." };
  if (status === "canceled") return { label: "Canceled", tone: "neutral", detail: "Your previous Rayla subscription is canceled." };
  if (status === "incomplete" || status === "incomplete_expired" || status === "unpaid") return { label: "Needs attention", tone: "amber", detail: "Open billing to complete or update payment." };
  return { label: "Not subscribed", tone: "neutral", detail: "Start checkout when you are ready." };
}

function hasActiveRaylaSubscription(subscription) {
  const status = String(subscription?.status || "inactive").toLowerCase();
  if (status === "active") return true;
  if (status !== "trialing") return false;
  if (!subscription?.trial_ends_at) return true;
  const trialEndMs = new Date(subscription.trial_ends_at).getTime();
  return !Number.isFinite(trialEndMs) || trialEndMs > Date.now();
}

// Returns true when the locally-cached user_subscriptions row is likely stale
// relative to Stripe and should be reconciled via stripe-sync-subscription
// before we decide the paywall gate. Handles the "trial ended weeks ago but
// row is still trialing" case observed in production when a subscription
// lifecycle webhook was missed.
function shouldReconcileStripeSubscription(subscription) {
  if (!subscription) return false;
  if (subscription.billing_provider && subscription.billing_provider !== "stripe") return false;
  if (subscription.plan_key === "rayla_discount") return false;
  if (!subscription.stripe_subscription_id) return false;
  const status = String(subscription.status || "").toLowerCase();
  if (status === "trialing" && subscription.trial_ends_at) {
    const trialEndMs = new Date(subscription.trial_ends_at).getTime();
    if (Number.isFinite(trialEndMs) && trialEndMs <= Date.now()) return true;
  }
  if (status === "checkout_started") {
    const updatedMs = new Date(subscription.updated_at || subscription.created_at || 0).getTime();
    if (Number.isFinite(updatedMs) && Date.now() - updatedMs > 10 * 60 * 1000) return true;
  }
  return false;
}

function getBillingBadgeStyle(tone) {
  if (tone === "green") return { background: "rgba(74,222,128,0.1)", color: "#86efac" };
  if (tone === "blue") return { background: "rgba(124,196,255,0.1)", color: "#bae6fd" };
  if (tone === "amber") return { background: "rgba(251,191,36,0.11)", color: "#fde68a" };
  return { background: "rgba(148,163,184,0.1)", color: "#cbd5e1" };
}

