async function handleChangePasswordSubmit() {
  if (passwordModalSaving) return;
  const newPw = passwordModalNew;
  const confirmPw = passwordModalConfirm;
  const missing = [];
  if (newPw.length < 8) missing.push("at least 8 characters");
  if (!/[A-Z]/.test(newPw)) missing.push("an uppercase letter");
  if (!/[0-9]/.test(newPw)) missing.push("a number");
  if (!/[^A-Za-z0-9]/.test(newPw)) missing.push("a special character");
  if (missing.length > 0) {
    showToast(`Password must include ${missing.join(", ")}.`, "error");
    return;
  }
  if (newPw !== confirmPw) {
    showToast("Passwords do not match.", "error");
    return;
  }
  setPasswordModalSaving(true);
  try {
    const { error } = await supabase.auth.updateUser({ password: newPw });
    if (error) {
      showToast(error.message || "Could not update password.", "error");
      return;
    }
    if (recoveryScreen === "form") {
      setRecoveryScreen("success");
      setPasswordModalNew("");
      setPasswordModalConfirm("");
      supabase.auth.signOut({ scope: "global" }).catch((err) => {
        console.error("[recovery] sign_out_after_update_failed", err?.message || err);
      });
      return;
    }
    setPasswordModalOpen(false);
    setPasswordModalNew("");
    setPasswordModalConfirm("");
    showToast("Password updated.", "success");
  } catch (err) {
    showToast(err instanceof Error ? err.message : "Could not update password.", "error");
  } finally {
    setPasswordModalSaving(false);
  }
}

async function handleDeleteAccount() {
  setDeleteAccountModalOpen(false);
  setDeleteAccountConfirmText("");

  try {
    const {
      data: { session: currentSession },
    } = await supabase.auth.getSession();

    const accessToken = currentSession?.access_token;
    if (!accessToken) {
      throw new Error("No active session found.");
    }

    const { data, error } = await supabase.functions.invoke("delete-account", {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    import.meta.env.DEV && console.log("[delete-account] invoke_result", {
      invokeError: error?.message || null,
      data,
    });

    if (error) {
      throw new Error(error.message || "Delete account failed.");
    }

    if (!data?.ok) {
      const detailSuffix = data?.details ? ` (${data.details})` : "";
      throw new Error(`Delete account failed [${data?.stage || "unknown"}]: ${data?.error || "Unknown error"}${detailSuffix}`);
    }

    const { error: signOutError } = await supabase.auth.signOut({ scope: "local" });
    if (signOutError) {
      console.error("[delete-account] local_sign_out_failed_after_success", signOutError.message || signOutError);
    }

    setSession(null);
    setUser(null);
    setProfile(null);
    setTrades([]);
    setHotColdReport(null);
    setRaylaResponse("");
    const deletingUserId = currentSession?.user?.id;
    localStorage.removeItem(getUserScopedStorageKey(SIMULATION_STORAGE_KEYS.tradeHistory, deletingUserId));
    localStorage.removeItem(getUserScopedStorageKey(SIMULATION_STORAGE_KEYS.closedTrade, deletingUserId));
    localStorage.removeItem(getUserScopedStorageKey(SIMULATION_STORAGE_KEYS.balance, deletingUserId));
    localStorage.removeItem("rayla_sim_open_position");
    localStorage.removeItem(RAYLA_COACH_PROFILE_STORAGE_KEY);
    localStorage.removeItem("rayla-visited");
    sessionStorage.removeItem("rayla-intel-report");
    showToast(data?.message || "Account deleted successfully.", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : "Delete account failed.";
    console.error("[delete-account] frontend_failure", error);
    showToast(message, "error");
  }
}

